window.TADABBUR_SAFFAT = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة الصافّات (٣٧)، سورةٌ مكّيّةٌ محورُها توحيدُ الله وتنزيهُه، وإثباتُ البعثِ ومشاهدُ القيامة، وقصصُ الأنبياء (نوح، إبراهيم وذبحُ ابنه، موسى وهارون، إلياس، لوط، يونس)، والردُّ على مزاعمِ المشركين في الملائكةِ والولد؛ فيها «وإن جندنا لهم الغالبون» و«سلام على المرسلين». بُدئت بالقسمِ بالصافّات. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":37,"name":"الصافات","total_ayahs":182,"audio":[1,4,24,61,79,102,107,125,143,182],"passages":[{"title":"القسمُ بالصافّاتِ على التوحيد، وحفظُ السماءِ من الشياطين","range":[1,10],"theme":"القسمُ بالملائكةِ الصافّةِ الزاجرةِ التاليةِ على أنّ الإله واحد، وأنه ربُّ السماواتِ والمشارق، وتزيينُ السماءِ بالكواكبِ وحفظُها من كلِّ شيطانٍ مارد، وعجزُ الشياطينِ عن استراقِ الوحي","verses":[{"n":1,"reflection":{"text":"«والصافات صفا» — أقسم الله بالملائكةِ الصافّةِ في عبادتها صفوفًا؛ ففي هذا تعظيمُ شأنِ الملائكةِ وعبادتها المنتظمة؛ فاقتدِ بالملائكةِ في انتظامِ العبادةِ وإتمامِ الصفوفِ في الصلاة، فالصفُّ المنتظمُ من تمامِ العبادة، فأتمَّ صفوفك في الصلاة اقتداءً بالملائكة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالملائكةِ في انتظامِ العبادةِ وإتمامِ الصفوف."},"action":{"text":"اقتدِ بالملائكةِ في انتظامِ العبادةِ وإتمامِ الصفوف، فقد أقسم الله بها صافّةً في عبادتها «والصافات صفا»؛ فأتمَّ صفوفك في الصلاةِ وسدَّ الفُرَجَ وحاذِ بين المناكب؛ فإتمامُ الصفِّ وتسويتُه من تمامِ الصلاة؛ واجعل عبادتك منتظمةً خاشعةً كعبادةِ الملائكة؛ فمن أتمَّ الصفوفَ وأحسن عبادته اقتداءً بالملائكةِ نال محبّةَ الله؛ فالتراصُّ في الصفوفِ وإحسانُ العبادةِ من علاماتِ التعظيمِ لله."}},{"n":2,"reflection":{"text":"«فالزاجرات زجرا» — والملائكةِ التي تزجر السحابَ وتسوقه، أو تزجر عن المعاصي؛ ففي هذا تقريرُ قيامِ الملائكةِ بأمرِ الله؛ فاعلم أنّ الملائكةَ تنفّذ أمرَ الله، فكن أنت مطيعًا لله كطاعةِ الملائكة، فالمخلوقاتُ منقادةٌ لأمرِ الله، فكن من المنقادين الطائعين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانقيادُ لأمرِ الله كطاعةِ الملائكة."},"action":{"text":"انقد لأمرِ الله وأطعه كطاعةِ الملائكةِ التي تنفّذ أمره وتزجر بما أُمِرت به «فالزاجرات زجرا»؛ فالملائكةُ لا يعصون الله ما أمرهم ويفعلون ما يُؤمَرون؛ فاقتدِ بهم في الطاعةِ والانقيادِ التامّ لأمرِ الله؛ فاجعل امتثالك لأوامرِ الله واجتنابك لنواهيه دأبك؛ فمن أطاع الله طاعةً تامّةً كالملائكةِ نال رضاه؛ فالكونُ كلُّه منقادٌ لأمرِ الله؛ فكن من المنقادين الطائعين، لا من المتمرّدين العاصين؛ فطاعةُ الله سبيلُ السعادةِ والفلاح."}},{"n":3,"reflection":{"text":"«فالتاليات ذكرا» — والملائكةِ التي تتلو ذكرَ الله وكتابه؛ ففي هذا شرفُ تلاوةِ الذكر؛ فاقتدِ بالملائكةِ في تلاوةِ ذكرِ الله وكتابه، فتلاوةُ القرآنِ والذكرِ من أشرفِ العبادات، فاعمر لسانك بتلاوةِ القرآنِ وذكرِ الله اقتداءً بالملائكة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالملائكةِ في تلاوةِ الذكرِ والقرآن."},"action":{"text":"اقتدِ بالملائكةِ في تلاوةِ ذكرِ الله وكتابه، فقد أقسم الله بها تاليةً للذكر «فالتاليات ذكرا»؛ فاعمر لسانك وقلبك بتلاوةِ القرآنِ وذكرِ الله؛ فتلاوةُ القرآنِ والذكرِ من أشرفِ العباداتِ وأحبّها إلى الله؛ فاجعل لك وردًا يوميًّا من تلاوةِ القرآن، وأكثر من ذكرِ الله في كلِّ حين؛ فمن عمر وقته بتلاوةِ الذكرِ اقتداءً بالملائكةِ نال شرفَ صحبةِ القرآنِ وأنسَ الذكر؛ فالذكرُ حياةُ القلوب، والتلاوةُ نورٌ وشفاء؛ فلا تدع لسانك يجفّ من ذكرِ الله وتلاوةِ كتابه."}},{"n":4,"reflection":{"text":"«إن إلهكم لواحد» — إنّ معبودكم بحقٍّ واحدٌ لا شريكَ له؛ ففي هذا تقريرُ التوحيدِ (جوابُ القسم)؛ فوحّد الله في عبادتك، فهو الإلهُ الواحدُ لا شريكَ له، فأخلص له العبادةَ والدعاءَ والتوكّل، فالتوحيدُ أصلُ الدينِ وغايةُ الخلق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله في العبادة، فهو الإلهُ الواحد."},"action":{"text":"وحّد الله في عبادتك، فهو الإلهُ الواحدُ الذي لا شريكَ له «إن إلهكم لواحد»؛ فأخلص له العبادةَ والدعاءَ والخوفَ والرجاءَ والتوكّل؛ ولا تجعل له شريكًا في شيءٍ من العبادة؛ فالتوحيدُ أصلُ الدينِ وغايةُ الخلق؛ فحقّق التوحيدَ في قلبك ولسانك وعملك؛ فمن وحّد الله اهتدى وسعد، ومن أشرك ضلّ وشقي؛ فاعتقد أنّ إلهك واحدٌ لا شريكَ له، واعبده وحده؛ فهو المستحقُّ للعبادةِ دون سواه؛ فالعبادةُ كلُّها حقٌّ للإلهِ الواحد."}},{"n":5,"reflection":{"text":"«رب السماوات والأرض وما بينهما ورب المشارق» — هو ربُّ السماواتِ والأرضِ وما بينهما، وربُّ مشارقِ الشمسِ ومغاربها؛ ففي هذا تقريرُ ربوبيةِ الله الشاملة؛ فاعبد ربَّ السماواتِ والأرضِ والمشارق، فمن كان ربًّا لكلِّ شيءٍ فهو المستحقُّ للعبادة، فأفرده بالعبادةِ كما تفرّد بالربوبية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عبادةُ ربِّ السماواتِ والأرضِ المتفرّدِ بالربوبية."},"action":{"text":"اعبد الله ربَّ السماواتِ والأرضِ وما بينهما، وربَّ المشارقِ والمغارب، المتفرّدَ بالربوبيةِ الشاملة «رب السماوات والأرض وما بينهما ورب المشارق»؛ فمن كان ربًّا لكلِّ شيءٍ خالقًا رازقًا مدبّرًا فهو المستحقُّ للعبادةِ وحده؛ فأفرده بالعبادةِ كما تفرّد بالربوبية؛ فالإقرارُ بأنّ الله ربُّ كلِّ شيءٍ يوجب إفرادَه بالعبادة؛ فلا تعبد مع ربِّ العالمين سواه؛ فاجعل عبادتك كلَّها لله ربِّ السماواتِ والأرض؛ فمن عرف ربوبيةَ الله الشاملةَ أخلص له العبادةَ والخضوع؛ فهو ربُّ كلِّ شيءٍ ومليكه."}},{"n":6,"reflection":{"text":"«إنا زينا السماء الدنيا بزينة الكواكب» — إنا زيّنّا السماءَ الدنيا (القريبةَ) بزينةِ الكواكبِ والنجوم؛ ففي هذا تعدادُ نعمةِ تزيينِ السماء؛ فتأمّل جمالَ السماءِ المزيّنةِ بالنجوم، فمن زيّنها بهذا البهاءِ يستحقّ العبادةَ والحمد، فاجعل نظرك في السماءِ سبيلًا لتعظيمِ الخالقِ وشكره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في جمالِ السماءِ المزيّنةِ لتعظيمِ الخالق."},"action":{"text":"تأمّل جمالَ السماءِ الدنيا التي زيّنها الله بالكواكبِ والنجومِ اللامعة «إنا زينا السماء الدنيا بزينة الكواكب»؛ فهذا التزيينُ البديعُ آيةٌ على قدرةِ الله وحكمته وجماله؛ فمن زيّن السماءَ بهذا البهاءِ يستحقّ العبادةَ والحمدَ والتعظيم؛ فاجعل نظرك في السماءِ المزيّنةِ سبيلًا لتعظيمِ الخالقِ وشكره؛ فكلّما نظرت إلى السماءِ ليلًا ورأيت النجومَ فتذكّر عظمةَ خالقها ومزيّنها؛ فمن تأمّل بديعَ صنعِ الله في السماءِ ازداد إيمانًا وتعظيمًا؛ فالكونُ كتابٌ مفتوحٌ يدلّ على الله؛ فاقرأ آياته بعينِ الاعتبارِ والتعظيم."}},{"n":7,"reflection":{"text":"«وحفظا من كل شيطان مارد» — وجعلنا النجومَ حفظًا للسماءِ من كلِّ شيطانٍ متمرّدٍ يسترق السمع؛ ففي هذا حفظُ الله للسماءِ من الشياطين؛ فاطمئنَّ إلى أنّ الله يحفظ وحيَه من استراقِ الشياطين، فما بلغك من الوحي محفوظٌ نقيّ، فثِق بسلامةِ ما جاءك من عند الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ إلى حفظِ الله للوحي من الشياطين."},"action":{"text":"اطمئنَّ إلى أنّ الله يحفظ وحيَه وسماءه من كلِّ شيطانٍ مارِدٍ متمرّدٍ يحاول استراقَ السمع «وحفظا من كل شيطان مارد»؛ فقد جعل الله النجومَ والشهبَ حفظًا للسماءِ من الشياطين؛ فما بلغك من الوحيِ (القرآنِ والسنّة) محفوظٌ نقيٌّ لم يخالطه دخيلٌ من الشياطين؛ فتلقَّه بثقةٍ تامّةٍ في سلامته؛ فالله حافظٌ لوحيه ودينه؛ فمن أيقن بحفظِ الله للوحيِ تلقّاه بالتعظيمِ والاطمئنانِ إلى سلامته؛ فاعتمد على الوحيِ الصافي المحفوظ؛ ولا تشكّ في سلامةِ ما جاءك من عند الله؛ فالله تكفّل بحفظِ دينه ووحيه من كلِّ دخيل."}},{"n":8,"reflection":{"text":"«لا يسمعون إلى الملإ الأعلى ويقذفون من كل جانب» — لا يستطيع الشياطينُ الاستماعَ إلى الملائكةِ في الملأ الأعلى، ويُرجَمون من كلِّ جانب؛ ففي هذا عجزُ الشياطينِ عن استراقِ الوحي؛ فاعلم عجزَ الشياطينِ عن بلوغِ الوحي، فلا يشتبه عليك الوحيُ الإلهيُّ بوسوسةِ الشياطين، فالوحيُ محروسٌ والشياطينُ مطرودون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ عجزِ الشياطينِ عن استراقِ الوحي."},"action":{"text":"اعلم عجزَ الشياطينِ عن الاستماعِ إلى الملائكةِ في الملأ الأعلى وبلوغِ الوحي، فإنهم يُرجَمون ويُطرَدون من كلِّ جانب «لا يسمعون إلى الملإ الأعلى ويقذفون من كل جانب»؛ فالوحيُ الإلهيُّ محروسٌ من استراقِ الشياطين؛ فلا يشتبه عليك الوحيُ الصافي بوسوسةِ الشياطينِ وإفكهم؛ فميّز بين وحيِ الرحمنِ (القرآنِ والسنّة) وبين وساوسِ الشياطينِ وإلهاماتهم الباطلة؛ فما جاء عن الله ورسوله فهو الحقُّ المحفوظ، وما جاء من الشياطينِ فهو الباطلُ المطرود؛ فاعتمد على الوحيِ المحروس، واحذر وسوسةَ الشياطين؛ فالوحيُ محروسٌ، والشياطينُ عاجزون مطرودون."}},{"n":9,"reflection":{"text":"«دحورا ولهم عذاب واصب» — طردًا لهم من السماء، ولهم عذابٌ دائمٌ لازم؛ ففي هذا عاقبةُ الشياطينِ الطردُ والعذابُ الدائم؛ فاحذر أن تكون من حزبِ الشياطينِ الذين عاقبتهم الطردُ والعذابُ الدائم، فكن من حزبِ الرحمنِ لتنجو، فالشياطينُ مطرودون معذّبون.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مصيرِ الشياطين، والكونُ من حزبِ الرحمن."},"action":{"text":"احذر أن تكون من حزبِ الشياطينِ الذين عاقبتهم الطردُ من رحمةِ الله والعذابُ الدائمُ اللازم «دحورا ولهم عذاب واصب»؛ فكن من حزبِ الرحمنِ الذين يطيعون الله لتنجو من مصيرِ الشياطين؛ فالشياطينُ مطرودون معذّبون بعذابٍ دائم؛ فلا تطع الشيطانَ فتكون من حزبه ومصيره؛ بل عادِ الشيطانَ وخالفه، والزم طاعةَ الله؛ فمن اتّبع الشيطانَ لحقه مصيره من الطردِ والعذاب، ومن اتّبع الله كان من حزبه الفائزين؛ فاجعل ولاءك لله وطاعتك له؛ واستعذ بالله من الشيطانِ الرجيمِ المطرود؛ فالنجاةُ في طاعةِ الرحمن، والهلاكُ في اتّباعِ الشيطان."}},{"n":10,"reflection":{"text":"«إلا من خطف الخطفة فأتبعه شهاب ثاقب» — إلا شيطانًا اختطف كلمةً من السمعِ خطفًا سريعًا فيتبعه شهابٌ نافذٌ مضيءٌ يحرقه؛ ففي هذا شدّةُ حفظِ الله للوحي؛ فاعلم شدّةَ حفظِ الله لوحيه، فحتى الخطفةُ اليسيرةُ يعقبها الشهاب، فما بلغك من الوحي محفوظٌ من كلِّ دخيل، فثِق بسلامته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بشدّةِ حفظِ الله للوحي من كلِّ دخيل."},"action":{"text":"أيقن بشدّةِ حفظِ الله لوحيه، فحتى الشيطانُ الذي يختطف كلمةً من السمعِ خطفًا سريعًا يتبعه شهابٌ ثاقبٌ نافذٌ يحرقه «إلا من خطف الخطفة فأتبعه شهاب ثاقب»؛ فالوحيُ محروسٌ حراسةً شديدةً من كلِّ استراق؛ فما بلغك من الوحيِ (القرآنِ والسنّة) محفوظٌ نقيٌّ من كلِّ دخيلٍ أو تحريف؛ فتلقَّه بثقةٍ تامّةٍ في سلامته وحفظه؛ فالله تكفّل بحفظِ وحيه ودينه من كلِّ عبثٍ أو تحريف؛ فمن أيقن بهذا الحفظِ الشديدِ تلقّى الوحيَ بالتعظيمِ والاطمئنان؛ فاعتمد على الوحيِ المحفوظ، واثقًا بسلامته وصفائه؛ فالله حافظٌ لكتابه وسنّةِ نبيّه؛ فلن يضيعا ولن يُحرَّفا؛ فتمسّك بهما، واثقًا بحفظِ الله لهما."}}]},{"title":"إنكارُ البعثِ والاستهزاء، ومشهدُ الحشرِ والفصلِ والسؤال","range":[11,26],"theme":"برهانُ البعثِ بأنّ من خلق الأعظمَ يعيد الأدنى، وعنادُ المكذّبين وسخريتهم، وتأكيدُ البعثِ وأنه صيحةٌ واحدة، ويومُ الفصل، وحشرُ الظالمين مع معبوداتهم إلى الجحيم، ووقوفُهم للسؤال، وذلُّ المستكبرين","verses":[{"n":11,"reflection":{"text":"«فاستفتهم أهم أشد خلقا أم من خلقنا إنا خلقناهم من طين لازب» — فاسأل منكري البعث: أهم أشدُّ خلقًا أم من خلقنا من السماواتِ والأرضِ والملائكة؟ إنا خلقناهم من طينٍ لاصق؛ ففي هذا برهانُ البعثِ بأنّ من خلق الأعظمَ يعيد الأدنى؛ فأيقن بأنّ من خلق السماواتِ العظيمةَ قادرٌ على إعادتك أنت المخلوقَ من طين، فالبعثُ أهونُ من خلقِ الكون، فلا تستبعده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ، فمن خلق الأعظمَ يعيد الأدنى."},"action":{"text":"أيقن بأنّ الذي خلق السماواتِ والأرضَ والملائكةَ (وهي أعظمُ خلقًا) قادرٌ على أن يبعثك أنت المخلوقَ من طينٍ لاصقٍ ضعيف «إنا خلقناهم من طين لازب»؛ فمن قدر على خلقِ الأعظمِ فهو على إعادةِ الأدنى أقدر؛ فالبعثُ أهونُ من خلقِ الكونِ العظيم؛ فلا تستبعد البعثَ ولا تشكّ فيه؛ فتذكّر أصلك الضعيفَ من الطين، وقدرةَ الله على خلقِ ما هو أعظمُ منك؛ فيحملك ذلك على اليقينِ بالبعثِ والتواضعِ لله؛ فمن تأمّل عظمةَ خلقِ الله أيقن بقدرته على بعثه؛ فرسّخ يقينك بالبعثِ بالنظرِ في خلقِ الكونِ العظيم؛ فاستعدَّ للبعثِ بالعملِ الصالح؛ فالبعثُ حقٌّ، وقدرةُ الله لا تحدّها حدود."}},{"n":12,"reflection":{"text":"«بل عجبت ويسخرون» — بل عجبتَ يا محمدُ من إنكارهم البعثَ مع وضوحِ الأدلّة، وهم يسخرون من ذلك؛ ففي هذا بيانُ عنادِ المنكرين للبعث؛ فلا تعجب من عنادِ المعاندين وسخريتهم من الحقّ، فتلك عادةُ المكذّبين، فاثبت على الحقِّ ولا تلتفت لسخريتهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ رغمَ عنادِ المعاندين وسخريتهم."},"action":{"text":"لا يزلزلك عنادُ المعاندين وسخريتهم من الحقِّ ومن البعثِ رغمَ وضوحِ الأدلّة، فتلك عادةُ المكذّبين مع الحقّ «بل عجبت ويسخرون»؛ فامضِ على يقينك، ولا تلتفت لسخريةِ الساخرين واستهزائهم؛ فالحقُّ لا يبطل باستهزاءِ الجاهلين ولا بسخريةِ المعاندين؛ فاثبت على الحقّ، واعجب أنت من إصرارهم على الباطلِ مع وضوحِ الأدلّة؛ فمن ثبت على الحقِّ رغمَ السخريةِ نجا، ومن تزعزع بها خسر؛ فلا تجعل سخريةَ المستهزئين تؤثر في إيمانك؛ بل ازدد يقينًا وثباتًا؛ فالعاقبةُ للمؤمنين الثابتين، والخزيُ للساخرين المعاندين؛ فامضِ في طريقك، غيرَ مكترثٍ بسخريةِ من يسخر."}},{"n":13,"reflection":{"text":"«وإذا ذكروا لا يذكرون» — وإذا ذُكِّروا بآياتِ الله والحقِّ لا يتذكّرون ولا ينتفعون؛ ففي هذا ذمُّ من لا ينتفع بالتذكير؛ فاحذر أن تكون ممّن لا يتذكّر إذا ذُكِّر، بل تفاعل مع التذكيرِ والموعظة، فالمنتفعُ من يتّعظ بالذكرى، والمحرومُ من يمرّ عليها بلا أثر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانتفاعُ بالتذكيرِ والموعظةِ لا الإعراضُ عنها."},"action":{"text":"احذر أن تكون ممّن لا يتذكّر ولا ينتفع إذا ذُكِّر بآياتِ الله والحقّ، كحالِ المعرضين «وإذا ذكروا لا يذكرون»؛ بل تفاعل مع التذكيرِ والموعظةِ بقلبٍ واعٍ؛ فإذا بلغتك آيةٌ أو موعظةٌ فتأثّر بها واعمل بمقتضاها؛ فالمنتفعُ من يتّعظ بالذكرى ويتفاعل معها، والمحرومُ من تمرّ عليه الموعظةُ بلا أثر؛ فاجعل قلبك حيًّا يتذكّر عند التذكير، ويلين عند الموعظة؛ فمن تذكّر عند التذكيرِ انتفع واهتدى، ومن أعرض عنه حُرِم؛ فلا تكن كالمعرضين الذين لا يذكرون إذا ذُكِّروا؛ بل كن من المتّعظين المتذكّرين؛ فالذكرى تنفع المؤمنين؛ فاجعل قلبك مقبلًا على مواعظِ الله وآياته، متذكّرًا متّعظًا عاملًا."}},{"n":14,"reflection":{"text":"«وإذا رأوا آية يستسخرون» — وإذا رأوا آيةً ومعجزةً بالغوا في السخريةِ منها ودعوا غيرهم إليها؛ ففي هذا شدّةُ عنادِ المعاندين حتى في السخرية؛ فاحذر السخريةَ من آياتِ الله، فالمعاندُ لا تنفعه الآياتُ بل يزداد بها سخرية، فعظّم آياتِ الله ولا تستهزئ بها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من السخريةِ من آياتِ الله، وتعظيمُها."},"action":{"text":"احذر السخريةَ والاستهزاءَ بآياتِ الله ومعجزاته، فإنّ المعاندين كلّما رأوا آيةً بالغوا في السخريةِ منها ودعوا غيرهم إليها «وإذا رأوا آية يستسخرون»؛ فالمعاندُ لا تنفعه الآياتُ بل يزداد بها سخريةً وعنادًا، لأنّ داءه الكبرُ لا الجهل؛ فعظّم آياتِ الله وشعائرَه وأحكامه، ولا تستهزئ بشيءٍ منها؛ فالاستهزاءُ بآياتِ الله من أعظمِ الجرائم؛ فراقب لسانك وقلبك أن يقعا في شيءٍ من ذلك؛ ولا تجالس المستهزئين بآياتِ الله؛ فمن عظّم آياتِ الله هُدِي ووُفِّق، ومن استهزأ بها خُذِل؛ فاجعل موقفك من آياتِ الله التعظيمَ والإجلالَ والاتّباع، لا السخريةَ والاستهزاء؛ فالمستهزئُ بالآياتِ معاندٌ لا ينتفع بها."}},{"n":15,"reflection":{"text":"«وقالوا إن هذا إلا سحر مبين» — وقالوا عن القرآنِ والآيات: ما هذا إلا سحرٌ واضح؛ ففي هذا ردُّهم الحقَّ بدعوى السحر؛ فلا يهزّك ردُّ المعاندين للحقِّ بتهمةِ السحر، فتلك حيلةُ العاجزِ عن الحجّة، فاثبت على الحقِّ ولا تلتفت لتهمهم الباطلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ رغمَ رميه بتهمةِ السحر."},"action":{"text":"لا يهزّك ردُّ المعاندين للحقِّ ولآياتِ الله بتهمةِ السحر، كما قالوا عن القرآن: «إن هذا إلا سحر مبين»؛ فتلك حيلةُ العاجزِ عن الحجّةِ والمعارضة؛ فامضِ على يقينك، ولا تلتفت لتهمهم الباطلة؛ فالحقُّ لا يبطل بتهمةِ المتّهمين ولا بافتراءِ المفترين؛ فاثبت على الحقّ، واعلم أنّ من عادى الحقَّ رماه بكلِّ تهمةٍ ليصدّ عنه؛ فلا يغرّنك ذلك؛ بل ازدد تمسّكًا بالحقِّ ويقينًا به؛ فمن اتّهم القرآنَ بالسحرِ فقد عجز عن معارضته والردِّ عليه؛ فالعاقبةُ للحقِّ وأهله، والخزيُ للمعاندين المتّهمين؛ فلا تجعل تهمَ الطاعنين تؤثر في إيمانك؛ فالمعاندُ لا تنفعه البيّناتُ لأنّ داءه العناد؛ فاثبت على الحقّ، واتّبعه بدليله."}},{"n":16,"reflection":{"text":"«أإذا متنا وكنا ترابا وعظاما أإنا لمبعوثون» — أإذا متنا وصرنا ترابًا وعظامًا باليةً أإنا لمبعوثون أحياءً؟ ففي هذا استبعادهم البعثَ واستنكارُه؛ فلا يدخلك استبعادُ المنكرين للبعثِ شكًّا، فمن خلقك أوّلًا قادرٌ على إعادتك، فرسّخ يقينك بالبعث، ولا تكابر قدرةَ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"دفعُ استبعادِ البعثِ باليقينِ بقدرةِ الله."},"action":{"text":"لا يدخلنّ قلبك شيءٌ من استبعادِ منكري البعثِ واستنكارهم له، إذ يقولون: أإذا متنا وصرنا ترابًا وعظامًا نُبعَث؟ «أإذا متنا وكنا ترابا وعظاما أإنا لمبعوثون»؛ فمن خلقك أوّلًا من العدمِ قادرٌ على إعادتك بعد أن تصير ترابًا وعظامًا؛ فالإعادةُ أهونُ من البدء؛ فرسّخ يقينك بالبعث؛ ولا تكابر قدرةَ الله كما كابر المنكرون؛ فتذكّر خلقك الأوّلَ لتوقن بالبعثِ الآخر؛ فمن تأمّل بدء خلقه أيقن بقدرةِ الله على إعادته؛ فلا تستبعد البعثَ، فهو على الله يسير؛ فاستعدَّ له بالعملِ الصالح؛ فالبعثُ حقٌّ لا شكَّ فيه؛ فمن أنكره فقد جهل قدرةَ خالقه؛ فاجعل يقينك بالبعثِ راسخًا، واعمل ليومِ اللقاء."}},{"n":17,"reflection":{"text":"«أوآباؤنا الأولون» — أوَيُبعَث آباؤنا الأوّلون الذين ماتوا من قديم؟ ففي هذا زيادةُ استبعادهم للبعث؛ فاعلم أنّ الله يبعث الأوّلين والآخرين جميعًا، فلا يعجزه بعثُ أحد، فمن قدر على الخلقِ قدر على البعثِ للجميع، فلا تستبعد بعثَ الأوّلين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ ببعثِ الأوّلين والآخرين، فلا يعجز الله بعثُ أحد."},"action":{"text":"أيقن بأنّ الله يبعث الأوّلين والآخرين جميعًا يومَ القيامة، فلا يعجزه بعثُ أحدٍ مهما تقادم موته، كما استبعد المنكرون بعثَ آبائهم الأوّلين «أوآباؤنا الأولون»؛ فمن قدر على خلقِ الخلقِ من العدمِ قادرٌ على بعثهم جميعًا؛ فلا فرقَ عند قدرةِ الله بين الأوّلين والآخرين، ولا بين قريبِ العهدِ وبعيده؛ فرسّخ يقينك بأنّ الله يبعث الخلقَ كلَّهم للحساب؛ فلا تستبعد بعثَ أحدٍ مهما طال أمده؛ فقدرةُ الله لا تحدّها حدود؛ فاستعدَّ ليومِ يُبعَث فيه الأوّلون والآخرون؛ فمن أيقن بالبعثِ الشاملِ عمل له؛ فالبعثُ حقٌّ للجميع، وقدرةُ الله محيطةٌ بكلِّ شيء؛ فاجعل هذا اليقينَ حاديًا لك إلى العمل."}},{"n":18,"reflection":{"text":"«قل نعم وأنتم داخرون» — قل لهم: نعم تُبعَثون وأنتم صاغرون ذليلون؛ ففي هذا تأكيدُ البعثِ وذلُّ المنكرين؛ فأيقن بالبعثِ وأنه واقعٌ لا محالة، واعمل له، فالمنكرون يُبعَثون أذلّاء، فاستعدَّ للبعثِ بالإيمانِ والعملِ لتكون من المكرمين لا من الأذلّاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ والاستعدادُ له لتكون من المكرمين."},"action":{"text":"أيقن بأنّ البعثَ واقعٌ لا محالة، وأنّ المنكرين له سيُبعَثون صاغرين أذلّاء «قل نعم وأنتم داخرون»؛ فاستعدَّ للبعثِ بالإيمانِ والعملِ الصالحِ لتكون من المكرمين لا من الأذلّاء؛ فالبعثُ حقٌّ، والحسابُ آتٍ؛ فمن آمن به وعمل له بُعِث مكرَّمًا، ومن أنكره وأعرض بُعِث ذليلًا؛ فاجعل يقينك بالبعثِ راسخًا؛ واعمل ليومِ اللقاءِ عملَ من يوقن به؛ فلا تكن كالمنكرين الذين يُبعَثون أذلّاء صاغرين؛ بل كن من المؤمنين الذين يُبعَثون مكرَّمين آمنين؛ فبادر بالتوبةِ والعملِ الصالحِ قبل فواتِ الأوان؛ فمن استعدَّ للبعثِ نال الكرامةَ يومَ القيامة، ومن أنكره نال الذلَّ والصغار؛ فاختر لنفسك سبيلَ المكرمين."}},{"n":19,"reflection":{"text":"«فإنما هي زجرة واحدة فإذا هم ينظرون» — فإنما البعثُ صيحةٌ واحدةٌ (النفخةُ الثانية) فإذا هم قائمون ينظرون أهوالَ القيامة؛ ففي هذا سهولةُ البعثِ على الله؛ فأيقن بسهولةِ البعثِ على الله، فبصيحةٍ واحدةٍ يُبعَث الخلق، فلا يعجزه شيء، فاستعدَّ لذلك اليومِ الذي يأتي بغتة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بسهولةِ البعثِ والاستعدادُ لذلك اليوم."},"action":{"text":"أيقن بسهولةِ البعثِ على الله، فما هو إلا صيحةٌ واحدةٌ (النفخةُ الثانية) فإذا الخلقُ قائمون ينظرون أهوالَ القيامة «فإنما هي زجرة واحدة فإذا هم ينظرون»؛ فما أيسرَ البعثَ على الله: صيحةٌ واحدةٌ يُبعَث بها الخلقُ أجمعون؛ فلا يعجزه شيء؛ فاستعدَّ لذلك اليومِ العظيمِ الذي يأتي بغتة؛ فمن أيقن بسهولةِ البعثِ على الله عمل له واستعدّ؛ فلا تستبعد البعثَ ولا تشكّ فيه؛ فقدرةُ الله لا تحدّها حدود؛ فبادر بالإيمانِ والعملِ الصالحِ قبل أن تأتيك تلك الصيحة؛ فاستحضر مشهدَ قيامك يومَ البعثِ تنظر أهوالَ القيامة؛ فيحملك ذلك على المبادرةِ بالعمل؛ فالبعثُ حقٌّ يسير، والحسابُ آتٍ قريب؛ فاستعدَّ له."}},{"n":20,"reflection":{"text":"«وقالوا يا ويلنا هذا يوم الدين» — وقال المنكرون حين بُعِثوا: يا هلاكنا هذا يومُ الجزاءِ والحساب؛ ففي هذا ندمُ المنكرين حين لا ينفع الندم؛ فبادر بالإيمانِ والعملِ قبل أن تقول يومَ القيامةِ: يا ويلنا، فالندمُ يومئذٍ لا ينفع، فاستعدَّ ليومِ الدينِ من الآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالعملِ قبل ندمِ يومِ الدين."},"action":{"text":"بادر بالإيمانِ والعملِ الصالحِ من الآن، قبل أن تقول يومَ القيامةِ متحسّرًا: يا ويلنا هذا يومُ الجزاء، كما يقول المنكرون حين يُبعَثون «وقالوا يا ويلنا هذا يوم الدين»؛ فالندمُ يومئذٍ لا ينفع؛ فاستعدَّ ليومِ الدينِ (الجزاءِ والحساب) في زمنِ الإمهال؛ فلا تسوّف بالتوبةِ والعمل؛ فمن استعدّ ليومِ الدينِ نجا، ومن فرّط ندم يومَ لا ينفع الندم؛ فاستحضر ذلك اليومَ العظيم؛ فيحملك ذلك على المبادرةِ بالعملِ الصالح؛ فاعمل لآخرتك عملَ من يوقن بيومِ الدين؛ فالحسابُ آتٍ، والجزاءُ واقع؛ فلا تكن كالمنكرين الذين يتحسّرون حين لا ينفع التحسّر؛ بل كن من المستعدّين الذين يفرحون بلقاءِ الله؛ فبادر بالزادِ قبل الرحيل."}},{"n":21,"reflection":{"text":"«هذا يوم الفصل الذي كنتم به تكذبون» — يُقال لهم: هذا يومُ الفصلِ بين الخلقِ بالحقّ، الذي كنتم به تكذّبون في الدنيا؛ ففي هذا تحقّقُ يومِ الفصلِ للمكذّبين؛ فصدّق بيومِ الفصلِ في الدنيا قبل أن تراه، فهو حقٌّ يُفصَل فيه بين الخلق، فاستعدَّ له بالعملِ، ولا تكذّب به فتندم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ بيومِ الفصلِ والاستعدادُ له."},"action":{"text":"صدّق بيومِ الفصلِ (يومِ القيامةِ الذي يُفصَل فيه بين الخلقِ بالحقّ) في الدنيا قبل أن تعاينه، فهو حقٌّ يُقال للمكذّبين حين يرونه: «هذا يوم الفصل الذي كنتم به تكذبون»؛ فمن كذّب به في الدنيا رآه وندم؛ فاستعدَّ ليومِ الفصلِ بالإيمانِ والعملِ الصالح؛ ولا تكذّب به فتندم يومَ تراه؛ فيومَ الفصلِ يُميَّز المحقُّ من المبطل، والمؤمنُ من الكافر، ويُجزى كلٌّ بعمله؛ فبادر بالعملِ الصالحِ الذي ينفعك يومئذ؛ فمن صدّق بيومِ الفصلِ واستعدّ له نجا، ومن كذّب به وأعرض خسر؛ فاجعل استحضارَ يومِ الفصلِ حاديًا لك إلى الطاعةِ وزاجرًا عن المعصية؛ فالفصلُ آتٍ، والجزاءُ بالعدل؛ فاستعدَّ ليومٍ يُفصَل فيه بين الخلائقِ بالحق."}},{"n":22,"reflection":{"text":"«احشروا الذين ظلموا وأزواجهم وما كانوا يعبدون» — يُقال للملائكة: اجمعوا الذين ظلموا (المشركين) وأشباههم وما كانوا يعبدون من دونِ الله؛ ففي هذا حشرُ المشركين مع معبوداتهم؛ فاحذر الشركَ والظلم، فالمشركون يُحشَرون مع معبوداتهم إلى النار، فأخلص العبادةَ لله لتنجو من هذا الحشر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الشركِ الذي يُحشَر أهلُه مع معبوداتهم."},"action":{"text":"احذر الشركَ والظلمَ، فإنّ المشركين يُحشَرون يومَ القيامةِ مع أزواجهم (أشباههم في الكفر) ومع ما كانوا يعبدون من دونِ الله «احشروا الذين ظلموا وأزواجهم وما كانوا يعبدون»؛ فيُجمَعون مع معبوداتهم الباطلةِ ويُساقون إلى النار؛ فأخلص العبادةَ لله وحده لتنجو من هذا الحشرِ المهين؛ ولا تجعل لله شريكًا في العبادة؛ فمن أشرك حُشِر مع شركائه إلى العذاب؛ ومن وحّد الله نجا وحُشِر مع المؤمنين؛ فحقّق التوحيدَ الخالص؛ واجتنب الظلمَ بأنواعه، وأعظمُه الشرك؛ فاجعل عبادتك كلَّها لله؛ فمن عبد غيرَ الله حُشِر معه إلى النار، ومن أخلص لله حُشِر مع أوليائه إلى الجنّة؛ فاختر لنفسك سبيلَ الموحّدين الناجين."}},{"n":23,"reflection":{"text":"«من دون الله فاهدوهم إلى صراط الجحيم» — ما كانوا يعبدون من دونِ الله، فسوقوهم ودلّوهم إلى طريقِ النار؛ ففي هذا مصيرُ المشركين ومعبوداتهم إلى النار؛ فاحذر أن تُساق إلى النارِ مع معبوداتِ الباطل، فأخلص العبادةَ لله لتُهدى إلى صراطِ الجنّةِ لا صراطِ الجحيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مصيرِ المشركين، وإخلاصُ العبادةِ للنجاة."},"action":{"text":"احذر أن تُساق يومَ القيامةِ إلى صراطِ الجحيمِ مع معبوداتِ الباطل، كما يُقال في المشركين ومعبوداتهم: «فاهدوهم إلى صراط الجحيم»؛ فمصيرُ المشركين ومعبوداتهم إلى النار؛ فأخلص العبادةَ لله وحده لتُهدى إلى صراطِ الجنّةِ لا صراطِ الجحيم؛ فمن عبد غيرَ الله سيق مع معبوده إلى النار؛ ومن أخلص لله هُدِي إلى الجنّة؛ فحقّق التوحيدَ الخالص، واجتنب الشركَ بكلِّ صوره؛ فاجعل عبادتك ودعاءك وتوكّلك لله وحده؛ فالطريقُ إلى الجنّةِ بالتوحيدِ والطاعة، والطريقُ إلى النارِ بالشركِ والمعصية؛ فاسلك سبيلَ الموحّدين لتُهدى إلى الجنّة؛ فلا تجعل لله شريكًا يسوقك إلى النار؛ بل أخلص له العبادةَ لتنجو وتفوز."}},{"n":24,"reflection":{"text":"«وقفوهم إنهم مسئولون» — واحبسوهم للحساب، إنهم مسؤولون عن أعمالهم وأقوالهم؛ ففي هذا تقريرُ سؤالِ الخلقِ يومَ القيامة؛ فاستعدَّ للسؤالِ يومَ القيامة، فكلُّ نفسٍ موقوفةٌ مسؤولةٌ عن عملها، فأعِدَّ للسؤالِ جوابًا بالعملِ الصالح، فالوقوفُ للحسابِ حقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للسؤالِ والوقوفِ للحسابِ يومَ القيامة."},"action":{"text":"استعدَّ للسؤالِ والوقوفِ للحسابِ يومَ القيامة، فكلُّ نفسٍ موقوفةٌ مسؤولةٌ عن أعمالها وأقوالها ونعمها «وقفوهم إنهم مسئولون»؛ فأعِدَّ لهذا السؤالِ جوابًا بالإيمانِ والعملِ الصالح؛ فستُسأل عن عمرك فيم أفنيته، وعن علمك ماذا عملت به، وعن مالك من أين اكتسبته وفيم أنفقته، وعن جسمك فيم أبليته؛ فاستحضر أنك موقوفٌ للحسابِ مسؤولٌ عن كلِّ شيء؛ فيحملك ذلك على المراقبةِ والاستعداد؛ فمن أعدَّ للسؤالِ جوابًا نجا، ومن فرّط تحيّر وخزي؛ فاجعل استحضارَ الوقوفِ للحسابِ حاديًا لك إلى الطاعةِ وزاجرًا عن المعصية؛ فالوقوفُ حقٌّ، والسؤالُ واقع؛ فاعمل لذلك اليومِ عملَ من يوقن أنه محاسَبٌ مسؤول."}},{"n":25,"reflection":{"text":"«ما لكم لا تناصرون» — يُقال للمشركين توبيخًا: ما لكم لا ينصر بعضكم بعضًا كما كنتم في الدنيا؟ ففي هذا انقطاعُ التناصرِ بين أهلِ الباطلِ يومَ القيامة؛ فلا تعتمد على نصرةِ المخلوقين، فيومَ القيامةِ لا ينصر أحدٌ أحدًا، فاجعل اعتمادك على الله، والجأ إليه لا إلى الخلق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاعتمادِ على نصرةِ المخلوقين، والاعتمادُ على الله."},"action":{"text":"لا تعتمد على نصرةِ المخلوقين وموالاتهم في الباطل، فيومَ القيامةِ ينقطع التناصرُ بين أهلِ الباطل، ويُقال لهم توبيخًا: «ما لكم لا تناصرون»؛ فلا ينصر أحدٌ أحدًا يومئذ؛ فاجعل اعتمادك على الله وحده، والجأ إليه لا إلى الخلق؛ فمن اعتمد على المخلوقين خُذِل يومَ الحاجة، ومن اعتمد على الله كفاه؛ فلا تبنِ ولاءك ونصرتك على الباطل، فإنها تنقلب عداوةً يومَ القيامة؛ بل ابنِ ولاءك على الإيمانِ والتقوى؛ فالتناصرُ في الحقِّ يدوم، والتناصرُ في الباطلِ ينقطع؛ فاجعل موالاتك ونصرتك لأهلِ الإيمانِ والحقّ؛ واعتمد في كلِّ أمرك على الله؛ فهو الناصرُ المعينُ الذي لا يخذل من توكّل عليه؛ فلا ناصرَ يومَ القيامةِ إلا الله."}},{"n":26,"reflection":{"text":"«بل هم اليوم مستسلمون» — بل هم اليومَ (يومَ القيامة) خاضعون منقادون أذلّاء لا حيلةَ لهم؛ ففي هذا ذلُّ المستكبرين يومَ القيامة؛ فاحذر الكبرَ في الدنيا الذي عاقبتُه الذلُّ يومَ القيامة، فالمستكبرون يستسلمون أذلّاء يومئذ، فتواضع لله في الدنيا لتكرَّم في الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبرِ الذي عاقبتُه الذلُّ يومَ القيامة."},"action":{"text":"احذر الكبرَ والاستكبارَ في الدنيا، فإنّ عاقبتَه الذلُّ والاستسلامُ يومَ القيامة، حيث يستسلم المستكبرون أذلّاء لا حيلةَ لهم «بل هم اليوم مستسلمون»؛ فمن تكبّر في الدنيا ذلَّ في الآخرة؛ فتواضع لله وللخلقِ في الدنيا لتُكرَّم في الآخرة؛ فالكبرُ خُلقٌ ممقوتٌ عاقبتُه الذلُّ والهوان؛ والتواضعُ خُلقٌ محمودٌ عاقبتُه العزّةُ والكرامة؛ فطهّر قلبك من الكبرِ والاستعلاءِ على الخلق؛ واقبل الحقَّ ممّن جاء به، ولا تستكبر عنه؛ فمن تواضع لله رفعه، ومن تكبّر وضعه؛ فاجعل التواضعَ خُلقك في الدنيا؛ فبه تنال العزّةَ والكرامةَ في الآخرة؛ فالمستكبرون يُذَلّون يومَ القيامة، والمتواضعون يُكرَمون؛ فاختر لنفسك التواضعَ لتكون من المكرمين."}}]},{"title":"تخاصمُ الأتباعِ والمتبوعين، وكبرُهم عن التوحيد، وعدلُ الجزاء","range":[27,39],"theme":"تلاومُ الأتباعِ والمتبوعين وتبرّؤُهم، وأنّ الإضلالَ بالتزيينِ لا الإجبار، واشتراكُهم في العذاب، وكبرُهم عن كلمةِ التوحيد ورميُهم النبيَّ بالشعرِ والجنون، وأنه جاء بالحقِّ مصدّقًا للرسل، وأنّ الجزاءَ بالعمل","verses":[{"n":27,"reflection":{"text":"«وأقبل بعضهم على بعض يتساءلون» — وأقبل الأتباعُ والمتبوعون بعضهم على بعضٍ يتلاومون ويتخاصمون؛ ففي هذا تخاصمُ أهلِ الباطلِ يومَ القيامة؛ فلا تتّبع أحدًا في باطلٍ فتتخاصم معه يومَ القيامة، فأهلُ الباطلِ يتلاومون يومئذ، فاتّبع الحقَّ لا الرجال، وابنِ علاقاتك على التقوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ اتّباعِ أهلِ الباطل، فهم يتخاصمون يومَ القيامة."},"action":{"text":"لا تتّبع أحدًا في باطلٍ أو ضلال، فإنّ أهلَ الباطلِ يتخاصمون ويتلاومون يومَ القيامة، يقبل بعضهم على بعضٍ يتساءلون ويتبرّأ بعضهم من بعض «وأقبل بعضهم على بعض يتساءلون»؛ فاتّباعك للباطلِ يجرّ عليك الخصومةَ والندامةَ يومَ القيامة؛ فاجعل اتّباعك للحقِّ والدليلِ لا للأشخاصِ والرجال؛ وابنِ علاقاتك وموالاتك على التقوى والإيمانِ لا على الباطلِ والهوى؛ فالأخلّاءُ على الباطلِ يومئذٍ بعضهم لبعضٍ عدوٌّ إلا المتّقين؛ فمن تحابَّ في الله دامت مودّتهم، ومن تحابَّ على المعصيةِ صارت عداوةً؛ فاختر أخلّاءك وأتباعك على الحقِّ والتقوى؛ فمن اتّبع الحقَّ نجا، ومن اتّبع الباطلَ ندم وتخاصم مع من اتّبعه؛ فحرّر دينك من التبعيّةِ العمياء."}},{"n":28,"reflection":{"text":"«قالوا إنكم كنتم تأتوننا عن اليمين» — قال الأتباعُ للمتبوعين: إنكم كنتم تأتوننا من جهةِ الدينِ والنصحِ (فتزيّنون لنا الكفر)؛ ففي هذا لومُ الأتباعِ للمتبوعين على إضلالهم؛ فاحذر أن تُضِلّ أحدًا بتزيينِ الباطلِ له باسمِ الدين، ولا تتّبع من يزيّن لك الباطل، فالمُضِلُّ والمُضَلُّ يتلاومان يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من إضلالِ الناسِ باسمِ الدين، وعدمُ اتّباعِ المزيّنين للباطل."},"action":{"text":"احذر أن تُضِلّ أحدًا بتزيينِ الباطلِ له وتحسينِ الكفرِ والمعصيةِ باسمِ الدينِ والنصح، فذلك جرمُ المتبوعين الذين لامهم أتباعهم: «إنكم كنتم تأتوننا عن اليمين» أي من جهةِ الدينِ تزيّنون لنا الباطل؛ ولا تتّبع من يزيّن لك الباطلَ ويحسّنه لك؛ فالمُضِلُّ والمُضَلُّ يتلاومان ويتخاصمان يومَ القيامة؛ فكن داعيًا إلى الحقِّ لا مزيّنًا للباطل؛ ولا تنقد وراء من يحسّن لك المعصيةَ باسمِ الدينِ أو الحرّيةِ أو التقدّم؛ فزِن ما يُدعى إليه بميزانِ الوحي؛ فمن دعا إلى حقٍّ فله أجره، ومن زيّن باطلًا حمل وزره ووزرَ من أضلّه؛ فاحذر تزيينَ الباطلِ باسمِ الحقّ؛ فالحقُّ ما وافق الوحيَ، والباطلُ ما خالفه ولو زُيِّن."}},{"n":29,"reflection":{"text":"«قالوا بل لم تكونوا مؤمنين» — قال المتبوعون: بل أنتم لم تكونوا مؤمنين أصلًا، فما أجبرناكم على الكفر؛ ففي هذا تبرّؤُ المتبوعين من الأتباعِ وتحميلهم المسؤولية؛ فاعلم أنّ المتبوعين يتبرّؤون من أتباعهم، فلا تُلقِ مسؤوليةَ ضلالك على غيرك، فأنت مسؤولٌ عن اختيارك، فتحمّل مسؤوليةَ نفسك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحمّلُ مسؤوليةِ الاختيار، فالمتبوعون يتبرّؤون من الأتباع."},"action":{"text":"اعلم أنّ المتبوعين في الضلالِ يتبرّؤون من أتباعهم يومَ القيامةِ ويحمّلونهم مسؤوليةَ اختيارهم، قائلين: «بل لم تكونوا مؤمنين» أي ما كان فيكم إيمانٌ أصلًا فتُضَلّون عنه؛ فلا تُلقِ مسؤوليةَ ضلالك أو معصيتك على غيرك؛ فأنت مسؤولٌ عن اختيارك، فالله أعطاك العقلَ والإرادةَ وبيّن لك السبيلين؛ فلا يعذرك أن تقول: أضلّني فلان، أو زيّن لي فلان؛ فالمسؤوليةُ عليك وحدك؛ فاختر لنفسك الهدى بقناعةٍ ودليل؛ ولا تتّبع مضلًّا؛ فمن اختار الحقَّ نجا، ومن اختار الباطلَ هلك ولو زيّنه له غيره؛ فتحمّل مسؤوليةَ اختياراتك، وراقب الله فيها؛ فلا ينفعك يومَ القيامةِ إلقاءُ اللومِ على من أضلّك؛ فالحسابُ فرديّ، والمسؤوليةُ فردية."}},{"n":30,"reflection":{"text":"«وما كان لنا عليكم من سلطان بل كنتم قوما طاغين» — قال المتبوعون: ما كان لنا عليكم قوّةٌ نجبركم بها، بل كنتم قومًا طاغين اخترتم الطغيان بأنفسكم؛ ففي هذا أنّ الإضلالَ بالتزيينِ لا بالإجبار؛ فاعلم أنّ من أضلّك لم يجبرك بل زيّن لك فاخترت، فلا تحتجَّ بإضلالِ غيرك، فالاختيارُ لك، فاختر الحقَّ ولا تطغَ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ الإضلالَ بالتزيينِ لا بالإجبار، فالاختيارُ للعبد."},"action":{"text":"اعلم أنّ من أضلّك من قرناءِ السوءِ أو دعاةِ الباطلِ لم يجبرك على الضلالِ، بل زيّنه لك ودعاك إليه فاخترته أنت بطغيانك، كما قال المتبوعون: «وما كان لنا عليكم من سلطان بل كنتم قوما طاغين»؛ فالإضلالُ يكون بالتزيينِ والدعوةِ لا بالإجبارِ والقهر؛ فلا تحتجَّ بإضلالِ غيرك على معصيتك؛ فالاختيارُ لك، والمسؤوليةُ عليك؛ فاختر الحقَّ، ولا تطغَ ولا تتّبع مزيّنًا للباطل؛ فمن اختار الطغيانَ والباطلَ فلا يلومنّ إلا نفسه؛ فالله أعطاك العقلَ والإرادةَ لتختار؛ فاختر الهدى والطاعة؛ ولا تجعل قرناءَ السوءِ حجّةً لك على المعصية؛ فمن طغى واختار الباطلَ باختياره استحقّ العقوبة؛ فاحذر الطغيانَ واتّباعَ المزيّنين للباطل؛ واختر لنفسك الحقّ."}},{"n":31,"reflection":{"text":"«فحق علينا قول ربنا إنا لذائقون» — قال المتبوعون والأتباع: فوجب علينا وعيدُ ربّنا بالعذاب، إنا لذائقون العذابَ جميعًا؛ ففي هذا اعترافهم باستحقاقِ العذاب؛ فاحذر أن يحقَّ عليك وعيدُ الله بالعذاب، فبادر بالإيمانِ والطاعةِ لتنجو، فمن استحقّ الوعيدَ ذاق العذاب، فاعمل لتكون من الناجين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من استحقاقِ الوعيدِ، والعملُ للنجاة."},"action":{"text":"احذر أن يحقَّ عليك وعيدُ الله بالعذابِ باستحقاقك له بالكفرِ والمعصية، كما اعترف المتبوعون والأتباع: «فحق علينا قول ربنا إنا لذائقون» العذابَ جميعًا؛ فبادر بالإيمانِ والطاعةِ والتوبةِ لتنجو من الوعيد؛ فمن استحقّ وعيدَ الله ذاق العذاب؛ فاعمل لتكون من الناجين الذين لا يحقّ عليهم الوعيد؛ فاجتنب أسبابَ العذاب: من الكفرِ والشركِ والمعاصي؛ والزم أسبابَ النجاة: من التوحيدِ والطاعةِ والتوبة؛ فمن آمن وعمل صالحًا نجا من الوعيد، ومن كفر وعصى استحقّه؛ فراجع نفسك: أأنت من أهلِ الوعيدِ أم من أهلِ النجاة؟ فبادر بالتوبةِ والعملِ الصالحِ قبل أن يحقَّ عليك القول؛ فاعمل ليومِ اللقاءِ عملَ من يخشى الوعيدَ ويرجو النجاة."}},{"n":32,"reflection":{"text":"«فأغويناكم إنا كنا غاوين» — قال المتبوعون: فدعوناكم إلى الغيِّ فاتّبعتمونا، إنا كنّا غاوين ضالّين فأحببنا أن تضلّوا مثلنا؛ ففي هذا اعترافُ المُضِلّين بإغوائهم؛ فاحذر دعاةَ الغيِّ الذين يحبّون أن تضلَّ مثلهم، ولا تتّبعهم، فالضالُّ يحبّ إضلالَ غيره، فكن على حذرٍ من قرناءِ السوء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من دعاةِ الغيِّ الذين يحبّون إضلالَ غيرهم."},"action":{"text":"احذر دعاةَ الغيِّ وقرناءَ السوءِ الذين يحبّون أن تضلَّ مثلهم وتشقى مثلهم، فقد اعترف المُضِلّون بإغوائهم: «فأغويناكم إنا كنا غاوين»؛ فالضالُّ الغاوي يحبّ إضلالَ غيره ليكون مثله؛ فلا تتّبع من يدعوك إلى الغيِّ والضلال؛ واحذر قرناءَ السوءِ الذين يجرّونك إلى المعصيةِ والباطل؛ فاختر جلساءك وأصحابك من أهلِ الخيرِ والصلاح؛ فالمرءُ على دينِ خليله؛ فمن صاحب الأخيارَ أعانوه على الطاعة، ومن صاحب الأشرارَ جرّوه إلى المعصية؛ فاحذر مجالسَ الغيِّ ودعاته؛ ولا تنقد وراء من يزيّن لك الباطل؛ فمن اتّبع دعاةَ الغيِّ هلك معهم، ومن اجتنبهم واتّبع الحقَّ نجا؛ فاجعل صحبتك للصالحين الداعين إلى الله؛ فالصحبةُ الصالحةُ عونٌ على الخير، وصحبةُ السوءِ بابُ الهلاك."}},{"n":33,"reflection":{"text":"«فإنهم يومئذ في العذاب مشتركون» — فإنّ المُضِلّين والمُضَلّين يومئذٍ في العذابِ مشتركون جميعًا؛ ففي هذا اشتراكُ أهلِ الباطلِ في العذاب؛ فاحذر أن تشترك مع أهلِ الباطلِ في العذاب، فالمُضِلُّ والمُضَلُّ في العذابِ سواء، فلا تتّبعهم ولا تكن منهم، فاختر طريقَ النجاةِ لا طريقَ العذابِ المشترك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاشتراكِ مع أهلِ الباطلِ في العذاب."},"action":{"text":"احذر أن تشترك مع أهلِ الباطلِ في العذابِ يومَ القيامة، فإنّ المُضِلّين والمُضَلّين يومئذٍ في العذابِ مشتركون جميعًا «فإنهم يومئذ في العذاب مشتركون»؛ فلا يغني عنك متبوعك ولا تابعك شيئًا، بل تشتركون في العذاب؛ فلا تتّبع أهلَ الباطلِ ولا تكن منهم؛ فاختر طريقَ النجاةِ لا طريقَ العذابِ المشترك؛ فمن اتّبع الباطلَ اشترك مع أهله في العذاب، ومن اتّبع الحقَّ نجا مع أهله؛ فاجعل اتّباعك للحقّ، وصحبتك للصالحين؛ فالاشتراكُ في الباطلِ يورث الاشتراكَ في العذاب، والاشتراكُ في الحقِّ يورث الاشتراكَ في النعيم؛ فاختر لنفسك رفقةَ أهلِ الحقّ؛ فمن كان مع أهلِ الباطلِ في الدنيا كان معهم في العذابِ في الآخرة؛ فلا تكن منهم؛ بل كن مع المؤمنين الناجين."}},{"n":34,"reflection":{"text":"«إنا كذلك نفعل بالمجرمين» — إنا كذلك (بالعذابِ المشترك) نفعل بالمجرمين جزاءً لهم؛ ففي هذا تقريرُ عدلِ الله في عقوبةِ المجرمين؛ فاحذر الإجرامَ فجزاؤه العذاب، فالله يعاقب المجرمين بعدله، فاجتنب الإجرامَ والمعاصيَ لتنجو من عقوبةِ المجرمين، فالجزاءُ بالعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإجرامِ الذي جزاؤه العذاب."},"action":{"text":"احذر الإجرامَ والمعاصيَ والذنوب، فإنّ الله يعاقب المجرمين بالعذابِ جزاءً وفاقًا بعدله «إنا كذلك نفعل بالمجرمين»؛ فالجزاءُ من جنسِ العمل؛ فاجتنب الإجرامَ بأنواعه لتنجو من عقوبةِ المجرمين؛ فمن أجرم عوقب، ومن أطاع أُثيب؛ فراقب نفسك واجتنب المعاصي؛ فالله عدلٌ يعاقب المجرمين بإجرامهم؛ فبادر بالتوبةِ من كلِّ جرمٍ ومعصية؛ ولا تُصِرَّ على ذنب؛ فالإصرارُ على الإجرامِ يورد العذاب؛ فاجعل همّك النجاةَ من عقوبةِ المجرمين بالتوبةِ والعملِ الصالح؛ فمن اجتنب الإجرامَ نجا، ومن أصرَّ عليه عوقب؛ فاحذر أن تكون من المجرمين الذين يفعل الله بهم ما توعّدهم به من العذاب؛ بل كن من المتّقين الناجين؛ فالله لا يظلم أحدًا، والجزاءُ بالعدل."}},{"n":35,"reflection":{"text":"«إنهم كانوا إذا قيل لهم لا إله إلا الله يستكبرون» — إنّ المجرمين كانوا إذا قيل لهم: قولوا لا إله إلا الله، استكبروا وأبوا؛ ففي هذا أنّ الكبرَ عن التوحيدِ سببُ الهلاك؛ فاحذر الكبرَ عن كلمةِ التوحيد، فقلها مذعنًا خاضعًا، فالمستكبرون عن التوحيدِ هلكوا، فتواضع لكلمةِ الإخلاصِ واعمل بمقتضاها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبرِ عن كلمةِ التوحيد، والإذعانُ لها."},"action":{"text":"احذر الكبرَ والاستكبارَ عن كلمةِ التوحيدِ «لا إله إلا الله»، فإنّ المجرمين كانوا إذا قيل لهم قولوها استكبروا وأبوا، فكان ذلك سببَ هلاكهم «إنهم كانوا إذا قيل لهم لا إله إلا الله يستكبرون»؛ فقل كلمةَ التوحيدِ مذعنًا خاضعًا، واعمل بمقتضاها من إخلاصِ العبادةِ لله وحده؛ فالتوحيدُ أصلُ النجاة، والكبرُ عنه أصلُ الهلاك؛ فتواضع لكلمةِ الإخلاص، وحقّق معناها في قلبك ولسانك وعملك؛ فمن أذعن للتوحيدِ وعمل به نجا، ومن استكبر عنه هلك؛ فاجعل «لا إله إلا الله» شعارك ودثارك، معتقدًا معناها، عاملًا بمقتضاها؛ فهي كلمةُ النجاة، ومفتاحُ الجنّة؛ فلا تستكبر عنها كما استكبر المجرمون؛ بل اعتزَّ بها، واثبت عليها، واعمل بحقّها؛ فالتوحيدُ عزٌّ وشرفٌ ونجاة."}},{"n":36,"reflection":{"text":"«ويقولون أئنا لتاركو آلهتنا لشاعر مجنون» — ويقولون: أنترك آلهتنا لأجلِ قولِ شاعرٍ مجنون (يعنون النبيَّ ﷺ)؟ ففي هذا رميُهم النبيَّ بالشعرِ والجنونِ تعلّلًا؛ فلا يهزّك رميُ المعاندين للحقِّ وأهله بالتهم، فتلك حيلةُ العاجز، فعظّم الحقَّ ولا تتّبع الآباءَ في باطل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ رغمَ رميِ أهله بالتهم، وترْكُ تقليدِ الآباء."},"action":{"text":"لا يهزّك رميُ المعاندين للحقِّ وأهله بالتهمِ الباطلة، كما رموا النبيَّ ﷺ بالشعرِ والجنونِ تعلّلًا لترْكِ التوحيد: «أئنا لتاركو آلهتنا لشاعر مجنون»؛ فتلك حيلةُ العاجزِ عن الحجّة؛ فامضِ على يقينك، ولا تلتفت لتهمهم؛ ولا تتّبع الآباءَ في عبادةِ الباطلِ كما فعلوا حين قدّموا تقليدَ الآباءِ على اتّباعِ الحق؛ فالحقُّ يُتّبَع بالدليلِ لا بموروثِ العادة؛ فعظّم الحقَّ وأهله، ولا تجعل رميهم بالتهمِ يصدّك عن الحق؛ فمن ثبت على الحقِّ رغمَ التهمِ نجا؛ ومن اتّبع الآباءَ في الباطلِ هلك؛ فحرّر عقلك من التقليدِ الأعمى؛ واتّبع الحقَّ بدليله؛ فالعاقبةُ للحقِّ وأهله، والخزيُ للمعاندين المتّهمين المقلّدين."}},{"n":37,"reflection":{"text":"«بل جاء بالحق وصدق المرسلين» — بل جاء محمدٌ بالحقِّ والتوحيد، وصدّق المرسلين الذين قبله؛ ففي هذا تقريرُ أنّ ما جاء به النبيُّ حقٌّ مصدّقٌ للرسل؛ فأيقن بأنّ ما جاء به النبيُّ ﷺ حقٌّ مصدّقٌ لما جاء به الرسلُ قبله، فاتّبعه، فالحقُّ يصدّق بعضه بعضًا، ودعوةُ الرسلِ واحدة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ ما جاء به النبيُّ حقٌّ مصدّقٌ للرسل، واتّباعُه."},"action":{"text":"أيقن بأنّ ما جاء به النبيُّ ﷺ حقٌّ وصدق، وأنه مصدّقٌ لما جاء به المرسلون قبله من التوحيدِ والحق «بل جاء بالحق وصدق المرسلين»؛ فدعوةُ الرسلِ واحدةٌ في أصلها: التوحيدُ وعبادةُ الله وحده؛ فالحقُّ يصدّق بعضه بعضًا؛ فاتّبع النبيَّ ﷺ فيما جاء به من الحقّ؛ فما جاء به مطابقٌ لما جاءت به الرسلُ قبله؛ فازدد يقينًا بصدقه واتّبع دعوته؛ فمن اتّبع النبيَّ ﷺ اتّبع الحقَّ الذي جاءت به الرسلُ كلُّها؛ فاجعل اتّباعَ النبيِّ ﷺ سبيلك؛ فما جاء به حقٌّ لا شكَّ فيه، مصدّقٌ لما سبق من الوحي؛ فاثبت على اتّباعه، واعمل بما جاء به؛ فالحقُّ واحدٌ لا يتناقض، ودعوةُ الأنبياءِ واحدةٌ في التوحيد؛ فاتّبع الحقَّ الذي جاء به خاتمُ المرسلين."}},{"n":38,"reflection":{"text":"«إنكم لذائقو العذاب الأليم» — إنكم أيها المكذّبون لذائقو العذابِ الأليمِ جزاءَ تكذيبكم؛ ففي هذا وعيدُ المكذّبين بالعذاب؛ فاحذر التكذيبَ بالحقّ، فجزاؤه العذابُ الأليم، فآمن بالحقِّ واتّبعه لتنجو، فالمكذّبُ يذوق العذاب، والمؤمنُ ينجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التكذيبِ بالحقِّ الموجبِ للعذابِ الأليم."},"action":{"text":"احذر التكذيبَ بالحقِّ وبما جاء به النبيُّ ﷺ، فإنّ جزاء المكذّبين ذوقُ العذابِ الأليم «إنكم لذائقو العذاب الأليم»؛ فآمن بالحقِّ واتّبعه لتنجو من هذا العذاب؛ فالمكذّبُ بالحقِّ يذوق العذابَ الأليم، والمؤمنُ به ينجو ويفوز؛ فاجعل موقفك من الحقِّ التصديقَ والاتّباع، لا التكذيبَ والإعراض؛ فبادر بالإيمانِ والعملِ الصالح؛ ولا تكذّب بشيءٍ من الحقّ؛ فمن كذّب بالحقِّ استحقّ العذاب، ومن صدّق به نال النجاة؛ فراجع موقفك: أمصدّقٌ بالحقِّ أم مكذّب؟ فاثبت على التصديقِ والاتّباع؛ فالتكذيبُ بالحقِّ سبيلُ العذاب، والتصديقُ به سبيلُ النجاة؛ فاجعل قلبك مذعنًا للحقِّ، عاملًا بمقتضاه؛ فبه تنجو من العذابِ الأليم."}},{"n":39,"reflection":{"text":"«وما تجزون إلا ما كنتم تعملون» — وما تُجزَون إلا بأعمالكم التي عملتموها؛ ففي هذا تقريرُ عدلِ الجزاء؛ فاعلم أنّ الجزاءَ بالعمل، فقدّم لنفسك عملًا صالحًا، فما تجزى إلا بما عملت، فأحسن عملك لتُجزى خيرًا، فالجزاءُ من جنسِ العمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ الجزاءَ بالعمل، وتقديمُ العملِ الصالح."},"action":{"text":"اعلم أنّ الجزاءَ يومَ القيامةِ بالعملِ بالعدلِ التام، فما تُجزى إلا بما عملت «وما تجزون إلا ما كنتم تعملون»؛ فقدّم لنفسك عملًا صالحًا يُجزيك الله عليه خيرًا؛ فما تجزى إلا بما عملت من خيرٍ أو شرّ؛ فأحسن عملك لتُجزى خيرًا؛ فالجزاءُ من جنسِ العمل: من عمل خيرًا وجده، ومن عمل شرًّا لقيه؛ فاحرص على الإكثارِ من الحسنات، واجتنابِ السيّئات؛ فكلُّ عملٍ محفوظٌ مجزيٌّ عليه بالعدل؛ فلا تظلم نفسك بالتفريطِ في العملِ الصالحِ أو بارتكابِ السيّئات؛ فاجعل عملك خالصًا صالحًا؛ فبه تُجزى خيرًا يومَ لا ينفع إلا العمل؛ فاعمل لآخرتك عملَ من يوقن بعدلِ الله وجزائه؛ فالجزاءُ بالعمل، والله لا يظلم أحدًا مثقالَ ذرّة."}}]},{"title":"نعيمُ المخلصين وحوارُ أهلِ الجنّة، والزقّوم، والتقليدُ الأعمى","range":[40,74],"theme":"استثناءُ المخلصين ونعيمُهم في الجنّةِ من الرزقِ والفواكهِ والشرابِ والأزواجِ والأنس، وحوارُ المؤمنِ مع قرينِ السوءِ الذي رآه في الجحيم، وأنّ ذلك الفوزُ العظيم، وشجرةُ الزقّومِ طعامُ أهلِ النار، وأنّ التقليدَ الأعمى للآباءِ سببُ الهلاك، ونجاةُ المخلصين","verses":[{"n":40,"reflection":{"text":"«إلا عباد الله المخلصين» — لكن عبادَ الله المخلصين الذين أخلصوا العبادةَ لله فإنهم ناجون من العذاب؛ ففي هذا استثناءُ المخلصين من الوعيد؛ فأخلص عبادتك لله لتكون من الناجين، فالإخلاصُ سببُ النجاة، فاجعل عملك كلَّه خالصًا لوجهِ الله، فالمخلصون هم الناجون المكرمون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله للنجاةِ من العذاب."},"action":{"text":"أخلص عبادتك وعملك لله وحده لتكون من عبادِ الله المخلصين الذين استثناهم الله من العذابِ والوعيد «إلا عباد الله المخلصين»؛ فالإخلاصُ سببُ النجاةِ والفوز؛ فاجعل عملك كلَّه خالصًا لوجهِ الله، لا رياءً ولا سمعةً ولا طلبًا لعرَضٍ من الدنيا؛ فالمخلصون هم الناجون المكرمون، الذين لا سلطانَ للشيطانِ عليهم؛ فراقب نيّتك في أعمالك: هل هي خالصةٌ لله؟ فطهّرها من شوائبِ الرياءِ والسمعة؛ فمن أخلص لله نجا وفاز، ومن راءى وطلب الدنيا خسر؛ فالإخلاصُ روحُ العمل، وبه يُقبَل ويُثاب عليه؛ فاجعل الإخلاصَ همّك في كلِّ عمل؛ فالله لا يقبل من العملِ إلا ما كان خالصًا له صوابًا على سنّةِ نبيّه؛ فأخلص لله، تكن من الناجين المكرمين."}},{"n":41,"reflection":{"text":"«أولئك لهم رزق معلوم» — أولئك المخلصون لهم رزقٌ معلومٌ في الجنّةِ محدّدٌ لهم؛ ففي هذا بشارةُ المخلصين بالرزقِ الكريم؛ فاعمل مخلصًا لتنال الرزقَ المعلومَ في الجنّة، فجزاءُ الإخلاصِ رزقٌ كريمٌ دائم، فاجتهد لتكون من أهله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ بإخلاصٍ لنيلِ الرزقِ المعلومِ في الجنّة."},"action":{"text":"اعمل بإخلاصٍ لله لتكون من المخلصين الذين لهم رزقٌ معلومٌ في الجنّةِ محدّدٌ مضمون «أولئك لهم رزق معلوم»؛ فجزاءُ الإخلاصِ رزقٌ كريمٌ دائمٌ لا ينقطع؛ فاجتهد في الإخلاصِ والعملِ الصالحِ لتنال هذا الرزقَ الكريم؛ فبادر بالأعمالِ الصالحةِ الخالصةِ لوجهِ الله؛ فمن أخلص لله ناله رزقُ الجنّةِ المعلومُ الكريم؛ فاجعل غايتك رضا الله ونعيمَ جنّته؛ فالرزقُ المعلومُ في الجنّةِ خيرٌ من كلِّ رزقِ الدنيا؛ فاعمل له عملَ من يرجو نعيمَ الجنّة؛ فمن آثر الإخلاصَ والعملَ لله نال الرزقَ الكريمَ الدائم؛ فاجتهد لتكون من أهلِ هذا النعيم؛ فالجنّةُ سلعةُ الله الغالية، ثمنُها الإيمانُ والإخلاصُ والعملُ الصالح."}},{"n":42,"reflection":{"text":"«فواكه وهم مكرمون» — الرزقُ المعلومُ فواكهُ لذيذةٌ متنوّعة، وهم مكرمون في الجنّة؛ ففي هذا وصفُ نعيمِ المخلصينَ وكرامتهم؛ فاعمل لتنال فواكهَ الجنّةِ وكرامتها، فالمخلصون منعَّمون مكرمون، فاجتهد لتكون من أهلِ هذا النعيمِ والكرامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ نعيمِ الجنّةِ وكرامتها."},"action":{"text":"اعمل بإخلاصٍ لتنال نعيمَ الجنّةِ من الفواكهِ اللذيذةِ المتنوّعة، والكرامةِ التي يكرَّم بها المخلصون فيها «فواكه وهم مكرمون»؛ فالمخلصون في الجنّةِ منعَّمون بأنواعِ اللذّات، مكرمون عند الله؛ فاجتهد لتكون من أهلِ هذا النعيمِ والكرامة؛ فبادر بالأعمالِ الصالحةِ الخالصةِ لوجهِ الله؛ فمن أخلص لله ناله نعيمُ الجنّةِ وكرامتها؛ فاجعل غايتك رضا الله ونعيمَ جنّته وكرامته؛ فكرامةُ الجنّةِ خيرٌ من كلِّ عزِّ الدنيا؛ فاعمل لها عملَ من يرجو نعيمَها وكرامتها؛ فالنعيمُ والكرامةُ لمن أخلص وعمل؛ فاجتهد لتكون من المكرمين المنعَّمين؛ فبعد تعبِ الدنيا نعيمٌ وكرامةٌ دائمةٌ في الجنّة."}},{"n":43,"reflection":{"text":"«في جنات النعيم» — هم في جنّاتِ النعيمِ الدائم؛ ففي هذا تقريرُ استقرارِ المخلصين في جنّاتِ النعيم؛ فاعمل لتكون في جنّاتِ النعيمِ الدائم، فنعيمُ الجنّةِ لا ينقطع، فاجتهد لتنال هذا النعيمَ المقيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للاستقرارِ في جنّاتِ النعيمِ الدائم."},"action":{"text":"اعمل بإخلاصٍ لتستقرَّ في جنّاتِ النعيمِ الدائمِ الذي أعدّه الله للمخلصين «في جنات النعيم»؛ فنعيمُ الجنّةِ مقيمٌ لا ينقطع ولا يزول؛ فاجتهد في الطاعةِ والإخلاصِ والعملِ الصالحِ لتنال هذا النعيمَ المقيم؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن أخلص وعمل استقرَّ في جنّاتِ النعيم؛ فاجعل غايتك هذا النعيمَ الدائم؛ فهو خيرٌ من كلِّ نعيمِ الدنيا الزائل؛ فاعمل له عملَ من يرجو الخلودَ في نعيمه؛ فالجنّةُ دارُ النعيمِ المقيمِ الذي لا يعقبه شقاء؛ فاجتهد لتكون من أهلها؛ فبعد تعبِ الدنيا القصيرِ نعيمٌ دائمٌ في جنّاتِ النعيم؛ فاصبر على الطاعةِ رجاءَ هذا النعيمِ الخالد؛ فالنعيمُ المقيمُ يستحقّ كلَّ جهدٍ وصبر."}},{"n":44,"reflection":{"text":"«على سرر متقابلين» — على أسرّةٍ مزيّنةٍ متقابلين ينظر بعضهم إلى بعضٍ في أنسٍ ومحبّة؛ ففي هذا وصفُ أنسِ أهلِ الجنّةِ وتحابّهم؛ فاعمل لتنال أنسَ الجنّةِ ومجالسَها، فأهلُ الجنّةِ في أنسٍ ومحبّةٍ متقابلين، فاجتهد لتكون من أهلِ هذا الأنسِ والنعيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ أنسِ الجنّةِ ومجالسِ أهلها المتحابّين."},"action":{"text":"اعمل بإخلاصٍ لتنال أنسَ الجنّةِ ومجالسَها، حيث يكون أهلها على أسرّةٍ مزيّنةٍ متقابلين ينظر بعضهم إلى بعضٍ في أنسٍ ومحبّةٍ وصفاء «على سرر متقابلين»؛ فأهلُ الجنّةِ في أنسٍ دائمٍ ومحبّةٍ خالصةٍ لا حقدَ فيها ولا حسد؛ فاجتهد لتكون من أهلِ هذا الأنسِ والنعيم؛ فبادر بالأعمالِ الصالحةِ الخالصةِ لوجهِ الله؛ واحرص على أن تكون صحبتك في الدنيا من الصالحين لتكون معهم في الجنّة؛ فالمرءُ مع من أحبّ؛ فأحبَّ الصالحين، وتحابَّ معهم في الله؛ فمن تحابَّ في الله كانوا على منابرَ من نورٍ يومَ القيامة، وفي الجنّةِ متقابلين متحابّين؛ فاجعل محبّتك في الله؛ فبها تنال أنسَ الجنّةِ ومجالسها؛ فالنعيمُ الأكبرُ الأنسُ بالأحبّةِ في جوارِ الله."}},{"n":45,"reflection":{"text":"«يطاف عليهم بكأس من معين» — يُطاف على أهلِ الجنّةِ بكأسٍ من خمرٍ جارٍ (من عينٍ جارية)؛ ففي هذا وصفُ شرابِ أهلِ الجنّة؛ فاعمل لتنال شرابَ الجنّةِ الطاهر، فأهلُ الجنّةِ يُنعَّمون بأطيبِ الشراب، فاجتهد لتكون من أهلِ هذا النعيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ شرابِ الجنّةِ الطاهر."},"action":{"text":"اعمل بإخلاصٍ لتنال شرابَ الجنّةِ الطاهرَ اللذيذ، حيث يُطاف على أهلها بكأسٍ من خمرٍ جارٍ من عينٍ جارية «يطاف عليهم بكأس من معين»؛ فأهلُ الجنّةِ يُنعَّمون بأطيبِ الشرابِ الذي لا يعقبه ضررٌ ولا سُكر؛ فاجتهد لتكون من أهلِ هذا النعيم؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن أخلص وعمل نال شرابَ الجنّةِ الطاهر؛ فاصبر عن محرّماتِ الدنيا (كالخمرِ المحرّم) رجاءَ شرابِ الجنّةِ الحلالِ الطيّب؛ فمن ترك شيئًا لله عوّضه خيرًا منه؛ فاعمل للجنّةِ ونعيمها؛ فشرابُ الجنّةِ خيرٌ من كلِّ لذّاتِ الدنيا المحرّمة؛ فاجتهد لتنال نعيمَها الطاهر."}},{"n":46,"reflection":{"text":"«بيضاء لذة للشاربين» — بيضاءَ صافيةً لذيذةً للشاربين لا كدرَ فيها؛ ففي هذا وصفُ صفاءِ شرابِ الجنّة؛ فاعمل لتنال شرابَ الجنّةِ الصافيَ اللذيذ، فنعيمُ الجنّةِ صافٍ لا كدرَ فيه، فاجتهد لتكون من أهلِ هذا النعيمِ الصافي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ نعيمِ الجنّةِ الصافي الخالي من الكدر."},"action":{"text":"اعمل بإخلاصٍ لتنال نعيمَ الجنّةِ الصافيَ اللذيذ، حيث شرابها بيضاءُ صافيةٌ لذيذةٌ للشاربين لا كدرَ فيها ولا شائبة «بيضاء لذة للشاربين»؛ فنعيمُ الجنّةِ صافٍ خالصٌ لا يشوبه كدرٌ ولا نغص، بخلافِ لذّاتِ الدنيا التي يشوبها التعبُ والكدر؛ فاجتهد لتكون من أهلِ هذا النعيمِ الصافي؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن أخلص وعمل نال نعيمَ الجنّةِ الصافي؛ فلذّاتُ الدنيا مكدَّرةٌ منغَّصة، ونعيمُ الجنّةِ صافٍ خالد؛ فآثِر النعيمَ الصافيَ الباقي على المتاعِ المكدَّرِ الفاني؛ فاعمل للجنّةِ ونعيمها الصافي؛ فالنعيمُ الخالي من الكدرِ يستحقّ كلَّ جهدٍ وصبر؛ فاصبر على تعبِ الطاعةِ رجاءَ نعيمِ الجنّةِ الصافي."}},{"n":47,"reflection":{"text":"«لا فيها غول ولا هم عنها ينزفون» — لا في خمرِ الجنّةِ ضررٌ للعقلِ أو البدن، ولا هم يسكرون منها ويذهب عقلهم؛ ففي هذا كمالُ نعيمِ الجنّةِ بلا ضرر؛ فاعمل لتنال نعيمًا لا ضررَ فيه، فنعيمُ الجنّةِ لذّةٌ بلا أذًى ولا نقص، فاجتهد لتكون من أهلِ هذا النعيمِ الكامل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ نعيمِ الجنّةِ الكاملِ بلا ضرر."},"action":{"text":"اعمل بإخلاصٍ لتنال نعيمَ الجنّةِ الكاملَ الذي لا ضررَ فيه ولا نقص، حيث خمرها لا تُذهِب العقلَ ولا تضرّ البدنَ ولا يسكرون منها «لا فيها غول ولا هم عنها ينزفون»؛ فنعيمُ الجنّةِ لذّةٌ خالصةٌ بلا أذًى ولا نقصٍ ولا عاقبةٍ سيّئة، بخلافِ لذّاتِ الدنيا التي يعقبها الضررُ والندم؛ فاجتهد لتكون من أهلِ هذا النعيمِ الكامل؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن أخلص وعمل نال نعيمَ الجنّةِ الكامل؛ فلذّاتُ الدنيا المحرّمةُ يعقبها الضررُ والعقوبة، ونعيمُ الجنّةِ لذّةٌ بلا ضرر؛ فآثِر النعيمَ الكاملَ الباقي على اللذّةِ الضارّةِ الفانية؛ فاعمل للجنّةِ ونعيمها الكامل؛ فالنعيمُ الخالي من الضررِ يستحقّ كلَّ جهد."}},{"n":48,"reflection":{"text":"«وعندهم قاصرات الطرف عين» — وعندهم في الجنّةِ نساءٌ قاصراتُ أعينهنّ على أزواجهنّ (عفيفات) واسعاتُ العيونِ حِسانٌ؛ ففي هذا وصفُ أزواجِ أهلِ الجنّة؛ فاعمل لتنال نعيمَ الجنّةِ وأزواجَها، فأهلُ الجنّةِ ينعمون بأزواجٍ عفيفاتٍ حسان، فاجتهد لتكون من أهلِ هذا النعيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ نعيمِ الجنّةِ وأزواجها العفيفات."},"action":{"text":"اعمل بإخلاصٍ لتنال نعيمَ الجنّةِ وأزواجَها، حيث ينعم أهلها بنساءٍ قاصراتِ الطرفِ (عفيفاتٍ لا ينظرن إلا إلى أزواجهنّ) واسعاتِ العيونِ حسان «وعندهم قاصرات الطرف عين»؛ فأهلُ الجنّةِ يُنعَّمون بأزواجٍ عفيفاتٍ حسانٍ كاملاتِ الجمالِ والخلق؛ فاجتهد لتكون من أهلِ هذا النعيم؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ واصبر عن الحرامِ في الدنيا (كالنظرِ المحرّمِ والعلاقاتِ المحرّمة) رجاءَ نعيمِ الجنّةِ الحلال؛ فمن غضَّ بصره عن الحرامِ وحفظ فرجه في الدنيا نال نعيمَ الجنّةِ وأزواجَها؛ فالعفّةُ في الدنيا سبيلُ النعيمِ في الآخرة؛ فاحفظ بصرك وفرجك عن الحرام؛ فمن ترك شهوةً محرّمةً لله عوّضه الله خيرًا منها في الجنّة."}},{"n":49,"reflection":{"text":"«كأنهن بيض مكنون» — كأنّ تلك النساءَ في صفائهنّ ونقائهنّ بيضٌ مصونٌ مستور؛ ففي هذا وصفُ صفاءِ أزواجِ الجنّة؛ فاعمل لتنال نعيمَ الجنّةِ الصافي، فأزواجُ الجنّةِ في غايةِ الصفاءِ والنقاء، فاجتهد لتكون من أهلِ هذا النعيمِ الصافي.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ نعيمِ الجنّةِ الصافي النقيّ."},"action":{"text":"اعمل بإخلاصٍ لتنال نعيمَ الجنّةِ الصافيَ النقيّ، حيث أزواجُ أهلها في صفائهنّ ونقائهنّ كأنهنّ بيضٌ مصونٌ مستورٌ لم تمسّه الأيدي «كأنهن بيض مكنون»؛ فهنّ في غايةِ الصفاءِ والنقاءِ والحسن؛ فاجتهد لتكون من أهلِ هذا النعيمِ الصافي؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن أخلص وعمل وحفظ نفسه عن الحرامِ نال نعيمَ الجنّةِ الصافي؛ فالعفّةُ والطهارةُ في الدنيا سبيلُ النعيمِ الطاهرِ في الآخرة؛ فاحرص على طهارةِ قلبك وجوارحك عن الحرام؛ فمن طهّر نفسه في الدنيا نال النعيمَ الطاهرَ في الجنّة؛ فاعمل للجنّةِ ونعيمها النقيّ؛ فالنعيمُ الصافي النقيُّ يستحقّ الصبرَ على العفّةِ والطهارةِ في الدنيا؛ فآثِر الطاهرَ الباقي على الدنسِ الفاني."}},{"n":50,"reflection":{"text":"«فأقبل بعضهم على بعض يتساءلون» — فأقبل أهلُ الجنّةِ بعضهم على بعضٍ يتساءلون عن أحوالهم في الدنيا؛ ففي هذا تحدّثُ أهلِ الجنّةِ وتذكّرهم لنعمِ الله؛ فاعمل لتكون في مجالسِ أهلِ الجنّةِ المتحابّين، فأهلُ الجنّةِ يتذاكرون نعمَ الله وأحوالهم، فاجتهد لتنال هذا الأنسَ والنعيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ مجالسِ أهلِ الجنّةِ المتحابّين المتذاكرين."},"action":{"text":"اعمل بإخلاصٍ لتكون في مجالسِ أهلِ الجنّةِ المتحابّين، حيث يقبل بعضهم على بعضٍ يتساءلون ويتذاكرون أحوالهم في الدنيا ونعمَ الله عليهم «فأقبل بعضهم على بعض يتساءلون»؛ فأهلُ الجنّةِ في أنسٍ ومحبّةٍ وتذاكرٍ لنعمِ الله وفضله؛ فاجتهد لتكون من أهلِ هذا الأنسِ والنعيم؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ واحرص على صحبةِ الصالحين في الدنيا لتكون معهم في الجنّة؛ فمن تحابَّ في الله دامت مودّتهم في الآخرة؛ فاجعل مجالسك في الدنيا مجالسَ ذكرٍ وخير، لتكون في مجالسِ الجنّةِ المتحابّة؛ فالأنسُ بالأحبّةِ في ذكرِ نعمِ الله من أعظمِ نعيمِ الجنّة؛ فاعمل للجنّةِ وأنسها؛ فالمجالسُ الصالحةُ في الدنيا سبيلٌ لمجالسِ الجنّةِ المتحابّة."}},{"n":51,"reflection":{"text":"«قال قائل منهم إني كان لي قرين» — قال قائلٌ من أهلِ الجنّة: إني كان لي في الدنيا قرينٌ (صاحبٌ) ينكر البعث؛ ففي هذا تذكّرُ المؤمنِ لقرينِ السوءِ في الدنيا؛ فاحذر قرينَ السوءِ الذي يجرّك إلى الكفرِ والمعصية، واختر القرينَ الصالح، فقرينُ السوءِ يجرّ إلى الهلاك، والقرينُ الصالحُ يعين على الخير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قرينِ السوء، واختيارُ القرينِ الصالح."},"action":{"text":"احذر قرينَ السوءِ الذي يجرّك إلى الكفرِ والمعصيةِ وإنكارِ الحقّ، كما ذكر المؤمنُ في الجنّةِ أنه كان له في الدنيا قرينٌ ينكر البعثَ ويثبّطه عن الإيمان «إني كان لي قرين»؛ فاختر القرينَ الصالحَ الذي يعينك على الخيرِ ويذكّرك بالله؛ فالمرءُ على دينِ خليله؛ فقرينُ السوءِ يجرّ إلى الهلاك، والقرينُ الصالحُ يعين على الخير؛ فاحرص على صحبةِ الصالحين، واجتنب قرناءَ السوء؛ فمن صاحب الأخيارَ أعانوه على الطاعة، ومن صاحب الأشرارَ جرّوه إلى المعصية؛ فمثلُ الجليسِ الصالحِ كحاملِ المسك، وجليسِ السوءِ كنافخِ الكير؛ فاختر جلساءك بعناية؛ فالصحبةُ الصالحةُ من أعظمِ العونِ على الجنّة، وصحبةُ السوءِ من أعظمِ أسبابِ النار؛ فاجعل قرناءك من أهلِ الإيمانِ والتقوى."}},{"n":52,"reflection":{"text":"«يقول أإنك لمن المصدقين» — كان قرينُ السوءِ يقول لي منكرًا: أإنك لمن المصدّقين بالبعثِ والجزاء؟ ففي هذا تشكيكُ قرينِ السوءِ في الحقّ؛ فاحذر من يشكّكك في الحقِّ والإيمان، واثبت على تصديقك بالبعثِ رغمَ تشكيكِ المشكّكين، فقرينُ السوءِ يشكّك في الحقّ، فلا تسمع له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على التصديقِ بالحقِّ رغمَ تشكيكِ المشكّكين."},"action":{"text":"احذر من يشكّكك في الحقِّ والإيمانِ بالبعثِ والجزاء، كما كان قرينُ السوءِ يشكّك المؤمنَ ويستنكر تصديقه: «أإنك لمن المصدقين»؛ فاثبت على تصديقك بالحقِّ والبعثِ والجزاءِ رغمَ تشكيكِ المشكّكين واستنكارِ المستنكرين؛ فقرناءُ السوءِ يشكّكون في الحقِّ ويثبّطون عن الإيمان؛ فلا تسمع لهم ولا تجالسهم؛ فالتشكيكُ في الحقِّ من أعظمِ ما يفسد الإيمان؛ فرسّخ يقينك بالبعثِ والجزاء، ولا تدع الشكوكَ والشبهاتِ تزلزل إيمانك؛ فمن ثبت على يقينه نجا، ومن استجاب للمشكّكين ضلّ؛ فاحذر من يبثّ الشكوكَ في الدينِ والغيبِ والبعث؛ وقوِّ إيمانك بالعلمِ والتدبّرِ والصحبةِ الصالحة؛ فالثباتُ على الحقِّ عند التشكيكِ من علاماتِ صدقِ الإيمان؛ فلا يزعزعك تشكيكُ الشاكّين؛ بل ازدد يقينًا وثباتًا."}},{"n":53,"reflection":{"text":"«أإذا متنا وكنا ترابا وعظاما أإنا لمدينون» — كان قرينُ السوءِ يقول منكرًا: أإذا متنا وصرنا ترابًا وعظامًا أإنا لمحاسَبون مجزيّون؟ ففي هذا إنكارُ قرينِ السوءِ للبعثِ والحساب؛ فلا يزلزلك إنكارُ المنكرين للبعثِ والحساب، فمن خلقك قادرٌ على بعثك وحسابك، فرسّخ يقينك بالحساب، ولا تسمع لمنكريه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على اليقينِ بالبعثِ والحسابِ رغمَ إنكارِ المنكرين."},"action":{"text":"لا يزلزلك إنكارُ المنكرين للبعثِ والحساب، كما كان قرينُ السوءِ ينكرهما مستبعدًا: «أإذا متنا وكنا ترابا وعظاما أإنا لمدينون» (محاسَبون مجزيّون)؛ فمن خلقك أوّلًا من العدمِ قادرٌ على بعثك بعد الموتِ ومحاسبتك؛ فرسّخ يقينك بالبعثِ والحسابِ والجزاء؛ ولا تسمع لمنكريه من قرناءِ السوءِ والمشكّكين؛ فالبعثُ والحسابُ حقٌّ لا شكَّ فيه؛ فمن أيقن بالحسابِ عمل له واستعدّ؛ فاعمل لآخرتك عملَ من يوقن أنه محاسَبٌ مجزيٌّ بعمله؛ فلا تدع إنكارَ المنكرين يؤثر في يقينك؛ بل ازدد ثباتًا ويقينًا؛ فالمنكرون للبعثِ والحسابِ خاسرون نادمون يومَ يرونه؛ فاثبت على يقينك، واعمل ليومِ الحساب؛ فالحسابُ آتٍ، والجزاءُ واقعٌ بالعدل؛ فاستعدَّ له بالإيمانِ والعملِ الصالح."}},{"n":54,"reflection":{"text":"«قال هل أنتم مطلعون» — قال المؤمنُ لإخوانه في الجنّة: هل أنتم مطّلعون معي على أهلِ النارِ لأرى قريني؟ ففي هذا اطّلاعُ أهلِ الجنّةِ على أهلِ النار؛ فاعمل لتكون من أهلِ الجنّةِ المطّلعين المنعَّمين، لا من أهلِ النارِ المعذّبين، فشتّانَ بين المطّلعِ الناجي والمطَّلَعِ عليه الهالك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكون من أهلِ الجنّةِ الناجين لا من أهلِ النار."},"action":{"text":"اعمل بإخلاصٍ لتكون من أهلِ الجنّةِ المنعَّمين الذين يطّلعون على أهلِ النار، لا من أهلِ النارِ المعذّبين، كما اطّلع المؤمنُ في الجنّةِ على قرينه في النار «قال هل أنتم مطلعون»؛ فشتّانَ بين المطّلعِ الناجي في الجنّةِ والمطَّلَعِ عليه الهالكِ في النار؛ فاختر لنفسك من الآن في أيِّ الفريقين تكون بعملك؛ فبادر بالإيمانِ والعملِ الصالحِ لتكون من أهلِ الجنّة؛ واحذر الكفرَ والمعاصيَ الموصلةَ إلى النار؛ فمن آمن وعمل صالحًا كان من الناجين المطّلعين، ومن كفر وعصى كان من الهالكين المطَّلَعِ عليهم؛ فاجتهد لتكون من أهلِ الجنّة؛ فراجع نفسك: أمن أهلِ الجنّةِ أنت أم من أهلِ النار؟ فاعمل لتكون من الناجين المكرمين؛ فالعبرةُ بالعمل، والاختيارُ بيدك."}},{"n":55,"reflection":{"text":"«فاطلع فرآه في سواء الجحيم» — فاطّلع المؤمنُ فرأى قرينَه في وسطِ النار؛ ففي هذا مصيرُ قرينِ السوءِ المنكرِ للبعث؛ فاحذر مصيرَ منكري البعثِ من قرناءِ السوء، فقرينُ السوءِ في وسطِ الجحيم، فاجتنب صحبتهم، واثبت على إيمانك لتنجو من مصيرهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مصيرِ قرناءِ السوءِ، والثباتُ على الإيمان."},"action":{"text":"احذر مصيرَ قرناءِ السوءِ المنكرين للبعثِ والحق، فقد اطّلع المؤمنُ في الجنّةِ فرأى قرينَه في وسطِ الجحيمِ يُعذَّب «فاطلع فرآه في سواء الجحيم»؛ فمصيرُ قرينِ السوءِ المنكرِ للبعثِ العذابُ في وسطِ النار؛ فاجتنب صحبةَ قرناءِ السوءِ الذين يجرّون إلى الكفرِ والمعصيةِ وإنكارِ الحق؛ واثبت على إيمانك وتصديقك بالحقِّ لتنجو من مصيرهم؛ فمن اتّبع قرينَ السوءِ وأنكر الحقَّ لحقه مصيره في النار؛ ومن ثبت على الإيمانِ ونجا من قرينِ السوءِ نجا؛ فاحذر من يشكّكك في الحقِّ ويثبّطك عن الإيمان؛ فاختر القرينَ الصالحَ الذي يعينك على الجنّة؛ فالصحبةُ الصالحةُ سبيلُ النجاة، وصحبةُ السوءِ سبيلُ الهلاك؛ فاجعل قرناءك من أهلِ الإيمانِ والتقوى؛ فمن نجا من قرناءِ السوءِ وثبت على الحقِّ فاز."}},{"n":56,"reflection":{"text":"«قال تالله إن كدت لتردين» — قال المؤمنُ لقرينه: والله إن كدت تهلكني بإغوائك لو أطعتك؛ ففي هذا خطرُ قرينِ السوءِ على الدين؛ فاعلم خطرَ قرينِ السوءِ الذي يكاد يهلكك بإغوائه، فاحذره واحمد الله أن نجّاك من طاعته، فقرينُ السوءِ قريبٌ من الإهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ خطرِ قرينِ السوءِ على الدين، والحذرُ منه."},"action":{"text":"اعلم خطرَ قرينِ السوءِ العظيمَ على دينك، فإنه يكاد يهلكك بإغوائه لو أطعته، كما قال المؤمنُ لقرينه في النار: «تالله إن كدت لتردين» أي كدت تهلكني بإغوائك؛ فقرينُ السوءِ قريبٌ من إهلاكِ صاحبه بجرّه إلى الكفرِ والمعصية؛ فاحذر قرناءَ السوءِ أشدَّ الحذر؛ واحمد الله أن نجّاك من طاعتهم واتّباعهم؛ فمن نجا من قرينِ السوءِ نجا من الهلاك؛ فاجتنب صحبةَ من يجرّك إلى المعصيةِ والباطل؛ واختر القرينَ الصالحَ الذي يعينك على الطاعة؛ فالصحبةُ لها أثرٌ عظيمٌ في الدينِ والمصير؛ فكم من قرينِ سوءٍ أهلك صاحبه، وكم من قرينٍ صالحٍ أنجى صاحبه؛ فاحذر قرينَ السوء، والزم صحبةَ الأخيار؛ فمن سلم من قرينِ السوءِ سلم دينه، ومن اتّبعه هلك."}},{"n":57,"reflection":{"text":"«ولولا نعمة ربي لكنت من المحضرين» — قال المؤمن: ولولا فضلُ ربّي عليّ بالإيمانِ والثباتِ لكنت من المحضَرين في النارِ معك؛ ففي هذا أنّ النجاةَ بفضلِ الله؛ فانسب نجاتك وهدايتك إلى فضلِ الله لا إلى نفسك، فلولا فضلُ الله لكنت من الهالكين، فاشكر فضلَ الله عليك بالهدايةِ والثبات.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"نسبةُ النجاةِ والهدايةِ إلى فضلِ الله وشكرُه عليها."},"action":{"text":"انسب نجاتك وهدايتك وثباتك على الإيمانِ إلى فضلِ الله ورحمته لا إلى نفسك وحولك، كما قال المؤمن: «ولولا نعمة ربي لكنت من المحضرين» في النار؛ فلولا فضلُ الله عليك بالإيمانِ والهدايةِ والثباتِ لكنت من الهالكين المعذّبين؛ فاشكر فضلَ الله عليك بنعمةِ الهدايةِ والإيمانِ والثبات؛ فكم من ضالٍّ لم يهده الله، وأنت في نعمةِ الهداية؛ فاحمد الله على هذه النعمةِ العظمى؛ ولا تنسب هدايتك إلى ذكائك أو جهدك، بل إلى فضلِ الله ومنّته؛ فمن نسب الهدى إلى فضلِ الله تواضع وشكر، ومن نسبه إلى نفسه تكبّر وعُجِب؛ فاجعل قلبك ممتلئًا بشكرِ فضلِ الله عليك بالهداية؛ واطلب من الله الثباتَ عليها؛ فالهدايةُ نعمةٌ من الله، والثباتُ عليها فضلٌ منه؛ فاشكره واسأله المزيدَ من فضله."}},{"n":58,"reflection":{"text":"«أفما نحن بميتين» — يقول أهلُ الجنّةِ مستبشرين: أفما نحن بميتين بعد اليوم؟ ففي هذا فرحُ أهلِ الجنّةِ بالخلودِ ونفيِ الموت؛ فاعمل للجنّةِ التي لا موتَ فيها، فأهلُ الجنّةِ خالدون لا يموتون، فاجتهد لتنال هذا الخلودَ في النعيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للجنّةِ التي لا موتَ فيها ولا فناء."},"action":{"text":"اعمل بإخلاصٍ لتنال الجنّةَ التي لا موتَ فيها ولا فناء، حيث يستبشر أهلها بالخلودِ ونفيِ الموت: «أفما نحن بميتين»؛ فأهلُ الجنّةِ خالدون فيها أبدًا لا يموتون ولا يفنون؛ فاجتهد لتنال هذا الخلودَ في النعيم؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن أخلص وعمل نال الخلودَ في الجنّة؛ فالجنّةُ دارُ الخلودِ والبقاء، لا موتَ فيها ولا زوال؛ فهي خيرٌ من الدنيا الفانيةِ التي يعقبها الموت؛ فآثِر الباقيَ على الفاني؛ فاعمل للجنّةِ ونعيمها الخالد؛ فالخلودُ في النعيمِ يستحقّ كلَّ جهدٍ وصبر؛ فمن عمل للدارِ الباقيةِ فاز بها؛ فاجعل غايتك الخلودَ في جنّةِ النعيم؛ فبعد موتِ الدنيا حياةٌ خالدةٌ في الجنّةِ لأهلِ الإيمانِ والعمل."}},{"n":59,"reflection":{"text":"«إلا موتتنا الأولى وما نحن بمعذبين» — إلا موتتنا الأولى في الدنيا، وما نحن بمعذّبين بعد اليوم؛ ففي هذا تقريرُ خلودِ أهلِ الجنّةِ ونجاتهم من العذاب؛ فاعمل لتنجو من العذابِ وتخلد في النعيم، فأهلُ الجنّةِ آمنون من الموتِ والعذاب، فاجتهد لتكون من أهلِ هذا الأمنِ والنعيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنجاةِ من العذابِ والخلودِ في نعيمِ الجنّة."},"action":{"text":"اعمل بإخلاصٍ لتنجو من العذابِ وتخلد في نعيمِ الجنّة، حيث يقول أهلها: ما نحن بميتين إلا موتتنا الأولى في الدنيا، وما نحن بمعذّبين «إلا موتتنا الأولى وما نحن بمعذبين»؛ فأهلُ الجنّةِ آمنون من الموتِ والعذاب، خالدون في النعيم؛ فاجتهد لتكون من أهلِ هذا الأمنِ والنعيمِ الخالد؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن أخلص وعمل نجا من العذابِ وخلد في النعيم؛ فالأمنُ من الموتِ والعذابِ في الجنّةِ من أعظمِ النعم؛ فاعمل لتنال هذا الأمنَ والخلود؛ فبعد موتةِ الدنيا حياةٌ خالدةٌ آمنةٌ في الجنّة؛ فاجعل غايتك النجاةَ من العذابِ والخلودَ في النعيم؛ فمن عمل للجنّةِ نجا من النار؛ فاجتهد لتكون من الآمنين المنعَّمين الخالدين."}},{"n":60,"reflection":{"text":"«إن هذا لهو الفوز العظيم» — إنّ هذا (نعيمَ الجنّةِ والنجاةَ من العذاب) لهو الفوزُ العظيم؛ ففي هذا تقريرُ أنّ الفوزَ الحقيقيَّ نعيمُ الجنّة؛ فاعلم أنّ الفوزَ العظيمَ ليس في متاعِ الدنيا بل في نعيمِ الجنّةِ والنجاةِ من النار، فاجعل غايتك هذا الفوزَ، واعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ الفوزَ العظيمَ نعيمُ الجنّةِ والنجاةُ من النار."},"action":{"text":"اعلم أنّ الفوزَ العظيمَ الحقيقيَّ ليس في مكاسبِ الدنيا وملذّاتها الزائلة، بل في نعيمِ الجنّةِ والنجاةِ من النار «إن هذا لهو الفوز العظيم»؛ فاجعل غايتك الكبرى هذا الفوزَ العظيم؛ واعمل له بالإيمانِ والعملِ الصالحِ والإخلاص؛ فمن دخل الجنّةَ ونجا من النارِ فقد فاز الفوزَ العظيم؛ ومن حُرِم الجنّةَ ودخل النارَ فقد خسر الخسرانَ المبين؛ فلا تجعل همّك الأكبرَ متاعَ الدنيا الفاني؛ بل اجعله الفوزَ بالجنّةِ والنجاةَ من النار؛ فوازن بين فوزِ الدنيا الزائلِ وفوزِ الآخرةِ الباقي؛ فآثِر الفوزَ العظيمَ الباقي؛ فاعمل للجنّةِ عملَ من يرجو الفوزَ العظيم؛ فمن فاز بالجنّةِ فاز بكلِّ خير، ومن خسرها خسر كلَّ خير؛ فاجعل الفوزَ العظيمَ نصب عينيك، واعمل له بجدٍّ واجتهاد."}},{"n":61,"reflection":{"text":"«لمثل هذا فليعمل العاملون» — لأجلِ مثلِ هذا الفوزِ العظيمِ فليعمل العاملون ويجتهد المجتهدون؛ ففي هذا الحثُّ على العملِ لنيلِ الفوزِ العظيم؛ فاعمل واجتهد لنيلِ الفوزِ العظيمِ (الجنّة)، فمثلُ هذا النعيمِ يستحقّ أن يُعمَل له ويُبذَل فيه الجهد، فاجعل عملك للفوزِ العظيمِ لا للدنيا الزائلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ والاجتهادُ لنيلِ الفوزِ العظيم."},"action":{"text":"اعمل واجتهد لنيلِ الفوزِ العظيم (نعيمِ الجنّةِ والنجاةِ من النار)، فلأجلِ مثلِ هذا النعيمِ العظيمِ فليعمل العاملون ويتنافس المتنافسون «لمثل هذا فليعمل العاملون»؛ فمثلُ هذا الفوزِ يستحقّ أن يُبذَل فيه الجهدُ والوقتُ والمال؛ فاجعل عملك واجتهادك للفوزِ العظيمِ لا للدنيا الزائلة؛ فما أحرى بالعاقلِ أن يجتهد لنعيمٍ خالدٍ لا ينقطع؛ فبادر بالأعمالِ الصالحة، وسابق إلى الخيرات؛ فالجنّةُ سلعةُ الله الغالية، تستحقّ الجدَّ والاجتهاد؛ فلا تكسل عن العملِ لها، ولا تفرّط في تحصيلها؛ فمن عمل لها بجدٍّ نالها، ومن تكاسل حُرِمها؛ فاجعل همّك الأكبرَ العملَ للفوزِ العظيم؛ فكلُّ جهدٍ يُبذَل لأجلِ الجنّةِ فهو رابحٌ لا محالة؛ فاعمل للفوزِ العظيمِ عملَ الجادّين المجتهدين؛ فالنعيمُ الخالدُ ثمنُه العملُ الصالح."}},{"n":62,"reflection":{"text":"«أذلك خير نزلا أم شجرة الزقوم» — أذلك النعيمُ (الجنّة) خيرٌ ضيافةً أم شجرةُ الزقّومِ (طعامُ أهلِ النار)؟ ففي هذا الموازنةُ بين نعيمِ الجنّةِ وطعامِ النار؛ فوازن بين نعيمِ الجنّةِ وعذابِ النار، واختر لنفسك خيرَ النزلين، فشتّانَ بين نعيمِ الجنّةِ وزقّومِ النار، فاعمل لنعيمِ الجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الموازنةُ بين نعيمِ الجنّةِ وعذابِ النار، واختيارُ الأفضل."},"action":{"text":"وازن بين نعيمِ الجنّةِ (الفوزِ العظيم) وبين عذابِ النارِ وطعامِ أهلها من شجرةِ الزقّومِ الخبيثة «أذلك خير نزلا أم شجرة الزقوم»؛ فشتّانَ بين النزلين: نعيمُ الجنّةِ الطيّبُ الدائم، وزقّومُ النارِ الخبيثُ المؤلم؛ فاختر لنفسك خيرَ النزلين بعملك؛ فاعمل لنعيمِ الجنّةِ واجتنب أسبابَ عذابِ النار؛ فمن آمن وعمل صالحًا نال نعيمَ الجنّة، ومن كفر وعصى ذاق زقّومَ النار؛ فراجع نفسك: لأيِّ النزلين تعمل؟ فبادر بالإيمانِ والعملِ الصالحِ لتنال نعيمَ الجنّة؛ واحذر الكفرَ والمعاصيَ الموصلةَ إلى عذابِ النار؛ فالعاقلُ من عمل لخيرِ النزلين؛ فوازن بين النعيمِ والعذاب، واختر ما ينجّيك ويسعدك؛ فالجنّةُ خيرٌ من النارِ بلا شكّ؛ فاعمل لها، واجتنب أسبابَ النار."}},{"n":63,"reflection":{"text":"«إنا جعلناها فتنة للظالمين» — إنا جعلنا شجرةَ الزقّومِ فتنةً واختبارًا للظالمين (استبعدوا أن تنبت شجرةٌ في النار)؛ ففي هذا أنّ الظالمين يُفتَنون بما لا يعقلون من قدرةِ الله؛ فاحذر أن تكون ممّن يُفتَن ويكذّب بما لا يدرك من قدرةِ الله، فسلّم لقدرةِ الله فيما أخبر به، ولا تكذّب بما لا تحيط به علمًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لقدرةِ الله فيما أخبر به، وعدمُ التكذيبِ بما لا يُدرَك."},"action":{"text":"احذر أن تكون من الظالمين الذين يُفتَنون ويكذّبون بما لا يدركون من قدرةِ الله وأخباره، كما جعل الله شجرةَ الزقّومِ فتنةً لهم إذ استبعدوا أن تنبت شجرةٌ في النار «إنا جعلناها فتنة للظالمين»؛ فسلّم لقدرةِ الله فيما أخبر به من الغيبِ والآخرة، ولا تكذّب بما لا تحيط به علمًا؛ فقدرةُ الله لا تحدّها العقولُ ولا المقاييسُ الدنيوية؛ فما أخبر به الله ورسولُه فهو حقٌّ وإن لم تدركه عقولنا؛ فاحذر التكذيبَ بالغيبِ لمجرّدِ أنه يخالف المألوف؛ فمن سلّم لأخبارِ الله واعتقد قدرته المطلقةَ نجا، ومن كذّب بما لا يدركه فُتِن وضلّ؛ فاجعل عقلك تابعًا للوحيِ لا حاكمًا عليه؛ فالله على كلِّ شيءٍ قدير؛ فسلّم لقدرته وأخباره، ولا تكن من المفتونين المكذّبين."}},{"n":64,"reflection":{"text":"«إنها شجرة تخرج في أصل الجحيم» — إنّ شجرةَ الزقّومِ تخرج في قعرِ النار وأصلها؛ ففي هذا وصفُ طعامِ أهلِ النار؛ فاحذر أن تكون من أهلِ النارِ الذين طعامهم الزقّوم، فاعمل لتنجو من هذا المصير، فطعامُ النارِ خبيثٌ يخرج من قعرها، فاجتنب أسبابَ النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن تكون من أهلِ النارِ الذين طعامهم الزقّوم."},"action":{"text":"احذر أن تكون من أهلِ النارِ الذين طعامهم شجرةُ الزقّومِ الخبيثةُ التي تخرج في قعرِ الجحيمِ وأصله «إنها شجرة تخرج في أصل الجحيم»؛ فاعمل بالإيمانِ والعملِ الصالحِ لتنجو من هذا المصيرِ الأليم؛ فطعامُ أهلِ النارِ خبيثٌ مؤلمٌ يخرج من قعرها؛ فاجتنب أسبابَ النار: من الكفرِ والشركِ والمعاصي؛ والزم أسبابَ الجنّة: من التوحيدِ والطاعةِ والتوبة؛ فمن آمن وعمل صالحًا نجا من النارِ وطعامها، ومن كفر وعصى ذاق زقّومها؛ فاجعل همّك النجاةَ من النارِ ونعيمَ الجنّة؛ فبادر بالتوبةِ والعملِ الصالح؛ فالنارُ وطعامها مصيرُ الكافرين والعصاة؛ فاحذرها بالعملِ الصالحِ والبعدِ عن المعاصي؛ فمن اتّقى النارَ ولو بشقِّ تمرةٍ نجا؛ فاعمل لتنجو من النارِ وطعامها الخبيث."}},{"n":65,"reflection":{"text":"«طلعها كأنه رءوس الشياطين» — ثمرُ شجرةِ الزقّومِ في قبحه وبشاعته كأنه رؤوسُ الشياطين؛ ففي هذا تصويرُ بشاعةِ طعامِ أهلِ النار؛ فاحذر مصيرَ أهلِ النارِ وطعامَهم البشع، فاعمل لتنجو منه، فطعامُ النارِ في غايةِ القبحِ والبشاعة، فاجتنب أسبابَ النارِ لتنجو.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من طعامِ أهلِ النارِ البشع، والعملُ للنجاة."},"action":{"text":"احذر مصيرَ أهلِ النارِ وطعامَهم البشعَ القبيح، فثمرُ شجرةِ الزقّومِ في قبحه كأنه رؤوسُ الشياطينِ في البشاعةِ والنفور «طلعها كأنه رءوس الشياطين»؛ فاعمل بالإيمانِ والعملِ الصالحِ لتنجو من هذا الطعامِ البشعِ والمصيرِ الأليم؛ فطعامُ أهلِ النارِ في غايةِ القبحِ والمرارةِ والبشاعة؛ فاجتنب أسبابَ النار لتنجو من طعامها؛ فمن آمن وعمل صالحًا نجا من النارِ وزقّومها، ومن كفر وعصى ذاق طعامها البشع؛ فاستحضر بشاعةَ طعامِ أهلِ النار؛ فيحملك ذلك على الحذرِ من أسبابِ النار؛ فاعمل للجنّةِ ونعيمها الطيّب، واجتنب النارَ وطعامها البشع؛ فبادر بالتوبةِ والعملِ الصالح؛ فالنجاةُ من النارِ وطعامها بالإيمانِ والطاعةِ والبعدِ عن المعاصي؛ فاعمل لتنجو من هذا المصيرِ البشع؛ فالجنّةُ وطعامها الطيّبُ خيرٌ من النارِ وزقّومها البشع."}},{"n":66,"reflection":{"text":"«فإنهم لآكلون منها فمالئون منها البطون» — فإنّ أهلَ النارِ لآكلون من شجرةِ الزقّومِ حتى يملؤوا منها بطونهم من شدّةِ الجوع؛ ففي هذا شدّةُ عذابِ أهلِ النارِ بالطعامِ الخبيث؛ فاحذر أن تكون من أهلِ النارِ الذين يأكلون الزقّوم، فاعمل لتنجو من هذا العذاب، فطعامُ النارِ عذابٌ يُملأ منه البطون، فاجتنب أسبابَ النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ أهلِ النارِ بالطعامِ الخبيث، والعملُ للنجاة."},"action":{"text":"احذر أن تكون من أهلِ النارِ الذين يأكلون من شجرةِ الزقّومِ حتى يملؤوا منها بطونهم من شدّةِ الجوعِ والعذاب «فإنهم لآكلون منها فمالئون منها البطون»؛ فاعمل بالإيمانِ والعملِ الصالحِ لتنجو من هذا العذابِ الأليم؛ فطعامُ أهلِ النارِ عذابٌ يُملأ منه البطونُ ثم يُشرَب عليه الحميم؛ فاجتنب أسبابَ النار لتنجو من طعامها وعذابها؛ فمن آمن وعمل صالحًا نجا من النارِ وطعامها، ومن كفر وعصى ذاق عذابها؛ فاستحضر شدّةَ عذابِ أهلِ النارِ بالطعامِ الخبيث؛ فيحملك ذلك على الحذرِ من أسبابِ النار؛ فاعمل للجنّةِ ونعيمها، واجتنب النارَ وعذابها؛ فبادر بالتوبةِ والعملِ الصالح؛ فالنجاةُ من عذابِ النارِ بالإيمانِ والطاعة؛ فاعمل لتنجو من هذا المصيرِ الأليم؛ فنعيمُ الجنّةِ خيرٌ من عذابِ النارِ بلا قياس."}},{"n":67,"reflection":{"text":"«ثم إن لهم عليها لشوبا من حميم» — ثم إنّ لأهلِ النارِ على طعامِ الزقّومِ خليطًا من ماءٍ حارٍّ شديدِ الحرارة؛ ففي هذا مضاعفةُ عذابِ أهلِ النار؛ فاحذر مصيرَ أهلِ النارِ الذين يشربون الحميمَ على الزقّوم، فاعمل لتنجو من هذا العذابِ المضاعف، فعذابُ النارِ يتضاعف، فاجتنب أسبابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ النارِ المضاعف، والعملُ للنجاة."},"action":{"text":"احذر مصيرَ أهلِ النارِ الذين يشربون على طعامِ الزقّومِ خليطًا من ماءٍ حارٍّ شديدِ الحرارةِ يقطّع أمعاءهم «ثم إن لهم عليها لشوبا من حميم»؛ فعذابُ أهلِ النارِ يتضاعف: طعامٌ خبيثٌ من الزقّوم، وشرابٌ حارٌّ من الحميم؛ فاعمل بالإيمانِ والعملِ الصالحِ لتنجو من هذا العذابِ المضاعف؛ فاجتنب أسبابَ النار لتنجو من عذابها المتنوّع؛ فمن آمن وعمل صالحًا نجا من النارِ وعذابها، ومن كفر وعصى ذاق عذابها المضاعف؛ فاستحضر شدّةَ عذابِ أهلِ النار؛ فيحملك ذلك على الحذرِ من أسبابِ النار؛ فاعمل للجنّةِ ونعيمها، واجتنب النارَ وعذابها المضاعف؛ فبادر بالتوبةِ والعملِ الصالح؛ فالنجاةُ من عذابِ النارِ المضاعفِ بالإيمانِ والطاعةِ والتوبة؛ فاعمل لتنجو من هذا العذابِ الأليم؛ فنعيمُ الجنّةِ الصافي خيرٌ من عذابِ النارِ المضاعف."}},{"n":68,"reflection":{"text":"«ثم إن مرجعهم لإلى الجحيم» — ثم إنّ مرجعَ أهلِ النارِ ومستقرَّهم إلى الجحيم؛ ففي هذا تقريرُ خلودِ أهلِ النارِ فيها؛ فاحذر أن يكون مرجعك إلى الجحيم، فاعمل لتنجو منها ويكون مرجعك إلى الجنّة، فمرجعُ الكافرين النار، فاجتنب أسبابها لتنجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يكون المرجعُ إلى الجحيم، والعملُ للنجاة."},"action":{"text":"احذر أن يكون مرجعك ومستقرّك إلى الجحيمِ كأهلِ النار «ثم إن مرجعهم لإلى الجحيم»؛ فاعمل بالإيمانِ والعملِ الصالحِ لتنجو من النارِ ويكون مرجعك إلى الجنّة؛ فمرجعُ الكافرين والعصاةِ إلى الجحيم، ومرجعُ المؤمنين المتّقين إلى الجنّة؛ فاجتنب أسبابَ النار: من الكفرِ والشركِ والمعاصي؛ والزم أسبابَ الجنّة: من التوحيدِ والطاعةِ والتوبة؛ فمن آمن وعمل صالحًا كان مرجعه إلى الجنّة، ومن كفر وعصى كان مرجعه إلى النار؛ فراجع نفسك: إلى أين مرجعك؟ فاعمل لتكون من أهلِ الجنّةِ لا من أهلِ النار؛ فبادر بالتوبةِ والعملِ الصالحِ قبل فواتِ الأوان؛ فالمرجعُ إلى الله، والجزاءُ بالعمل؛ فاجعل عملك يوصلك إلى الجنّةِ لا إلى النار؛ فمن عمل للجنّةِ كان مرجعه إليها، ومن عمل بأسبابِ النارِ كان مرجعه إليها؛ فاختر لنفسك خيرَ المرجعين."}},{"n":69,"reflection":{"text":"«إنهم ألفوا آباءهم ضالين» — إنّ أهلَ النارِ وجدوا آباءهم ضالّين فاتّبعوهم في الضلال؛ ففي هذا أنّ التقليدَ الأعمى للآباءِ سببُ الهلاك؛ فاحذر التقليدَ الأعمى للآباءِ في الضلال، فلا تتّبع أحدًا في باطلٍ لأنك وجدت عليه آباءك، بل اتّبع الحقَّ بدليله، فالتقليدُ في الباطلِ هلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التقليدِ الأعمى للآباءِ في الضلال."},"action":{"text":"احذر التقليدَ الأعمى للآباءِ والأسلافِ في الضلالِ والباطل، فإنّ أهلَ النارِ إنما هلكوا لأنهم وجدوا آباءهم ضالّين فاتّبعوهم في ضلالهم بلا دليل «إنهم ألفوا آباءهم ضالين»؛ فلا تتّبع أحدًا في باطلٍ أو ضلالٍ لمجرّدِ أنك وجدت عليه آباءك أو مجتمعك؛ فالحقُّ يُتّبَع بالدليلِ لا بموروثِ العادة؛ فزِن ما ورثته من معتقداتٍ وعاداتٍ بميزانِ الوحي؛ فما وافق الحقَّ اتّبعته، وما خالفه رددته ولو كان عليه آباؤك؛ فحرّر عقلك من أسرِ التقليدِ الأعمى؛ فمن قلّد آباءه في الباطلِ هلك معهم، ومن اتّبع الحقَّ بدليله نجا؛ فاجعل اتّباعك للحقِّ لا للأشخاصِ والعادات؛ فالتقليدُ في الباطلِ من أعظمِ أسبابِ الضلالِ والهلاك؛ فاتّبع الحقَّ حيث كان، ولو خالف ما عليه الآباءُ والأكثرون."}},{"n":70,"reflection":{"text":"«فهم على آثارهم يهرعون» — فهم على آثارِ آبائهم الضالّين يسرعون في اتّباعهم بلا تبصّر؛ ففي هذا شدّةُ اندفاعهم في التقليدِ الأعمى؛ فاحذر الاندفاعَ في اتّباعِ الباطلِ تقليدًا، فلا تسرع في اتّباعِ ما عليه الناسُ بلا تبصّر، بل تبصّر واتّبع الحقّ، فالاندفاعُ في التقليدِ الأعمى هلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاندفاعِ في التقليدِ الأعمى، ولزومُ التبصّر."},"action":{"text":"احذر الاندفاعَ والإسراعَ في اتّباعِ الباطلِ تقليدًا للآباءِ أو المجتمعِ بلا تبصّرٍ ولا دليل، كما اندفع أهلُ النارِ في اتّباعِ آبائهم الضالّين مسرعين بلا رويّة «فهم على آثارهم يهرعون»؛ فلا تسرع في اتّباعِ ما عليه الناسُ أو الأكثرون بلا تبصّرٍ وتمحيص؛ بل تبصّر وتأمّل، واتّبع الحقَّ بدليله؛ فالاندفاعُ في التقليدِ الأعمى من غيرِ تفكّرٍ سببُ الضلالِ والهلاك؛ فاستعمل عقلك في وزنِ الأمورِ قبل اتّباعها؛ ولا تنقد وراء الجموعِ بلا بصيرة؛ فكم من مندفعٍ في اتّباعِ الباطلِ تقليدًا هلك؛ فتأنَّ وتبصّر، واتّبع الحقَّ حيث دلّ الدليل؛ فمن اتّبع الحقَّ بتبصّرٍ نجا، ومن اندفع في التقليدِ الأعمى ضلّ؛ فلا تجعل كثرةَ السالكين لطريقٍ دليلًا على صحّته؛ بل زِنه بميزانِ الوحي والعقلِ الرشيد."}},{"n":71,"reflection":{"text":"«ولقد ضل قبلهم أكثر الأولين» — ولقد ضلَّ قبل هؤلاء المشركين أكثرُ الأممِ الأولين؛ ففي هذا أنّ الكثرةَ ليست دليلَ الحقّ؛ فلا يغرّنك كثرةُ الضالّين، فالحقُّ لا يُعرَف بالكثرة، فقد ضلّ أكثرُ الأوّلين، فكن مع الحقِّ ولو قلَّ أهله، ولا تغترَّ بكثرةِ المخالفين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بكثرةِ الضالّين، فالحقُّ لا يُعرَف بالكثرة."},"action":{"text":"لا يغرّنك كثرةُ الضالّين والمخالفين للحقّ، فإنّ الكثرةَ ليست دليلَ الحقّ، فقد ضلّ قبل هؤلاء المشركين أكثرُ الأممِ الأولين «ولقد ضل قبلهم أكثر الأولين»؛ فالحقُّ لا يُعرَف بكثرةِ أتباعه، ولا الباطلُ بقلّةِ مخالفيه؛ فكن مع الحقِّ ولو قلَّ أهله، ولا تغترَّ بكثرةِ أهلِ الباطل؛ فأكثرُ الناسِ لا يؤمنون، وأكثرهم للحقِّ كارهون؛ فلا تجعل كثرةَ السالكين لطريقٍ دليلًا على صحّته؛ بل زِن الأمورَ بميزانِ الوحيِ والدليل؛ فمن اتّبع الحقَّ مع قلّةِ أهله نجا، ومن اتّبع الباطلَ مع كثرةِ أهله هلك؛ فكن من القلّةِ المؤمنةِ المتّبعةِ للحقّ، ولو خالفك الأكثرون؛ فالعبرةُ بالحقِّ لا بالكثرة؛ فاثبت على الحقّ، ولا يوحشك قلّةُ السالكين؛ فالغرباءُ الذين يتمسّكون بالحقِّ عند فسادِ الناسِ لهم البشرى."}},{"n":72,"reflection":{"text":"«ولقد أرسلنا فيهم منذرين» — ولقد أرسلنا في الأممِ الأولين منذِرين يحذّرونهم؛ ففي هذا عدلُ الله في إرسالِ النذر؛ فاعلم أنّ الله لم يترك الأممَ بلا نذير عدلًا منه، فاحمد الله أن بلغتك النذارة، واتّبع النذير، فلا حجّةَ لمن أُنذِر فأعرض.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحمدُ لله على النذارة، واتّباعُ النذير."},"action":{"text":"اعلم أنّ الله بعدله لم يترك الأممَ الأولين بلا نذيرٍ يحذّرهم ويقيم عليهم الحجّة «ولقد أرسلنا فيهم منذرين»؛ فاحمد الله أن بلغتك النذارةُ على يدِ خاتمِ الأنبياءِ محمدٍ ﷺ؛ واتّبع هذا النذير، واعمل بما جاء به؛ فلا حجّةَ لمن أُنذِر فأعرض؛ فقد أقام الله الحجّةَ بإرسالِ المنذرين؛ فبادر بالاستجابةِ للنذارة، ولا تعتذر بعد قيامِ الحجّة؛ فمن اتّبع النذيرَ نجا، ومن أعرض عنه هلك؛ فاجعل نعمةَ بلوغِ النذارةِ إليك سببًا للشكرِ والاتّباع، لا للإعراضِ والتكذيب؛ فالأممُ التي أُرسِل فيها المنذرون فأعرضت هلكت؛ فاحذر أن تكون منهم؛ بل استجب للنذارة، واعمل بمقتضاها؛ فالنذارةُ رحمةٌ بك لتنجو؛ فقابلها بالإقبالِ والاتّباعِ والعمل."}},{"n":73,"reflection":{"text":"«فانظر كيف كان عاقبة المنذرين» — فانظر كيف كانت عاقبةُ الذين أُنذِروا فأعرضوا (الهلاك)؛ ففي هذا الاعتبارُ بعاقبةِ المعرضين عن النذارة؛ فاعتبر بعاقبةِ من أُنذِروا فأعرضوا، فمصيرهم الهلاك، فلا تكن منهم، بل اتّعظ بالنذارةِ واتّبع الحق، فالمعرضُ عن النذارةِ هالك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ المعرضين عن النذارة، والاتّعاظُ بها."},"action":{"text":"اعتبر بعاقبةِ الأممِ التي أُنذِرت فأعرضت عن النذارةِ وكذّبت المنذرين، كيف كانت عاقبتهم الهلاكَ والدمار «فانظر كيف كان عاقبة المنذرين»؛ فمصيرُ المعرضين عن النذارةِ الهلاك؛ فلا تكن منهم؛ بل اتّعظ بالنذارةِ واتّبع الحقّ؛ فاجعل من مصارعِ الأممِ الهالكةِ عبرةً تزيدك اتّعاظًا بالنذارةِ وحذرًا من الإعراض؛ فمن اتّعظ بالنذيرِ نجا، ومن أعرض عنه هلك؛ فبادر بالاستجابةِ للنذارةِ والعملِ بمقتضاها؛ فالإعراضُ عن النذارةِ بعد بلوغها سببُ الهلاك؛ فاجعل النذارةَ موعظةً لك لتنجو؛ فتأمّل عاقبةَ من أعرض عن نُذُرِ الله؛ فيحملك ذلك على الاتّعاظِ والاتّباع؛ فالعاقبةُ للمتّعظين المتّبعين، والدمارُ للمعرضين المكذّبين؛ فكن من المتّعظين بالنذارةِ الناجين."}},{"n":74,"reflection":{"text":"«إلا عباد الله المخلصين» — لكن عبادَ الله المخلصين الذين أخلصوا العبادةَ له نجوا من الهلاك؛ ففي هذا استثناءُ المخلصين من الهلاك؛ فأخلص عبادتك لله لتكون من الناجين، فالإخلاصُ سببُ النجاةِ من الهلاك، فاجعل عملك خالصًا لوجهِ الله، فالمخلصون هم الناجون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله للنجاةِ من الهلاك."},"action":{"text":"أخلص عبادتك وعملك لله وحده لتكون من عبادِ الله المخلصين الذين نجوا من الهلاكِ الذي حلَّ بالمعرضين «إلا عباد الله المخلصين»؛ فالإخلاصُ سببُ النجاةِ من الهلاكِ والعذاب؛ فاجعل عملك كلَّه خالصًا لوجهِ الله، لا رياءً ولا سمعة؛ فالمخلصون هم الناجون المكرمون؛ فراقب نيّتك في أعمالك: هل هي خالصةٌ لله؟ فطهّرها من شوائبِ الرياءِ والسمعةِ وطلبِ الدنيا؛ فمن أخلص لله نجا، ومن راءى خسر؛ فالإخلاصُ روحُ العملِ وسببُ قبوله؛ فاجعل الإخلاصَ همّك في كلِّ عمل؛ فالله لا يقبل من العملِ إلا ما كان خالصًا له؛ فأخلص لله في عبادتك ودعائك وسائرِ عملك؛ فبالإخلاصِ تنجو من الهلاكِ وتفوز بالنعيم؛ فالمخلصون هم الناجون في الدنيا والآخرة."}}]},{"title":"نوحٌ: إجابةُ دعائه ونجاتُه وبقاءُ ذريّتِه والثناءُ عليه، وإغراقُ المكذّبين","range":[75,82],"theme":"دعوةُ نوحٍ وإجابةُ الله له، ونجاتُه وأهله من الكربِ العظيم، وجعلُ ذريّتِه هم الباقين، والثناءُ الباقي عليه في العالمين، وأنّ ذلك جزاءُ المحسنين المؤمنين، وإغراقُ المكذّبين الآخرين","verses":[{"n":75,"reflection":{"text":"«ولقد نادانا نوح فلنعم المجيبون» — ولقد دعانا نوحٌ على قومه لمّا كذّبوه، فنعم المجيبون نحن لدعائه؛ ففي هذا فضلُ دعاءِ الله وسرعةُ إجابته لعباده؛ فادعُ الله واثقًا بالإجابة، فهو نِعم المجيبُ لمن دعاه، فألحّ في الدعاءِ عند الشدائد كما دعا نوحٌ فأُجيب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بإجابةِ الله للدعاء، والإلحاحُ فيه عند الشدائد."},"action":{"text":"ادعُ الله واثقًا بإجابته، فقد نادى نوحٌ ربَّه بعد طولِ الدعوةِ والتكذيب فأجابه أحسنَ إجابة «ولقد نادانا نوح فلنعم المجيبون»؛ فالله نِعم المجيبُ لمن دعاه، لا يردّ سائلًا ولا يخيّب داعيًا؛ فألحّ في الدعاءِ عند الشدائدِ والكرب، ولا تيأس من روحِ الله؛ فمن دعا الله بصدقٍ أجابه؛ فاجعل الدعاءَ ملجأك في كلِّ حال؛ فباب الله مفتوحٌ لا يُغلَق، وعطاؤه لا ينفد؛ فاطرق بابه بالدعاءِ والافتقار؛ فمن لزم الدعاءَ نال المطلوب؛ فنوحٌ دعا فأُجيب ونُجّي، فكن أنت من الداعين الواثقين بإجابةِ الله."}},{"n":76,"reflection":{"text":"«ونجيناه وأهله من الكرب العظيم» — ونجّينا نوحًا وأهله المؤمنين من الكربِ العظيمِ (الغرقِ والتكذيب)؛ ففي هذا أنّ الله ينجّي أولياءه من الشدائد؛ فاعلم أنّ الله ينجّي عباده المؤمنين من الكرب، فالجأ إليه في كربك، فمن التجأ إلى الله نجّاه من كلِّ كرب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في تنجيةِ الله من الكرب، والالتجاءُ إليه فيه."},"action":{"text":"اعلم أنّ الله ينجّي عباده المؤمنين من الكربِ العظيم، كما نجّى نوحًا وأهله من الغرقِ والتكذيبِ الطويل «ونجيناه وأهله من الكرب العظيم»؛ فالجأ إلى الله في كربك وضيقك، فهو المنجّي من كلِّ شدّة؛ فمن التجأ إلى الله نجّاه؛ فلا تيأس عند اشتدادِ الكرب، فإنّ فرجَ الله قريب؛ فاجعل الله ملجأك ومنجاك؛ فكم من كربٍ عظيمٍ فرّجه الله عن أوليائه؛ فأحسن الظنَّ بالله، وارجُ تنجيته؛ فمن صدق اللجوءَ إلى الله كفاه ونجّاه؛ فالتنجيةُ من الكربِ ثمرةُ الإيمانِ والصبرِ والدعاء؛ فاصبر وادعُ وارجُ، فإنّ الله منجّي المؤمنين."}},{"n":77,"reflection":{"text":"«وجعلنا ذريته هم الباقين» — وجعلنا ذريةَ نوحٍ هم الباقين في الأرضِ بعد الغرق (فالناسُ كلُّهم من نسله)؛ ففي هذا كرامةٌ لنوحٍ ببقاءِ نسله؛ فاعلم أنّ عاقبةَ الصبرِ والإيمانِ خيرٌ وبقاء، فمن أخلص لله أبقى الله أثره، فاسعَ لعملٍ صالحٍ يبقى أثره بعدك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العملِ الباقي أثره، فعاقبةُ الإيمانِ البقاء."},"action":{"text":"اعلم أنّ الله جعل ذريةَ نوحٍ هم الباقين في الأرضِ بعد إغراقِ المكذّبين، فالناسُ كلُّهم من نسله، كرامةً له على صبرِه وإيمانه «وجعلنا ذريته هم الباقين»؛ فعاقبةُ الصبرِ والإيمانِ خيرٌ وبقاء؛ فمن أخلص لله أبقى الله ذكره الحسنَ وأثره الصالح؛ فاسعَ لعملٍ صالحٍ يبقى أثره بعدك: علمٍ ينتفع به، أو ذريةٍ صالحةٍ تدعو لك، أو صدقةٍ جارية؛ فالباقياتُ الصالحاتُ خيرٌ عند ربك؛ فاجعل همّك ما يبقى لا ما يفنى؛ فمن أخلص لله رفعه وأبقى أثره؛ فالدنيا فانيةٌ والعملُ الصالحُ باقٍ؛ فاعمر حياتك بما يبقى نفعه وأثره بعد موتك."}},{"n":78,"reflection":{"text":"«وتركنا عليه في الآخرين» — وأبقينا لنوحٍ ثناءً حسنًا وذكرًا جميلًا في الأممِ الآخرين إلى يومِ القيامة؛ ففي هذا جزاءُ المحسنِ بالثناءِ الباقي؛ فاعلم أنّ الله يجزي المحسنَ بالذكرِ الحسنِ الباقي، فأحسن عملك يبقَ لك الثناءُ الجميل، فالذكرُ الحسنُ عمرٌ ثانٍ للمحسن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الثناءِ الحسنِ الباقي بإحسانِ العمل."},"action":{"text":"اعلم أنّ الله أبقى لنوحٍ ثناءً حسنًا وذكرًا جميلًا في الأممِ الآخرين، يُذكَر به بالخيرِ إلى يومِ القيامة، جزاءً على إحسانه «وتركنا عليه في الآخرين»؛ فالله يجزي المحسنين بالذكرِ الحسنِ الباقي في الدنيا مع الأجرِ في الآخرة؛ فأحسن عملك وأخلص لله، يبقَ لك الثناءُ الجميلُ والذكرُ الحسن؛ فالذكرُ الحسنُ عمرٌ ثانٍ للمحسن، ودعوةٌ صالحةٌ تتبعه؛ فاسعَ لأن تُذكَر بالخيرِ بعد موتك بإحسانك وصلاحك؛ فمن أحسن في حياته بقي ذكره الحسن؛ فاجعل سيرتك عطرةً بالإحسانِ والصلاح؛ فالثناءُ الحسنُ من عاجلِ بشرى المؤمن؛ فأحسن تُذكَر بالخير، ويبقَ لك الأثرُ الجميل."}},{"n":79,"reflection":{"text":"«سلام على نوح في العالمين» — سلامٌ وأمانٌ وثناءٌ على نوحٍ من الله في جميعِ العالمين؛ ففي هذا شرفُ السلامِ الإلهي على أوليائه؛ فاعلم أنّ أعظمَ الكرامةِ سلامُ الله على العبد، فاطلب رضا الله بالإحسانِ لتنال سلامه، فسلامُ الله أعظمُ ما يُطلَب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ سلامِ الله ورضاه بالإحسان، وهو أعظمُ الكرامة."},"action":{"text":"اعلم أنّ الله سلّم على نوحٍ وأثنى عليه في جميعِ العالمين، فلا يُذكَر إلا بخيرٍ وثناء «سلام على نوح في العالمين»؛ فأعظمُ الكرامةِ أن يُسلّم الله على العبدِ ويثني عليه؛ فاطلب رضا الله وسلامه بالإحسانِ والإخلاص؛ فسلامُ الله على العبدِ أمانٌ له من كلِّ آفةٍ ونقص، وثناءٌ عليه في الملأ الأعلى وفي الأرض؛ فاجعل غايتك أن تنال رضا الله وسلامه؛ فمن أحسن وأخلص نال السلامَ والثناء؛ فسلامُ الله أعظمُ ما يُطلَب، وأجلُّ ما يُنال؛ فاعمل عملَ من يرجو سلامَ ربه وثناءه؛ فالسلامُ من الله غايةُ الشرفِ والكرامة؛ فاطلبه بالإحسانِ في عبادةِ الله ومعاملةِ خلقه."}},{"n":80,"reflection":{"text":"«إنا كذلك نجزي المحسنين» — إنا كما جزينا نوحًا بهذا الثناءِ والتنجيةِ نجزي كلَّ محسنٍ في عمله؛ ففي هذا تقريرُ سنّةِ جزاءِ المحسنين؛ فأحسن في عملك لتكون من المحسنين الذين وعدهم الله بالجزاءِ الحسن، فالإحسانُ سبيلُ الجزاءِ الجميل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ في العملِ رجاءَ جزاءِ الله للمحسنين."},"action":{"text":"أحسن في عملك وعبادتك ومعاملتك لتكون من المحسنين الذين وعدهم الله بالجزاءِ الحسن، كما جزى نوحًا بالتنجيةِ والثناءِ الباقي «إنا كذلك نجزي المحسنين»؛ فهذه سنّةُ الله في جزاءِ المحسنين، لا تتخلّف؛ فالإحسانُ أن تعبد الله كأنك تراه، وأن تُتقن عملك، وتُحسن إلى خلقه؛ فمن أحسن جزاه الله أحسنَ الجزاء؛ فاجعل الإحسانَ دأبك في كلِّ ما تأتي وتذر؛ فالله يحبّ المحسنين ويجزيهم بالحسنى؛ فراقب إحسانك في عبادتك وأخلاقك ومعاملاتك؛ فكلّما أحسنت زاد جزاؤك؛ فالجزاءُ من جنسِ العمل؛ فمن أحسن أُحسِن إليه؛ فاطلب معيّةَ الله وجزاءه بالإحسان؛ فالإحسانُ أعلى مراتبِ الدين، وأهله هم المقرّبون."}},{"n":81,"reflection":{"text":"«إنه من عبادنا المؤمنين» — إنّ نوحًا من عبادنا المؤمنين الذين صدق إيمانهم؛ ففي هذا أنّ الإيمانَ الصادقَ أصلُ الإحسانِ والنجاة؛ فحقّق الإيمانَ الصادقَ في قلبك، فهو أصلُ كلِّ خير، فمن صدق إيمانه استحقّ كرامةَ الله ونجاته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ الإيمانِ الصادق، فهو أصلُ الإحسانِ والنجاة."},"action":{"text":"اعلم أنّ الله وصف نوحًا بأنه من عبادِه المؤمنين الصادقين في إيمانهم، فكان ذلك أصلَ إحسانه ونجاته وكرامته «إنه من عبادنا المؤمنين»؛ فالإيمانُ الصادقُ أصلُ كلِّ خير، وبه يُنال رضا الله ونجاته؛ فحقّق الإيمانَ في قلبك تصديقًا وإذعانًا، وفي لسانك إقرارًا، وفي جوارحك عملًا؛ فمن صدق إيمانه استحقّ كرامةَ الله؛ فاعتنِ بإيمانك: قوِّه بالطاعةِ والذكرِ والتفكّر، وصُنه عن المعاصي التي تُنقصه؛ فالإيمانُ يزيد بالطاعةِ وينقص بالمعصية؛ فتعاهد إيمانك بالتقويةِ والتجديد؛ فمن قوي إيمانه حسُن عمله ونجا؛ فاجعل تحقيقَ الإيمانِ الصادقِ همّك الأول؛ فهو رأسُ الأمرِ وأساسُ النجاةِ والفلاح."}},{"n":82,"reflection":{"text":"«ثم أغرقنا الآخرين» — ثم أغرقنا القومَ الآخرين المكذّبين لنوح؛ ففي هذا عاقبةُ المكذّبين، ومقابلةُ نجاةِ المؤمنين بهلاكِ الكافرين؛ فاعتبر بعاقبةِ المكذّبين، واحذر أن تكون منهم، فمصيرُ من كذّب رسلَ الله الهلاك، فاتّبع الحقَّ لتنجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بهلاكِ المكذّبين، والحذرُ من مصيرهم."},"action":{"text":"اعتبر بعاقبةِ قومِ نوحٍ المكذّبين الذين أغرقهم الله جميعًا بعد طولِ دعوته لهم «ثم أغرقنا الآخرين»؛ فتأمّل كيف قابل الله نجاةَ المؤمنين بهلاكِ الكافرين، جزاءً وفاقًا؛ فمصيرُ من كذّب رسلَ الله وأصرّ على الكفرِ الهلاك؛ فاحذر أن تكون من المكذّبين المعرضين؛ بل اتّبع الحقَّ الذي جاءت به الرسل لتنجو؛ فالتكذيبُ سببُ الهلاك، والإيمانُ سببُ النجاة؛ فاجعل من هلاكِ المكذّبين عبرةً تحملك على الإيمانِ والاتّباع؛ فمن كذّب هلك، ومن آمن نجا؛ فاختر لنفسك سبيلَ الناجين؛ فالله لا يظلم الناس شيئًا، ولكنّهم أنفسهم يظلمون؛ فبادر بالإيمانِ والطاعةِ قبل نزولِ العذاب؛ فما نجا الناجون إلا بالإيمانِ والاتّباع، وما هلك الهالكون إلا بالكفرِ والتكذيب."}}]},{"title":"إبراهيم: القلبُ السليمُ ومحاجّةُ قومِه وكسرُ الأصنامِ ونجاتُه من النار","range":[83,98],"theme":"أنّ إبراهيمَ من شيعةِ نوحٍ على التوحيد، ومجيئُه ربَّه بقلبٍ سليم، وإنكارُه على أبيه وقومه عبادةَ الأصنام، وتوريتُه ليتخلّف، وكسرُه الأصنامَ بيمينه، ومحاجّتُه لهم بأنهم يعبدون ما ينحتون والله خلقهم وما يعملون، وكيدُهم بإلقائه في النارِ وردُّ كيدهم وجعلُهم الأسفلين","verses":[{"n":83,"reflection":{"text":"«وإن من شيعته لإبراهيم» — وإنّ من أتباعِ نوحٍ على دينِ التوحيدِ لإبراهيمَ عليه السلام؛ ففي هذا شرفُ اتّباعِ أهلِ الحقِّ السابقين؛ فاتّبع سبيلَ الموحّدين السابقين من الأنبياءِ وأتباعهم، فالحقُّ واحدٌ ومنهجُ الأنبياءِ واحد، فاجعل نفسك في شيعةِ أهلِ التوحيد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ سبيلِ الموحّدين السابقين من الأنبياء."},"action":{"text":"اعلم أنّ إبراهيمَ عليه السلام كان من أتباعِ نوحٍ على أصلِ دينِ التوحيدِ والدعوةِ إليه، فمنهجُ الأنبياءِ واحد «وإن من شيعته لإبراهيم»؛ فاتّبع سبيلَ الموحّدين السابقين من الأنبياءِ وأتباعهم الصالحين؛ فالحقُّ واحدٌ لا يتعدّد، ومنهجُ الرسلِ في التوحيدِ واحد؛ فاجعل نفسك في شيعةِ أهلِ التوحيدِ والإيمان، تسير على دربهم؛ فمن اتّبع سبيلَ المؤمنين نجا وسعد؛ فاقتدِ بالأنبياءِ وأتباعهم في توحيدِ الله وإخلاصِ الدينِ له؛ فهم القدوةُ والأسوة؛ فالزم سبيلهم، ولا تحد عنه؛ فسبيلُ الموحّدين هو الصراطُ المستقيم؛ فاسلكه، وكن من أهله؛ فالانتسابُ إلى أهلِ التوحيدِ والإيمانِ شرفٌ ونجاة."}},{"n":84,"reflection":{"text":"«إذ جاء ربه بقلب سليم» — حين جاء إبراهيمُ ربَّه بقلبٍ سليمٍ من الشركِ والشكِّ والغلِّ والأخلاقِ الرديئة؛ ففي هذا أنّ سلامةَ القلبِ أصلُ النجاة؛ فاعمل على سلامةِ قلبك من الشركِ والغلِّ والحسدِ والنفاق، فالنجاةُ يومَ القيامةِ لمن أتى الله بقلبٍ سليم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"السعيُ لسلامةِ القلبِ من الشركِ والأدرانِ الباطنة."},"action":{"text":"اسعَ لسلامةِ قلبك، فقد أثنى الله على إبراهيمَ أنه جاء ربَّه بقلبٍ سليمٍ من الشركِ والشكِّ والغلِّ والحقدِ والأخلاقِ الذميمة «إذ جاء ربه بقلب سليم»؛ فسلامةُ القلبِ أصلُ النجاة، وبها الفوزُ يومَ لا ينفع مالٌ ولا بنون إلا من أتى الله بقلبٍ سليم؛ فطهّر قلبك من الشركِ بتحقيقِ التوحيد، ومن الشكِّ باليقين، ومن الغلِّ والحسدِ والحقدِ بالسلامةِ لعبادِ الله؛ فالقلبُ السليمُ هو الخالصُ من كلِّ دنسٍ ومرض؛ فتعاهد قلبك بالتطهيرِ والتزكية؛ فصلاحُ الجسدِ كلِّه بصلاحِ القلب؛ فاجعل همّك سلامةَ قلبك؛ فمن سلم قلبه نجا، ومن فسد قلبه هلك؛ فالقلوبُ هي محلُّ نظرِ الرب؛ فاعمرها بالتوحيدِ والإيمانِ والمحبّةِ والسلامة."}},{"n":85,"reflection":{"text":"«إذ قال لأبيه وقومه ماذا تعبدون» — حين قال إبراهيمُ لأبيه وقومه منكرًا: ما هذا الذي تعبدونه؟ ففي هذا إنكارُ الشركِ ومناصحةُ الأقربين؛ فأنكِر الباطلَ وابدأ بمناصحةِ أقربِ الناسِ إليك، فإبراهيمُ بدأ بأبيه وقومه، فادعُ أهلك وقرابتك إلى التوحيدِ برفق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إنكارُ الشركِ والبدءُ بدعوةِ الأقربين إلى التوحيد."},"action":{"text":"أنكِر الباطلَ والشركَ كما أنكره إبراهيمُ على أبيه وقومه حين سألهم موبّخًا: ما هذا الذي تعبدونه من دونِ الله؟ «إذ قال لأبيه وقومه ماذا تعبدون»؛ فابدأ بمناصحةِ أقربِ الناسِ إليك ودعوتهم إلى التوحيد، فإبراهيمُ بدأ بأبيه وقومه؛ فادعُ أهلك وقرابتك إلى عبادةِ الله وحده برفقٍ وحكمةٍ ومحبّة؛ فأولى الناسِ بدعوتك ونصحك أقربهم إليك؛ فأنذر عشيرتك الأقربين؛ فمن أصلح أهله فقد أدّى حقًّا عظيمًا؛ فلا تغفل عن دعوةِ أهلك وأنت تدعو الناس؛ فالبدايةُ بالأقربين سنّةُ الأنبياء؛ فاجمع بين إنكارِ المنكرِ ودعوةِ المخالفِ بالحكمةِ والموعظةِ الحسنة؛ فالغايةُ هدايتهم لا مجرّدُ توبيخهم؛ فادعُ أهلك بالحبِّ والحكمةِ إلى التوحيد."}},{"n":86,"reflection":{"text":"«أئفكا آلهة دون الله تريدون» — أكذبًا وباطلًا تريدون آلهةً تعبدونها من دونِ الله؟ ففي هذا بيانُ أنّ عبادةَ غيرِ الله إفكٌ وكذب؛ فاعلم أنّ كلَّ معبودٍ سوى الله باطلٌ وإفك، فاطرح كلَّ ما يُعبَد من دونِ الله، ووحّد المعبودَ الحق، فالشركُ أعظمُ الإفك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ عبادةَ غيرِ الله إفكٌ وباطل، ونبذُها."},"action":{"text":"اعلم أنّ عبادةَ غيرِ الله إفكٌ وكذبٌ وباطل، كما وبّخ إبراهيمُ قومه: أكذبًا وزورًا تريدون آلهةً تعبدونها من دونِ الله الخالقِ الرازق؟ «أئفكا آلهة دون الله تريدون»؛ فكلُّ معبودٍ سوى الله باطل، وعبادتُه أعظمُ الإفكِ والكذب؛ فاطرح كلَّ ما يُعبَد من دونِ الله من صنمٍ أو قبرٍ أو وليٍّ أو هوى؛ ووحّد المعبودَ الحقَّ الذي بيده كلُّ شيء؛ فالشركُ أعظمُ الظلمِ وأكبرُ الإفك؛ فلا تصرف شيئًا من العبادةِ لغيرِ الله؛ فمن عبد غيرَ الله فقد اتّخذ إلهًا باطلًا لا يملك له نفعًا ولا ضرًّا؛ فأخلص عبادتك لله وحده؛ فالمعبودُ بحقٍّ هو الله الخالقُ المدبّر؛ فانبذ كلَّ إفكٍ وباطل، والزم توحيدَ الحق."}},{"n":87,"reflection":{"text":"«فما ظنكم برب العالمين» — فما ظنّكم بربِّ العالمين إن عبدتم غيره؟ أيتركُكم أم يعاقبكم؟ ففي هذا التخويفُ بلقاءِ الله وسؤالِ النفسِ عن الظنِّ به؛ فحاسب نفسك: ما ظنّك بربّك إن لقيته مشركًا؟ فأحسن الظنَّ بالله بأن توحّده وتطيعه، لا بأن تعصيه وترجو نجاته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفسِ عن الظنِّ بالله، وتحقيقُ حسنِ الظنّ بالطاعة."},"action":{"text":"حاسب نفسك واسألها: ما ظنّك بربِّ العالمين إن لقيته وقد عبدت غيره؟ كما نبّه إبراهيمُ قومه محذّرًا «فما ظنكم برب العالمين»؛ فربُّ العالمين لا يترك من أشرك به وعبد سواه بلا عقاب؛ فأحسن الظنَّ بالله بأن توحّده وتطيعه وتخلص له، لا بأن تعصيه وترجو مع ذلك نجاته؛ فحسنُ الظنِّ الحقُّ يقارنه حسنُ العمل؛ فمن أحسن الظنَّ بالله وأحسن العملَ رجا رحمته؛ فأمّا من أساء العملَ وأشرك ثم زعم حسنَ الظنِّ فذلك غرورٌ وتمنٍّ؛ فراقب ظنّك بربك، وأتبعه بالعملِ الصالح؛ فالله عند ظنِّ عبدِه به؛ فاجعل ظنّك به حسنًا مقرونًا بالطاعةِ والتوحيد؛ فمن خاف مقامَ ربه وأحسن الظنَّ به مع العملِ نجا وفاز."}},{"n":88,"reflection":{"text":"«فنظر نظرة في النجوم» — فنظر إبراهيمُ نظرةً في النجومِ (تعريضًا ليتخلّف عن الخروجِ معهم إلى عيدهم)؛ ففي هذا جوازُ المعاريضِ والحيلةِ لإقامةِ الحقِّ والدعوة؛ فاستعمل الحكمةَ والتدبيرَ في نصرةِ الحقّ، فإبراهيمُ دبّر ليكسر أصنامهم، فادفع الباطلَ بالحكمةِ والتدبيرِ لا بالتهوّرِ وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعمالُ الحكمةِ والتدبيرِ في نصرةِ الحقّ."},"action":{"text":"استعمل الحكمةَ والتدبيرَ في نصرةِ الحقِّ ودفعِ الباطل، كما نظر إبراهيمُ في النجومِ نظرةً ليعتذر عن الخروجِ مع قومه إلى عيدهم، فيتفرّغ لكسرِ أصنامهم «فنظر نظرة في النجوم»؛ فالداعيةُ الحكيمُ يدبّر لإقامةِ الحقِّ بأحسنِ الوسائل؛ فجازت المعاريضُ والتوريةُ لتحقيقِ مقصدٍ شرعيٍّ عظيم؛ فادفع الباطلَ بالحكمةِ والتدبيرِ والتخطيطِ السليم، لا بالتهوّرِ والاندفاعِ وحدهما؛ فالعملُ للحقِّ يحتاج بصيرةً وحكمة؛ فادرس المواقفَ، ودبّر بحكمة، واختر أنسبَ الأوقاتِ والوسائل؛ فمن جمع بين الغيرةِ على الحقِّ والحكمةِ في نصرتِه بلغ مقصده؛ فلا تكن متهوّرًا ولا متخاذلًا، بل حكيمًا مقدامًا؛ فالحكمةُ ضالّةُ المؤمنِ يأخذها حيث وجدها؛ فانصر الحقَّ بحكمةٍ وتدبير."}},{"n":89,"reflection":{"text":"«فقال إني سقيم» — فقال إبراهيمُ معرّضًا: إني سقيمٌ (سأسقم، أو مريضُ القلبِ من كفركم)؛ ففي هذا جوازُ التوريةِ لمصلحةِ الدين؛ فاعلم أنّ التوريةَ لدفعِ الباطلِ ونصرةِ الحقِّ جائزة، فادفع أذى الباطلِ بالتوريةِ عند الحاجة، ولا تعرّض نفسك للفتنةِ بلا داعٍ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ جوازِ التوريةِ لمصلحةِ الدينِ ودفعِ الباطل."},"action":{"text":"اعلم أنّ إبراهيمَ ورّى لقومه بقوله «إني سقيم» ليتخلّف عنهم فيكيد لأصنامهم، وكان في ذلك مصلحةٌ عظيمةٌ للدين؛ فالتوريةُ — وهي أن تقول قولًا صحيحًا تريد به معنًى خلافَ ظاهره — جائزةٌ لدفعِ الباطلِ ونصرةِ الحق؛ فادفع أذى الباطلِ بالحكمةِ والتوريةِ عند الحاجةِ والمصلحةِ الراجحة؛ ولا تعرّض نفسك للفتنةِ والأذى بلا داعٍ حين يمكن دفعُه بالحكمة؛ فالمؤمنُ كيّسٌ فطن، يدرأ الشرَّ بأخفِّ الوسائل؛ فاقتدِ بإبراهيمَ في حكمتِه ومدافعتِه للباطلِ بالتدبير؛ فليس كلُّ موطنٍ موطنَ مصارحةٍ ومواجهة؛ بل من الحكمةِ التوريةُ والتدبيرُ لتحقيقِ المقصدِ الأعظم؛ فوازن بين المصالحِ والمفاسد، واختر ما فيه نصرةُ الحقِّ بأقلِّ ضرر؛ فالدينُ يُنصَر بالحكمةِ كما يُنصَر بالقوة."}},{"n":90,"reflection":{"text":"«فتولوا عنه مدبرين» — فأعرض قومه عنه وانصرفوا إلى عيدهم مدبرين؛ ففي هذا خلاءُ الجوِّ للداعيةِ ليعملَ عمله؛ فاعلم أنّ الله قد يهيّئ للحقِّ أسبابَ ظهوره، فاغتنم فرصك في نصرةِ الحقِّ إذا أتيحت، فإبراهيمُ اغتنم انصرافهم فكسر الأصنام.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ الفرصِ المتاحةِ لنصرةِ الحقّ."},"action":{"text":"اعلم أنّ الله لمّا أراد نصرةَ الحقِّ هيّأ لإبراهيمَ خلاءَ الجوِّ بانصرافِ قومه عنه إلى عيدهم، فاغتنم الفرصةَ فكسر أصنامهم «فتولوا عنه مدبرين»؛ فالله يهيّئ لأوليائه أسبابَ نصرةِ الحقِّ وظهوره؛ فاغتنم الفرصَ المتاحةَ لنصرةِ الحقِّ والدعوةِ إليه؛ فكم من فرصةٍ سانحةٍ للخيرِ تمرّ فيفوّتها الغافلون؛ فكن يقظًا مغتنمًا للفرص؛ فإذا سنحت لك فرصةٌ لعملِ خيرٍ أو نصرةِ حقٍّ أو دفعِ باطلٍ فبادر إليها؛ فالفرصُ تمرّ مرَّ السحاب؛ فمن اغتنمها ظفر، ومن فرّط ندم؛ فاجعل من عادتك اغتنامَ أوقاتِ الخيرِ ومواسمِ الطاعةِ وفرصِ الدعوة؛ فالموفّقُ من هيّأه الله لاغتنامِ الخير؛ فاسأل الله التوفيقَ والإعانة، واغتنم كلَّ فرصةٍ لنصرةِ دينه."}},{"n":91,"reflection":{"text":"«فراغ إلى آلهتهم فقال ألا تأكلون» — فذهب في خفيةٍ إلى أصنامهم فقال ساخرًا: ألا تأكلون هذا الطعامَ المقدَّم لكم؟ ففي هذا تبكيتُ الباطلِ وفضحُ عجزِ المعبوداتِ الباطلة؛ فتأمّل عجزَ كلِّ معبودٍ سوى الله عن أبسطِ الأفعال، فكيف تُعبَد آلهةٌ لا تأكل ولا تنفع؟ فوحّد القادرَ وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ عجزِ المعبوداتِ الباطلة، وتوحيدُ القادرِ وحده."},"action":{"text":"تأمّل كيف بكّت إبراهيمُ آلهةَ قومه الباطلةَ حين ذهب إليها خفيةً فقال ساخرًا مبيّنًا عجزها: ألا تأكلون هذا الطعامَ الذي قُدِّم إليكم؟ «فراغ إلى آلهتهم فقال ألا تأكلون»؛ فهذه المعبوداتُ عاجزةٌ عن أبسطِ الأفعال، لا تأكل ولا تنطق ولا تنفع ولا تضرّ؛ فكيف تُعبَد آلهةٌ بهذا العجز؟ فأدرك بطلانَ عبادةِ كلِّ ما سوى الله؛ فالمعبودُ بحقٍّ هو القادرُ على كلِّ شيء، الرازقُ النافعُ الضارّ؛ فوحّد القادرَ وحده، واطرح المعبوداتِ العاجزة؛ فكلُّ ما عُبِد من دونِ الله عاجزٌ فقيرٌ محتاج؛ فلا يستحقّ العبادةَ إلا من له الكمالُ المطلقُ والقدرةُ التامّة؛ فتفكّر في عجزِ ما يُعبَد من دونِ الله، يزدك ذلك يقينًا بتوحيدِ القادرِ الرزّاق؛ فاصرف عبادتك كلَّها لله القادرِ على كلِّ شيء."}},{"n":92,"reflection":{"text":"«ما لكم لا تنطقون» — ما بالكم لا تنطقون ولا تجيبون؟ ففي هذا زيادةُ التبكيتِ لعجزِ الأصنامِ عن الكلام؛ فاعلم أنّ المعبودَ الحقَّ يسمع ويجيب، والأصنامُ لا تنطق، فادعُ الربَّ الذي يسمع دعاءك ويجيبه، ولا تدعُ ما لا يسمع ولا ينطق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"دعاءُ الربِّ السميعِ المجيب، وتركُ ما لا ينطق."},"action":{"text":"تأمّل كيف زاد إبراهيمُ في تبكيتِ آلهةِ قومه وفضحِ عجزها بقوله: ما لكم لا تنطقون ولا تردّون جوابًا؟ «ما لكم لا تنطقون»؛ فهذه الأصنامُ جماداتٌ لا تسمع ولا تنطق ولا تعقل؛ فكيف تُدعى وتُعبَد؟ فاعلم أنّ المعبودَ الحقَّ هو الله السميعُ الذي يسمع دعاءك، المجيبُ الذي يستجيب لك؛ فادعُ الربَّ الذي يسمع ويجيب، ولا تدعُ ما لا يسمع ولا ينطق ولا يملك شيئًا؛ فالدعاءُ عبادةٌ لا تُصرَف إلا لله؛ فمن دعا غيرَ الله فقد دعا من لا يستجيب له إلى يومِ القيامة، وهم عن دعائهم غافلون؛ فأخلص دعاءك لله وحده؛ فهو القريبُ المجيبُ لمن دعاه؛ فلا تصرف دعاءك لقبرٍ أو صنمٍ أو غائبٍ لا يسمع؛ فالله وحده هو السميعُ المجيبُ القريب."}},{"n":93,"reflection":{"text":"«فراغ عليهم ضربا باليمين» — فأقبل عليها ضربًا بيده اليمنى (بقوّة) فكسّرها؛ ففي هذا إزالةُ المنكرِ باليدِ عند القدرة؛ فأزل المنكرَ بيدك إن قدرت بلا مفسدةٍ أكبر، فإبراهيمُ كسر الأصنامَ بيده، فغيّر ما تستطيع تغييرَه من المنكرِ بحكمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تغييرُ المنكرِ باليدِ عند القدرةِ وأمنِ المفسدة."},"action":{"text":"اعلم أنّ إبراهيمَ أقبل على أصنامِ قومه فكسّرها بيده اليمنى بقوّة، إزالةً للمنكرِ الأعظم «فراغ عليهم ضربا باليمين»؛ فمن رأى منكرًا وقدر على تغييرِه بيده بلا مفسدةٍ أكبر فليغيّره؛ فأزل المنكرَ بيدك إن استطعت، فإن لم تستطع فبلسانك، فإن لم تستطع فبقلبك، وذلك أضعفُ الإيمان؛ فغيّر ما تقدر على تغييرِه من المنكراتِ في بيتك ومحيطِ سلطانك بحكمةٍ ومراعاةٍ للمآلات؛ فإبراهيمُ لم يغيّر إلا ما قدر عليه وأمِن معه المفسدةَ الأكبر؛ فالإنكارُ باليدِ لمن له قدرةٌ وولايةٌ عليه؛ فلا تُقدِم على تغييرٍ يجرّ منكرًا أعظم؛ فوازن بين إزالةِ المنكرِ وما قد يترتّب عليها؛ فمن غيّر منكرًا استطاع تغييرَه فقد أدّى واجبَه؛ فقم بواجبِ الإنكارِ بحسبِ قدرتك وموقعك، بحكمةٍ وبصيرة."}},{"n":94,"reflection":{"text":"«فأقبلوا إليه يزفون» — فأقبل قومه إليه مسرعين غاضبين لمّا رأوا أصنامهم محطّمة؛ ففي هذا أنّ نصرةَ الحقِّ تستتبع أذى المبطلين؛ فاعلم أنّ من قام بالحقِّ لقي عداوةَ أهلِ الباطل، فاثبت على الحقِّ وإن آذاك المبطلون، ولا يصدّنّك أذاهم عن الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ رغمَ أذى أهلِ الباطل."},"action":{"text":"اعلم أنّ إبراهيمَ لمّا كسر أصنامَ قومه أقبلوا إليه مسرعين غاضبين يريدون به الأذى «فأقبلوا إليه يزفون»؛ فنصرةُ الحقِّ والقيامُ به يستتبع غالبًا عداوةَ أهلِ الباطلِ وأذاهم؛ فاعلم أنّ من قام بالحقِّ وأنكر الباطلَ لقي عداوةَ المبطلين وأذاهم؛ فاثبت على الحقِّ وإن آذاك أهلُ الباطل، ولا يصدّنّك أذاهم عن الاستمرارِ عليه؛ فما من داعٍ إلى الحقِّ إلا أوذي؛ فالأنبياءُ وأتباعهم أوذوا في سبيلِ الله فصبروا؛ فاقتدِ بهم في الثباتِ والصبرِ على الأذى؛ فالعاقبةُ للحقِّ وأهله؛ فلا تلتفت إلى غضبِ المبطلين وتهديدهم؛ بل امضِ في نصرةِ الحقِّ صابرًا محتسبًا؛ فمن ثبت على الحقِّ رغمَ الأذى نصره الله؛ فالثباتُ عند اشتدادِ الأذى علامةُ صدقِ الإيمان؛ فاصبر واثبت، فإنّ نصرَ الله قريب."}},{"n":95,"reflection":{"text":"«قال أتعبدون ما تنحتون» — قال إبراهيمُ محتجًّا: أتعبدون أصنامًا تنحتونها بأيديكم؟ ففي هذا بطلانُ عبادةِ ما يصنعه الإنسانُ بنفسه؛ فتأمّل سخفَ عبادةِ ما تصنعه يدك، فكيف يكون إلهًا ما نحتَّه أنت؟ فوحّد الخالقَ الذي لم يُصنَع، ولا تعبد صنعةَ يدك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ بطلانِ عبادةِ المصنوعات، وتوحيدُ الخالق."},"action":{"text":"تأمّل حجّةَ إبراهيمَ على قومه حين قال موبّخًا: أتعبدون أصنامًا تنحتونها بأيديكم من الحجارةِ والخشب؟ «قال أتعبدون ما تنحتون»؛ فكيف يكون إلهًا معبودًا ما نحتَّه أنت بيدك وصنعتَه بنفسك؟ فأدرك سخفَ عبادةِ ما يصنعه الإنسانُ ثم يعبده؛ فالمعبودُ بحقٍّ هو الخالقُ الذي لم يُخلَق، الصانعُ الذي لم يُصنَع؛ فوحّد الخالقَ الأولَ الذي خلق كلَّ شيء، ولا تعبد صنعةَ يدك ولا شيئًا مخلوقًا؛ فكلُّ ما سوى الله مخلوقٌ مصنوعٌ فقير؛ فلا يستحقّ العبادةَ إلا الخالقُ القادر؛ فتفكّر: أيُعبَد المصنوعُ ويُترَك الصانع؟ فهذا عينُ الضلال؛ فاعبد الله الخالقَ وحده، وانبذ عبادةَ كلِّ مخلوقٍ ومصنوع؛ فالعقلُ السليمُ يأبى عبادةَ ما تصنعه الأيدي؛ فوحّد ربَّك الخالقَ، وأخلص له العبادة."}},{"n":96,"reflection":{"text":"«والله خلقكم وما تعملون» — والله خلقكم وخلق أعمالكم التي تعملونها (ومنها نحتُ الأصنام)؛ ففي هذا تقريرُ عمومِ خلقِ الله لكلِّ شيء؛ فاعلم أنّ الله خالقُ كلِّ شيءٍ حتى أعمالك، فأخلص العبادةَ للخالقِ الذي خلقك وخلق فعلك، ولا تعبد ما هو مخلوقٌ مثلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بأنّ الله خالقُ كلِّ شيءٍ حتى الأعمال، وإخلاصُ العبادةِ له."},"action":{"text":"اعلم أنّ الله خلقكم وخلق أعمالكم التي تعملونها، فهو خالقُ العبادِ وخالقُ أفعالهم، ومنها نحتهم للأصنام «والله خلقكم وما تعملون»؛ فالله خالقُ كلِّ شيءٍ لا خالقَ سواه؛ فإذا كان هو الخالقَ لك ولفعلك، فكيف تعبد ما هو مخلوقٌ مثلك أو من صنعِ فعلك المخلوق؟ فأخلص العبادةَ للخالقِ الذي خلقك وخلق كلَّ شيء؛ فهذه الآيةُ من أعظمِ الأدلّةِ على عمومِ خلقِ الله، وأنّ أفعالَ العبادِ مخلوقةٌ لله مع كونها كسبًا لهم يُحاسَبون عليه؛ فاعبد الخالقَ وحده، ووحّده في ربوبيتِه وألوهيتِه؛ فمن أقرّ بأنّ الله خالقُ كلِّ شيءٍ لزمه أن يعبده وحده؛ فالخلقُ دليلُ استحقاقِ العبادة؛ فاصرف عبادتك للخالقِ، لا للمخلوق؛ فالله ربُّ كلِّ شيءٍ وخالقه ومليكه."}},{"n":97,"reflection":{"text":"«قالوا ابنوا له بنيانا فألقوه في الجحيم» — قال قومه: ابنوا له بناءً واملؤوه نارًا ثم ألقوه في النارِ العظيمة؛ ففي هذا بلوغُ الباطلِ في عداوةِ الحقِّ منتهاه؛ فاعلم أنّ أهلَ الباطلِ قد يبلغون في أذى أهلِ الحقِّ أقصاه، فاستعن بالله واثبت، فالله ناصرُ أوليائه ولو بلغ كيدُ الأعداءِ ما بلغ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ والاستعانةُ بالله عند بلوغِ كيدِ الأعداءِ منتهاه."},"action":{"text":"اعلم أنّ قومَ إبراهيمَ لمّا عجزوا عن مقارعتِه بالحجّةِ لجؤوا إلى القوّةِ والبطش، فقالوا: ابنوا له بناءً واملؤوه نارًا وألقوه في الجحيمِ الملتهبة «قالوا ابنوا له بنيانا فألقوه في الجحيم»؛ فهكذا يبلغ أهلُ الباطلِ في عداوةِ الحقِّ وأهله منتهاهم حين تُعوزهم الحجّة؛ فإذا بلغ كيدُ الأعداءِ لك أقصاه فاستعن بالله واثبت، ولا تهن؛ فالله ناصرُ أوليائه ولو بلغ كيدُ أعدائهم ما بلغ؛ فإبراهيمُ أُلقي في النارِ فجعلها الله عليه بردًا وسلامًا؛ فمن توكّل على الله كفاه؛ فلا تخف بطشَ المبطلين ما دمت على الحق؛ فالله أقوى وأعظم؛ فالجأ إليه، وفوّض أمرك إليه، واثبت على الحقّ؛ فكم من كيدٍ عظيمٍ ردّه الله في نحرِ أصحابه؛ فحسبك الله ونعم الوكيل؛ فمن كان الله معه فلا غالبَ له."}},{"n":98,"reflection":{"text":"«فأرادوا به كيدا فجعلناهم الأسفلين» — فأرادوا بإبراهيمَ كيدًا وإهلاكًا، فجعلهم الله الأسفلين المقهورين المغلوبين، ونجّاه؛ ففي هذا أنّ كيدَ الباطلِ يرتدّ على أهله؛ فاعلم أنّ من كاد الحقَّ وأهله ردّ الله كيده في نحره، فلا تخف كيدَ الكائدين، فالعاقبةُ للحقِّ وأهله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ كيدَ الباطلِ يرتدّ على أهله، والعاقبةُ للحق."},"action":{"text":"اعلم أنّ قومَ إبراهيمَ أرادوا به كيدًا عظيمًا بإحراقه، فردّ الله كيدهم في نحورهم، وجعل النارَ عليه بردًا وسلامًا، وجعلهم الأسفلين المقهورين المغلوبين «فأرادوا به كيدا فجعلناهم الأسفلين»؛ فهذه سنّةُ الله: كيدُ الباطلِ يرتدّ على أهله، ومكرُهم يحيق بهم؛ فلا يحيق المكرُ السيّئُ إلا بأهله؛ فاعلم أنّ من كاد الحقَّ وأهله ردّ الله كيده عليه وأهلكه به؛ فلا تخف كيدَ الكائدين ومكرَ الماكرين ما دمت على الحق؛ فالعاقبةُ للحقِّ وأهله، والخِزيُ والسُّفلُ لأهلِ الباطل؛ فثق بنصرِ الله لأوليائه؛ فمن نصر دينَ الله نصره الله وأعلاه، ومن كاد الحقَّ أذلّه الله وأسفله؛ فاثبت على الحق، ودع الكائدين وكيدهم؛ فإنّ الله يتولّى الصالحين؛ فالنصرُ للحقِّ ولو بعد حين؛ فكن مع الحقِّ تكن من الأعلين."}}]},{"title":"هجرةُ إبراهيمَ ودعاؤه بالذريّة، والبشارةُ بالحليم، والذبحُ والفداءُ والبلاءُ المبين","range":[99,107],"theme":"هجرةُ إبراهيمَ إلى ربّه وثقتُه بهدايته، ودعاؤه بالذريةِ الصالحة، والبشارةُ بالغلامِ الحليمِ إسماعيل، ورؤيا ذبحِه وتسليمُ الأبِ والابنِ لأمرِ الله، والنداءُ عند تمامِ التسليمِ وتصديقِ الرؤيا، وأنه البلاءُ المبين، والفداءُ بذبحٍ عظيم","verses":[{"n":99,"reflection":{"text":"«وقال إني ذاهب إلى ربي سيهدين» — وقال إبراهيمُ مهاجرًا: إني ذاهبٌ إلى حيث أمرني ربي، سيهديني إلى ما فيه صلاحي؛ ففي هذا الهجرةُ في سبيلِ الله والثقةُ بهدايته؛ فهاجر بدينك حيث تعبد الله، وثق بهدايةِ الله لك، فمن ترك شيئًا لله عوّضه خيرًا منه، فاجعل رضا الله غايةَ رحلتك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الهجرةُ في سبيلِ الله، والثقةُ بهدايتِه للمهاجرِ إليه."},"action":{"text":"اقتدِ بإبراهيمَ حين فارق قومه وأرضه مهاجرًا إلى ربّه قائلًا بثقةٍ ويقين: إني ذاهبٌ إلى حيث أمرني ربي، سيهديني إلى ما فيه صلاحُ ديني ودنياي «وقال إني ذاهب إلى ربي سيهدين»؛ فالهجرةُ في سبيلِ الله وتركُ ما يُبعِد عن طاعتِه من أعظمِ القربات؛ فهاجر بدينك حيث تتمكّن من عبادةِ الله وطاعته، وفرَّ بدينك من الفتن؛ وثق بهدايةِ الله لك وتوفيقِه إذا صدقت في الهجرةِ إليه؛ فمن ترك شيئًا لله عوّضه الله خيرًا منه؛ فاجعل رضا الله غايةَ رحلتك وسفرك وسائرِ حركاتك؛ فمن خرج مهاجرًا إلى الله ورسولِه هداه الله وأعانه؛ فالثقةُ بهدايةِ الله زادُ المهاجرِ والمسافرِ في طاعته؛ فاعتزل ما يفسد دينك، واقصد ربك بقلبك وعملك؛ فسيهديك ويكفيك ويرعاك؛ فمن أقبل على الله أقبل الله عليه وهداه."}},{"n":100,"reflection":{"text":"«رب هب لي من الصالحين» — دعا إبراهيمُ ربَّه: ربِّ ارزقني ولدًا صالحًا من عبادك الصالحين؛ ففي هذا مشروعيةُ الدعاءِ بالذريةِ الصالحة؛ فادعُ الله أن يرزقك الذريةَ الصالحة، فالولدُ الصالحُ قرّةُ عينٍ وذخرٌ باقٍ، فاسأل الله صلاحَ ذريتك قبل وجودهم وبعده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعاءُ بالذريةِ الصالحةِ التي تُعينُ على الطاعة."},"action":{"text":"اقتدِ بإبراهيمَ في دعائه ربَّه أن يرزقه ولدًا صالحًا من عبادِه الصالحين، بعد أن هاجر إلى الله «رب هب لي من الصالحين»؛ فتأمّل كيف طلب الولدَ موصوفًا بالصلاح، لا مجرّدَ الولد؛ فادعُ الله أن يرزقك الذريةَ الصالحة، فالولدُ الصالحُ قرّةُ عينٍ في الدنيا، وذخرٌ باقٍ بعد الموتِ بدعائه؛ فاسأل الله صلاحَ ذريتك: أن يرزقك إياهم، وأن يُصلحهم لك؛ فالدعاءُ للذريةِ بالصلاحِ سنّةُ الأنبياءِ والصالحين؛ فادعُ الله: ربِّ هب لي من لدنك ذريةً طيبة، وأصلح لي في ذريتي؛ فالذريةُ الصالحةُ من أعظمِ نعمِ الله؛ فاعتنِ بطلبها من الله، ثم بتربيتها على الصلاحِ والتقوى؛ فمن رُزِق ذريةً صالحةً فقد رُزِق خيرًا كثيرًا؛ فاجعل الدعاءَ بصلاحِ الذريةِ من وردك الدائم؛ فالولدُ الصالحُ صدقةٌ جاريةٌ ودعوةٌ لا تنقطع."}},{"n":101,"reflection":{"text":"«فبشرناه بغلام حليم» — فبشّرنا إبراهيمَ بغلامٍ يبلغ الحلمَ ويوصَف به (وهو إسماعيل)؛ ففي هذا إجابةُ دعائه وفضلُ الحلم؛ فاعلم أنّ الله يجيب دعاءَ عباده، وأنّ الحلمَ من أشرفِ الصفات، فادعُ الله واثقًا بالإجابة، وتخلّق بالحلمِ الذي أثنى الله به على أنبيائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بإجابةِ الدعاء، والتخلّقُ بالحلم."},"action":{"text":"اعلم أنّ الله أجاب دعاءَ إبراهيمَ فبشّره بغلامٍ حليم، هو إسماعيلُ عليه السلام «فبشرناه بغلام حليم»؛ فتأمّل كيف عجّل الله له البشرى بعد الدعاء، ووصف الغلامَ بالحلم، وهو من أشرفِ الأخلاق؛ فالله يجيب دعاءَ عباده الصادقين؛ فادعُ الله واثقًا بالإجابة، ولا تستبطئ العطاء؛ وتخلّق بالحلمِ الذي أثنى الله به على أنبيائه؛ فالحلمُ ضبطُ النفسِ عند الغضب، والأناةُ وكظمُ الغيظ، والعفوُ عمّن أساء؛ فما أُعطي عبدٌ عطاءً خيرًا وأوسعَ من الحلم؛ فربِّ نفسك على الحلمِ والأناة؛ فالحليمُ محبوبٌ عند الله وعند الناس؛ فإذا غضبت فاكظم، وإذا قدرت فاعفُ، وإذا استُثِرت فتأنَّ؛ فالحلمُ سيّدُ الأخلاق؛ فاجعله خلقك، تنل محبّةَ الله ورضاه؛ فإبراهيمُ وابنُه كانا مثالًا في الحلمِ والصبرِ والتسليم."}},{"n":102,"reflection":{"text":"«فلما بلغ معه السعي قال يا بني إني أرى في المنام أني أذبحك...» — فلمّا كبر الغلامُ وبلغ أن يسعى مع أبيه، رأى إبراهيمُ في المنامِ أنه يذبحه (ورؤيا الأنبياءِ حق)، فشاور ابنه، فأجابه الابنُ بالتسليمِ والصبر؛ ففي هذا قمّةُ الطاعةِ والتسليمِ لأمرِ الله؛ فسلّم لأمرِ الله ولو خالف هواك، وربِّ أبناءك على الطاعةِ والتسليم، فالغلامُ سلّم لأمرِ الله وهو غلام.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ التامُّ لأمرِ الله، وتربيةُ الأبناءِ عليه."},"action":{"text":"تأمّل قمّةَ الطاعةِ والتسليم: لمّا بلغ إسماعيلُ أن يسعى مع أبيه، رأى إبراهيمُ في المنامِ أنه يذبحه — ورؤيا الأنبياءِ وحيٌ حق — فعرض الأمرَ على ابنه مشاورًا، فأجابه الابنُ بالتسليمِ الكامل: يا أبتِ افعل ما تؤمَر، ستجدني إن شاء الله من الصابرين «فلما بلغ معه السعي قال يا بني إني أرى في المنام أني أذبحك...»؛ فأيُّ تسليمٍ أعظمُ من أبٍ يمضي لذبحِ ولدِه طاعةً لله، وابنٍ يسلّم نفسه للذبحِ امتثالًا؟ فسلّم لأمرِ الله ولو خالف هواك ومحبوبك؛ فحقيقةُ الإسلامِ الاستسلامُ لله؛ وربِّ أبناءك على الطاعةِ والتسليمِ لله؛ فانظر كيف ربّى إبراهيمُ ابنه حتى بلغ هذا المبلغَ من التسليم؛ فشاور ابنك ولاطفه كما فعل إبراهيمُ «فانظر ماذا ترى»؛ واقرن التسليمَ بالاستعانةِ بالله «إن شاء الله»؛ فمن سلّم لله كفاه ورضي عنه؛ فاجعل شعارك: سمعنا وأطعنا؛ فالسعادةُ كلُّها في الاستسلامِ لأمرِ الله."}},{"n":103,"reflection":{"text":"«فلما أسلما وتله للجبين» — فلمّا استسلما لأمرِ الله وأصرّا عليه، وصرعه على جبينه ليذبحه؛ ففي هذا تمامُ العزمِ على الطاعةِ والمضيُّ فيها؛ فاعزم على طاعةِ الله وامضِ فيها بصدق، فالعبرةُ بالعزمِ الصادقِ والمضيِّ في الطاعة، فإبراهيمُ وابنُه مضيا في التنفيذِ فنالا الرضا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العزمُ الصادقُ على الطاعةِ والمضيُّ في تنفيذها."},"action":{"text":"تأمّل تمامَ الاستسلامِ والعزم: لمّا استسلم إبراهيمُ وابنُه لأمرِ الله وأصرّا على تنفيذه، وأضجعه على جبينه ليمرّ السكينُ على حلقه «فلما أسلما وتله للجبين»؛ فبلغا غايةَ العزمِ والمضيِّ في الطاعة، حتى باشرا أسبابَ التنفيذِ فعلًا؛ فاعزم على طاعةِ الله عزمًا صادقًا، وامضِ فيها بلا تردّدٍ ولا تسويف؛ فالعبرةُ بالعزمِ الصادقِ المقرونِ بالعمل، لا بمجرّدِ النيّةِ المتردّدة؛ فإبراهيمُ وابنُه لم يكتفيا بالنيّة، بل مضيا في التنفيذِ حتى الغاية، فنالا رضا الله وثناءه؛ فإذا عزمت على طاعةٍ فبادر إليها، ولا تدع الشيطانَ يثبّطك؛ فالتسويفُ آفةُ العزائم؛ فاصدق الله في عزمك، يصدقك في التوفيق؛ فمن عزم على الخيرِ ومضى فيه أعانه الله وأتمّه له؛ فالطاعةُ تحتاج عزيمةً ومضاءً، لا مجرّدَ أمانيّ؛ فاجعل عزمك صادقًا وعملك متبوعًا للعزم."}},{"n":104,"reflection":{"text":"«وناديناه أن يا إبراهيم» — وناديناه في تلك اللحظةِ الحرجة: يا إبراهيم؛ ففي هذا فرجُ الله عند اشتدادِ البلاءِ وتمامِ التسليم؛ فاعلم أنّ فرجَ الله يأتي عند اشتدادِ الكربِ وتمامِ التسليمِ لأمره، فسلّم لله وأحسن الظنَّ به، فمع العسرِ يسرًا، وعند تمامِ التسليمِ يأتي الفرج.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ فرجَ الله يأتي عند تمامِ التسليمِ والبلاء."},"action":{"text":"تأمّل كيف جاء نداءُ الله لإبراهيمَ في أحرجِ اللحظاتِ وقد أضجع ابنه ليذبحه: وناديناه أن يا إبراهيم «وناديناه أن يا إبراهيم»؛ فجاء الفرجُ عند اشتدادِ البلاءِ إلى منتهاه، وعند تمامِ التسليمِ لأمرِ الله؛ فاعلم أنّ فرجَ الله يأتي عند اشتدادِ الكربِ وبلوغِ البلاءِ غايتَه، وعند صدقِ التسليمِ لأمرِ الله؛ فما ضاق أمرٌ إلا اتّسع؛ ومع العسرِ يسرًا، إنّ مع العسرِ يسرًا؛ فسلّم لله في البلاء، وأحسن الظنَّ به، وانتظر فرجه؛ فمن صدق في التسليمِ لله عجّل الله فرجه؛ فلا تيأس عند اشتدادِ الكرب، فإنّ الفرجَ أقربُ ما يكون عند اشتدادِ الشدّة؛ فأشدُّ ساعاتِ الليلِ ظلمةً هي التي تسبق الفجر؛ فاصبر وسلّم وارجُ فرجَ الله؛ فالبلاءُ إذا تمَّ التسليمُ فيه أعقبه الفرجُ والرضا؛ فاجعل تسليمك لله بابًا لفرجه ورحمته."}},{"n":105,"reflection":{"text":"«قد صدقت الرؤيا إنا كذلك نجزي المحسنين» — قد حقّقت رؤياك بعزمك وتنفيذك للمأمور، إنا كذلك نجزي المحسنين بالتخفيفِ والفرجِ والثواب؛ ففي هذا أنّ الجزاءَ بالنيّةِ الصادقةِ والعزمِ الجازم؛ فاعلم أنّ الله يجزي على العزمِ الصادقِ والنيّةِ ولو لم يكتمل الفعلُ لعذر، فأخلص نيّتك وأحسن، فالله يجزي المحسنين بإحسانهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الله يجزي على النيّةِ الصادقةِ والعزمِ والإحسان."},"action":{"text":"اعلم أنّ الله قال لإبراهيمَ بعد أن أضجع ابنه ممتثلًا: قد صدّقت الرؤيا وحقّقت مقصودها بعزمك وتنفيذك، إنا كذلك نجزي المحسنين «قد صدقت الرؤيا إنا كذلك نجزي المحسنين»؛ فحصل المقصودُ بالعزمِ الصادقِ والمباشرة، ورُفِع الذبحُ رحمةً وجزاءً للإحسان؛ فالله يجزي على النيّةِ الصادقةِ والعزمِ الجازمِ ولو لم يكتمل الفعلُ لعذرٍ أو رفعِ الله له؛ فأخلص نيّتك، واعزم على الخيرِ عزمًا صادقًا، وأحسن في عملك؛ فمن نوى الخيرَ وعزم عليه وسعى فيه كُتِب له أجرُه ولو لم يتمّه لمانع؛ فالله كريمٌ يجزي المحسنين بأحسنَ من عملهم؛ فأحسن في نيّتك وعزمك وعملك؛ فالإحسانُ سببُ الجزاءِ الحسنِ والفرجِ والتخفيف؛ فاجعل الإحسانَ في السرِّ والعلنِ دأبك؛ فمن أحسن جزاه الله أحسنَ الجزاء، وفرّج عنه، ورفع عنه ما يكره؛ فالجزاءُ من جنسِ العملِ ومن جنسِ الإحسان."}},{"n":106,"reflection":{"text":"«إن هذا لهو البلاء المبين» — إنّ هذا الأمرَ (ذبحُ الولد) لهو الاختبارُ الظاهرُ البيّنُ الشديد؛ ففي هذا أنّ الابتلاءَ سنّةُ الله لتمييزِ الصادقين؛ فاعلم أنّ الله يبتلي عباده ليمحّصهم ويميّز صادقهم، فاصبر على البلاءِ واثبت، فالبلاءُ المبينُ يكشف صدقَ الإيمانِ ويرفع الدرجات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على البلاءِ المبين، وإدراكُ حكمتِه في التمحيص."},"action":{"text":"اعلم أنّ ما أُمِر به إبراهيمُ من ذبحِ ولدِه كان الاختبارَ الظاهرَ البيّنَ العظيم الذي لا اختبارَ أشدُّ منه «إن هذا لهو البلاء المبين»؛ فالابتلاءُ سنّةُ الله في أنبيائه وأوليائه، يمحّصهم به ويميّز صادقهم من غيره، ويرفع درجاتهم؛ فأشدُّ الناسِ بلاءً الأنبياءُ ثم الأمثلُ فالأمثل؛ فاعلم أنّ الله يبتلي عباده على قدرِ إيمانهم؛ فاصبر على البلاءِ واثبت، ولا تجزع؛ فالبلاءُ المبينُ يكشف صدقَ الإيمانِ ويظهر معدنَ الرجال؛ فمن صبر على البلاءِ ورضي فله الرضا، ومن جزع فله الجزع؛ فاستقبل البلاءَ بالصبرِ والتسليمِ والاحتساب؛ فعِظمُ الجزاءِ مع عِظمِ البلاء؛ فما ابتُلي عبدٌ ببلاءٍ فصبر إلا رفعه الله؛ فاجعل البلاءَ سببًا لرفعِ درجتك، لا لسخطك؛ فالصبرُ على الابتلاءِ من أعظمِ القربات؛ فاصبر واحتسب، وأبشر بحسنِ العاقبة."}},{"n":107,"reflection":{"text":"«وفديناه بذبح عظيم» — وفدينا الغلامَ بكبشٍ عظيمٍ أنزله الله بدلًا عنه؛ ففي هذا رحمةُ الله ولطفه بعباده بعد الابتلاء؛ فاعلم أنّ الله بعد البلاءِ يفرّج ويعوّض بالأحسن، فأحسن الظنَّ بالله في بلائك، فمن صبر واحتسب عوّضه الله، وجعل له من كلِّ ضيقٍ مخرجًا وفرجًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ برحمةِ الله ولطفِه بعد البلاء، وحسنُ الظنِّ به."},"action":{"text":"تأمّل رحمةَ الله ولطفه: بعد أن صدق إبراهيمُ وابنُه في التسليم، فدى الله الغلامَ بكبشٍ عظيمٍ عظيمِ القدرِ أنزله بدلًا عنه «وفديناه بذبح عظيم»؛ فجعل الله مكانَ الذبحِ العظيمِ فداءً، رحمةً بعبدِه وجزاءً لإحسانه؛ فاعلم أنّ الله بعد البلاءِ يفرّج، وبعد الشدّةِ يأتي بالرخاء، ويعوّض الصابرين بأحسنَ ممّا فقدوا؛ فأحسن الظنَّ بالله في بلائك ومحنتك؛ فمن صبر واحتسب عوّضه الله خيرًا، وجعل له من كلِّ همٍّ فرجًا ومن كلِّ ضيقٍ مخرجًا؛ فلطفُ الله بعباده الصادقين لا ينقطع؛ فثق برحمتِه ولطفه ولو اشتدّ البلاء؛ فما أراد الله بالمؤمنِ إلا خيرًا؛ فاصبر وأحسن الظنَّ، وانتظر لطفَ الله وفرجه؛ فمن كان مع الله كان الله معه، ولطف به من حيث لا يحتسب؛ فالفرجُ من الله قريب، ورحمتُه بالمحسنين واسعة؛ فسلّم لله، وثق بلطفه، وأبشر بحسنِ العاقبة."}}]},{"title":"تمامُ قصةِ إبراهيم: الثناءُ الباقي والبشارةُ بإسحاق","range":[108,113],"theme":"إبقاءُ الثناءِ الحسنِ على إبراهيمَ في الآخرين، والسلامُ عليه، وأنّ ذلك جزاءُ المحسنين المؤمنين، والبشارةُ بإسحاقَ نبيًّا صالحًا، والبركةُ عليه وعلى إسحاق، وأنّ من ذريّتهما محسنًا وظالمًا لنفسه، فالعبرةُ بالعملِ لا بالنسب","verses":[{"n":108,"reflection":{"text":"«وتركنا عليه في الآخرين» — وأبقينا لإبراهيمَ ثناءً حسنًا وذكرًا جميلًا في الأممِ الآخرين إلى يومِ القيامة؛ ففي هذا جزاءُ إحسانِه بالذكرِ الباقي؛ فاعلم أنّ الله يجزي المحسنين بالثناءِ الحسنِ الباقي، فأحسن عملك يبقَ لك الذكرُ الجميل، فالصلاةُ الإبراهيميةُ في كلِّ صلاةٍ شاهدةٌ على هذا الذكرِ الباقي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الذكرِ الحسنِ الباقي بإحسانِ العمل."},"action":{"text":"اعلم أنّ الله أبقى لإبراهيمَ ثناءً حسنًا وذكرًا جميلًا في الأممِ الآخرين إلى يومِ القيامة، جزاءً على إحسانه وصبره وتسليمه «وتركنا عليه في الآخرين»؛ حتى إنّا نصلّي عليه في كلِّ صلاةٍ «كما صلّيت على إبراهيم»؛ فالله يجزي المحسنين بالذكرِ الحسنِ الباقي في الدنيا مع الأجرِ في الآخرة؛ فأحسن عملك وأخلص لله، يبقَ لك الذكرُ الجميلُ والثناءُ الحسن؛ فالذكرُ الحسنُ عمرٌ ثانٍ للمحسن؛ فاسعَ لأن تُذكَر بالخيرِ بعد موتك بإحسانك وصلاحك؛ فمن أحسن في حياته بقي أثره الحسن؛ فاجعل سيرتك عطرةً بالإحسانِ والتسليمِ لله؛ فالثناءُ الحسنُ من عاجلِ بشرى المؤمن."}},{"n":109,"reflection":{"text":"«سلام على إبراهيم» — سلامٌ وأمانٌ وثناءٌ من الله على إبراهيمَ خليلِه؛ ففي هذا شرفُ السلامِ الإلهي على أوليائه؛ فاعلم أنّ أعظمَ الكرامةِ سلامُ الله على العبد، فاطلب رضا الله بالإحسانِ والتسليمِ لتنال سلامه، فسلامُ الله أعظمُ ما يُطلَب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ سلامِ الله ورضاه بالإحسانِ والتسليم."},"action":{"text":"اعلم أنّ الله سلّم على إبراهيمَ خليلِه وأثنى عليه، أمانًا له وثناءً وتكريمًا «سلام على إبراهيم»؛ فأعظمُ الكرامةِ أن يسلّم الله على العبدِ ويثني عليه في الملأ الأعلى؛ فاطلب رضا الله وسلامه بالإحسانِ والإخلاصِ والتسليمِ لأمره؛ فسلامُ الله على العبدِ أمانٌ له من كلِّ آفةٍ ونقص؛ فاجعل غايتك أن تنال رضا الله وسلامه؛ فمن أحسن وأخلص وسلّم لله نال السلامَ والثناء؛ فسلامُ الله أجلُّ ما يُنال، وأعظمُ ما يُطلَب؛ فاعمل عملَ من يرجو سلامَ ربه وثناءه؛ فاطلبه بالإحسانِ في عبادةِ الله ومعاملةِ خلقه، وبالتسليمِ التامِّ لأمره كما سلّم إبراهيم."}},{"n":110,"reflection":{"text":"«كذلك نجزي المحسنين» — كما جزينا إبراهيمَ بهذا الثناءِ والتكريمِ نجزي كلَّ محسنٍ في عمله؛ ففي هذا تقريرُ سنّةِ جزاءِ المحسنين؛ فأحسن في عملك لتكون من المحسنين الذين وعدهم الله بالجزاءِ الحسن، فالإحسانُ سبيلُ الجزاءِ الجميل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ في العملِ رجاءَ جزاءِ الله للمحسنين."},"action":{"text":"أحسن في عملك وعبادتك وتسليمك لله لتكون من المحسنين الذين وعدهم الله بالجزاءِ الحسن، كما جزى إبراهيمَ بالثناءِ الباقي والتكريم «كذلك نجزي المحسنين»؛ فهذه سنّةُ الله في جزاءِ المحسنين، لا تتخلّف؛ فالإحسانُ أن تعبد الله كأنك تراه، وأن تُسلّم لأمره، وتُتقن عملك، وتُحسن إلى خلقه؛ فمن أحسن جزاه الله أحسنَ الجزاء؛ فاجعل الإحسانَ دأبك في كلِّ ما تأتي وتذر؛ فالله يحبّ المحسنين ويجزيهم بالحسنى؛ فراقب إحسانك في عبادتك وأخلاقك ومعاملاتك؛ فكلّما أحسنت زاد جزاؤك؛ فالجزاءُ من جنسِ العمل؛ فمن أحسن أُحسِن إليه؛ فاطلب جزاءَ الله بالإحسانِ والتسليم."}},{"n":111,"reflection":{"text":"«إنه من عبادنا المؤمنين» — إنّ إبراهيمَ من عبادنا المؤمنين الذين صدق إيمانهم؛ ففي هذا أنّ الإيمانَ الصادقَ أصلُ الإحسانِ والكرامة؛ فحقّق الإيمانَ الصادقَ في قلبك، فهو أصلُ كلِّ خير، فمن صدق إيمانه استحقّ كرامةَ الله وثناءه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ الإيمانِ الصادق، فهو أصلُ الإحسانِ والكرامة."},"action":{"text":"اعلم أنّ الله وصف إبراهيمَ خليلَه بأنه من عبادِه المؤمنين الصادقين، فكان ذلك أصلَ إحسانه وكرامته وثنائه «إنه من عبادنا المؤمنين»؛ فالإيمانُ الصادقُ أصلُ كلِّ خير، وبه تُنال كرامةُ الله؛ فحقّق الإيمانَ في قلبك تصديقًا وإذعانًا، وفي لسانك إقرارًا، وفي جوارحك عملًا وتسليمًا؛ فمن صدق إيمانه استحقّ كرامةَ الله؛ فاعتنِ بإيمانك: قوِّه بالطاعةِ والذكرِ والتفكّرِ والتسليم، وصُنه عن المعاصي؛ فالإيمانُ يزيد بالطاعةِ وينقص بالمعصية؛ فتعاهد إيمانك بالتقويةِ والتجديد؛ فمن قوي إيمانه حسُن عمله وسلّم لربه؛ فاجعل تحقيقَ الإيمانِ الصادقِ همّك الأول؛ فهو رأسُ الأمرِ وأساسُ الكرامةِ والنجاة."}},{"n":112,"reflection":{"text":"«وبشرناه بإسحاق نبيا من الصالحين» — وبشّرنا إبراهيمَ بإسحاقَ نبيًّا من الصالحين، جزاءً على صبره وتسليمه؛ ففي هذا فضلُ الله على المسلّمِ لأمره بالعطاءِ المضاعف؛ فاعلم أنّ الله يعوّض من سلّم لأمره خيرًا وبركة، فسلّم لله في كلِّ أمرك، فمن صبر وسلّم أعطاه الله فوق ما يرجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله يعوّض المسلّمَ لأمره بالعطاءِ المضاعف."},"action":{"text":"تأمّل كيف عوّض الله إبراهيمَ بعد تسليمِه لأمرِ ذبحِ ابنه، فبشّره بإسحاقَ ولدًا آخرَ نبيًّا من الصالحين «وبشرناه بإسحاق نبيا من الصالحين»؛ فمن سلّم لأمرِ الله وصبر عوّضه الله خيرًا مضاعفًا وبركةً في العطاء؛ فاعلم أنّ الله يعوّض من سلّم لأمره ورضي بقضائه بالعطاءِ الواسعِ والبركة؛ فسلّم لله في كلِّ أمرك، وارضَ بقضائه، ولا تحزن على ما فاتك في طاعته؛ فمن صبر وسلّم أعطاه الله فوق ما يرجو، وبارك له فيما أبقى؛ فالتسليمُ لأمرِ الله بابُ الخيرِ والبركة؛ فما ترك أحدٌ شيئًا لله إلا عوّضه خيرًا منه؛ فإذا ابتُلي المؤمنُ فسلّم ورضي فتح الله له أبوابَ فضله؛ فاجعل التسليمَ والرضا سبيلك، وانتظر عطاءَ الله وبركته؛ فالله لا يضيع أجرَ من أحسن عملًا، ولا يخيّب من سلّم لأمره."}},{"n":113,"reflection":{"text":"«وباركنا عليه وعلى إسحاق ومن ذريتهما محسن وظالم لنفسه مبين» — وباركنا على إبراهيمَ وإسحاقَ ببركةِ الدينِ والذريّة، ومن ذريّتهما محسنٌ لنفسه وظالمٌ لها بيّنُ الظلم؛ ففي هذا أنّ شرفَ النسبِ لا ينفع مع الظلم؛ فاعلم أنّ العبرةَ بالعملِ لا بالنسب، فلا يغرّنك شرفُ أصلك، بل اعمل صالحًا، فمن ذريّةِ الأنبياءِ ظالمٌ لنفسه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ العبرةَ بالعملِ لا بالنسب، والسعيُ للإحسان."},"action":{"text":"اعلم أنّ الله بارك على إبراهيمَ وإسحاقَ ببركةِ النبوّةِ والدينِ وكثرةِ الذريّة، ثم بيّن أنّ من ذريّتهما محسنًا لنفسه بالطاعةِ والإيمان، وظالمًا لها بيّنَ الظلمِ بالكفرِ والمعصية «وباركنا عليه وعلى إسحاق ومن ذريتهما محسن وظالم لنفسه مبين»؛ فشرفُ النسبِ لا ينفع مع ظلمِ النفسِ بالكفرِ والمعاصي؛ فالعبرةُ بالعملِ الصالحِ لا بشرفِ الأصلِ والنسب؛ فلا يغرّنك شرفُ آبائك وأصلك، فمن أبطأ به عمله لم يسرع به نسبه؛ فاسعَ للإحسانِ إلى نفسك بالطاعةِ والإيمان، ولا تظلمها بالمعصيةِ والكفران؛ فكلٌّ يُجزى بعمله لا بنسبه؛ فانظر إلى نفسك: أمحسنٌ أنت أم ظالمٌ لها؟ فبادر بالإحسانِ قبل فواتِ الأوان؛ فالنجاةُ بالعملِ الصالحِ والإيمان، لا بالانتسابِ إلى الصالحين؛ فاعمل صالحًا تكن من المحسنين، ولا تظلم نفسك فتكون من الخاسرين."}}]},{"title":"موسى وهارون: المنُّ والنجاةُ والنصرُ والكتابُ والهدايةُ والثناء","range":[114,122],"theme":"المنُّ على موسى وهارونَ بالنبوّة، ونجاتُهما وقومِهما من الكربِ العظيمِ ونصرُهم وغلبتُهم، وإيتاؤهما الكتابَ المستبينَ وهدايتُهما الصراطَ المستقيم، وإبقاءُ الثناءِ عليهما والسلامُ عليهما، وأنهما من عبادِ الله المؤمنين","verses":[{"n":114,"reflection":{"text":"«ولقد مننا على موسى وهارون» — ولقد أنعمنا على موسى وهارون بالنبوّةِ والرسالةِ وسائرِ النعم؛ ففي هذا تعدادُ نعمةِ الله على أنبيائه؛ فاعلم أنّ كلَّ خيرٍ فمنّةٌ من الله وفضل، فانسب النعمَ إلى الله واشكرها، ولا تنسبها إلى حولك وقوّتك، فالفضلُ كلُّه بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"نسبةُ النعمِ إلى الله وشكرُها، وإدراكُ أنها منّةٌ وفضل."},"action":{"text":"اعلم أنّ الله منّ على موسى وهارون بالنبوّةِ والرسالةِ والنصرِ والكتابِ والهداية «ولقد مننا على موسى وهارون»؛ فكلُّ خيرٍ يصيب العبدَ فهو منّةٌ من الله وفضل، لا بحولِ العبدِ وقوّته؛ فانسب النعمَ إلى الله وحده، واشكرها له، ولا تنسبها إلى نفسك وذكائك وسعيك؛ فالفضلُ كلُّه بيدِ الله يؤتيه من يشاء؛ فمن نسب النعمةَ إلى الله شكرها فزادها الله، ومن نسبها إلى نفسه كفرها فسلبها الله؛ فأكثر من شكرِ الله على نعمه الظاهرةِ والباطنة؛ فاستشعر منّةَ الله عليك في كلِّ نعمة: في دينك وإيمانك، في صحّتك ورزقك، في أهلك وولدك؛ فما بك من نعمةٍ فمن الله؛ فقابل النعمَ بالشكرِ والطاعة، لا بالبطرِ والمعصية؛ فالشكرُ قيدُ النعمِ وسببُ المزيد؛ فاجعل قلبك ولسانك وجوارحك في شكرِ منّةِ الله."}},{"n":115,"reflection":{"text":"«ونجيناهما وقومهما من الكرب العظيم» — ونجّينا موسى وهارونَ وقومهما بني إسرائيلَ من الكربِ العظيمِ (استعبادِ فرعونَ والغرق)؛ ففي هذا أنّ الله ينجّي أولياءه من الشدائد؛ فاعلم أنّ الله ينجّي عباده المؤمنين من الكرب، فالجأ إليه في كربك، فمن التجأ إلى الله نجّاه من كلِّ شدّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في تنجيةِ الله من الكرب، والالتجاءُ إليه."},"action":{"text":"اعلم أنّ الله نجّى موسى وهارونَ وقومهما بني إسرائيلَ من الكربِ العظيم: من استعبادِ فرعونَ وظلمِه وتقتيلِه، ومن الغرقِ في البحر «ونجيناهما وقومهما من الكرب العظيم»؛ فالله ينجّي عباده المؤمنين من الشدائدِ والكرب مهما عظمت؛ فالجأ إلى الله في كربك وضيقك، فهو المنجّي من كلِّ شدّة؛ فمن التجأ إلى الله بصدقٍ نجّاه؛ فلا تيأس عند اشتدادِ الكربِ ولو أحاط بك العدوُّ من كلِّ جانب، كما أُحيط ببني إسرائيلَ بين البحرِ وفرعون؛ فإنّ مع موسى قال «كلا إنّ معي ربي سيهدين»، ففرج الله عنهم؛ فأحسن الظنَّ بالله، وارجُ تنجيته؛ فكم من كربٍ عظيمٍ فرّجه الله عن أوليائه في أحلكِ اللحظات؛ فاجعل الله ملجأك ومنجاك؛ فمن صدق اللجوءَ إلى الله كفاه ونجّاه؛ فالفرجُ من الله قريب."}},{"n":116,"reflection":{"text":"«ونصرناهم فكانوا هم الغالبين» — ونصرنا موسى وهارونَ وقومهم على فرعونَ وجنده، فكانوا هم الغالبين الظاهرين؛ ففي هذا أنّ العاقبةَ والغلبةَ لأهلِ الإيمان؛ فاعلم أنّ نصرَ الله لأوليائه حقٌّ، فاثبت على الحقِّ واصبر، فالعاقبةُ للمتّقين، والغلبةُ لجندِ الله ولو بعد حين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ العاقبةَ والغلبةَ لأهلِ الإيمانِ والحق."},"action":{"text":"اعلم أنّ الله نصر موسى وهارونَ وقومهم على فرعونَ وجنودِه، فكانوا هم الغالبين الظاهرين، وأغرق عدوَّهم «ونصرناهم فكانوا هم الغالبين»؛ فهذه سنّةُ الله: النصرُ والغلبةُ لأهلِ الإيمانِ والحقِّ ولو بعد استضعافٍ وشدّة؛ فاعلم أنّ نصرَ الله لأوليائه حقٌّ لا يتخلّف؛ فاثبت على الحقِّ واصبر على الأذى، فالعاقبةُ للمتّقين؛ فلا يغرّنك تسلّطُ أهلِ الباطلِ حينًا، فإنّ العاقبةَ للمؤمنين؛ فالغلبةُ لجندِ الله ولو بعد حين؛ فاجتهد في أسبابِ النصرِ من الإيمانِ والتقوى والصبرِ والإعدادِ والتوكّل؛ فمن نصر دينَ الله نصره الله؛ فثق بوعدِ الله بنصرِ عباده المؤمنين؛ فكم من فئةٍ قليلةٍ غلبت فئةً كثيرةً بإذنِ الله؛ فالنصرُ من عند الله؛ فاصبر واثبت وتوكّل، وانتظر نصرَ الله وغلبته لأوليائه؛ فإنّ العاقبةَ للتقوى."}},{"n":117,"reflection":{"text":"«وآتيناهما الكتاب المستبين» — وأعطينا موسى وهارونَ الكتابَ (التوراة) الواضحَ البيّن؛ ففي هذا نعمةُ الكتابِ الهادي المبيّن؛ فاعلم أنّ أعظمَ النعمِ نعمةُ الكتابِ الهادي، فاشكر الله على القرآنِ المبين، واهتدِ به، فالكتابُ المبينُ نورٌ يهدي إلى الصراطِ المستقيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الكتابِ الهادي، والاهتداءُ به."},"action":{"text":"اعلم أنّ الله أنعم على موسى وهارونَ بالكتابِ المستبينِ الواضحِ في أحكامه وأخباره، وهو التوراة «وآتيناهما الكتاب المستبين»؛ فأعظمُ النعمِ نعمةُ الكتابِ الهادي الذي يبيّن الحقَّ من الباطل، والهدى من الضلال؛ فاشكر الله على أعظمِ كتابٍ وأتمِّه: القرآنِ المبين، الذي هدى الله به من الضلالة، وبصّر به من العمى؛ فاهتدِ بالقرآن: اتلُه، وتدبّره، واعمل به، وتحاكم إليه؛ فالكتابُ المبينُ نورٌ يهدي إلى الصراطِ المستقيم؛ فمن اعتصم به هُدي، ومن أعرض عنه ضلّ؛ فاجعل القرآنَ إمامك ودليلك في كلِّ أمرك؛ فما أنزل الله الكتابَ إلا ليُتدبَّر ويُعمَل به؛ فاقبل على كتابِ ربك تلاوةً وتدبّرًا وعملًا؛ فهو حبلُ الله المتين، وصراطُه المستقيم، ونوره المبين؛ فاشكر نعمةَ الكتابِ بالاهتداءِ به والعملِ بمقتضاه."}},{"n":118,"reflection":{"text":"«وهديناهما الصراط المستقيم» — وهدينا موسى وهارونَ الصراطَ المستقيمَ (الدينَ الحقّ)؛ ففي هذا أنّ الهدايةَ فضلٌ من الله ومنّة؛ فاسأل الله الهدايةَ للصراطِ المستقيمِ دائمًا، فهي أعظمُ ما تُطلَب، وأنت تسألها في كلِّ صلاةٍ «اهدنا الصراط المستقيم»، فألحّ في طلبها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"سؤالُ الله الهدايةَ للصراطِ المستقيمِ والثباتَ عليه."},"action":{"text":"اعلم أنّ الله هدى موسى وهارونَ الصراطَ المستقيم، وهو الدينُ الحقُّ الموصلُ إلى الله وإلى جنّته «وهديناهما الصراط المستقيم»؛ فالهدايةُ إلى الصراطِ المستقيمِ أعظمُ نعمةٍ ومنّةٍ من الله؛ فاسأل الله الهدايةَ للصراطِ المستقيمِ والثباتَ عليه دائمًا؛ فأنت تسألها في كلِّ ركعةٍ من صلاتك «اهدنا الصراط المستقيم»، لعظمِ حاجتك إليها في كلِّ لحظة؛ فألحّ في طلبها، فما أعطي عبدٌ عطاءً أفضلَ منها؛ فالهدايةُ نوعان: هدايةُ الدلالةِ والإرشاد، وهدايةُ التوفيقِ والإلهام؛ فاطلبهما من الله؛ فلا يهدي إلى الصراطِ المستقيمِ إلا الله؛ فلا تعتمد على علمك وعقلك، بل افتقر إلى هدايةِ الله؛ فمن هداه الله فهو المهتد، ومن يضلل فلن تجد له وليًّا مرشدًا؛ فأكثر من دعاءِ الهدايةِ والثبات؛ فالقلوبُ بين إصبعين من أصابعِ الرحمن يقلّبها كيف يشاء؛ فاسأله الثباتَ على دينه حتى الممات."}},{"n":119,"reflection":{"text":"«وتركنا عليهما في الآخرين» — وأبقينا لموسى وهارونَ ثناءً حسنًا وذكرًا جميلًا في الأممِ الآخرين؛ ففي هذا جزاءُ إحسانهما بالذكرِ الباقي؛ فاعلم أنّ الله يجزي المحسنين بالثناءِ الحسنِ الباقي، فأحسن عملك يبقَ لك الذكرُ الجميل، فالإحسانُ يخلّد الذكرَ الطيّب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الذكرِ الحسنِ الباقي بإحسانِ العمل."},"action":{"text":"اعلم أنّ الله أبقى لموسى وهارونَ ثناءً حسنًا وذكرًا جميلًا في الأممِ الآخرين إلى يومِ القيامة، جزاءً على إحسانهما «وتركنا عليهما في الآخرين»؛ فالله يجزي المحسنين بالذكرِ الحسنِ الباقي في الدنيا مع الأجرِ في الآخرة؛ فأحسن عملك وأخلص لله، يبقَ لك الذكرُ الجميلُ والثناءُ الحسن؛ فالذكرُ الحسنُ عمرٌ ثانٍ للمحسن؛ فاسعَ لأن تُذكَر بالخيرِ بعد موتك بإحسانك وصلاحك؛ فمن أحسن في حياته بقي أثره الحسن؛ فاجعل سيرتك عطرةً بالإحسانِ والصلاح؛ فالثناءُ الحسنُ من عاجلِ بشرى المؤمن؛ فأحسن تُذكَر بالخير، ويبقَ لك الأثرُ الجميلُ والدعوةُ الصالحة."}},{"n":120,"reflection":{"text":"«سلام على موسى وهارون» — سلامٌ وأمانٌ وثناءٌ من الله على موسى وهارون؛ ففي هذا شرفُ السلامِ الإلهي على أوليائه؛ فاعلم أنّ أعظمَ الكرامةِ سلامُ الله على العبد، فاطلب رضا الله بالإحسانِ لتنال سلامه، فسلامُ الله أعظمُ ما يُطلَب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ سلامِ الله ورضاه بالإحسان."},"action":{"text":"اعلم أنّ الله سلّم على موسى وهارونَ وأثنى عليهما، أمانًا وثناءً وتكريمًا «سلام على موسى وهارون»؛ فأعظمُ الكرامةِ أن يسلّم الله على العبدِ ويثني عليه؛ فاطلب رضا الله وسلامه بالإحسانِ والإخلاصِ وحملِ رسالتِه؛ فسلامُ الله على العبدِ أمانٌ له من كلِّ آفةٍ ونقص، وثناءٌ عليه في الملأ الأعلى وفي الأرض؛ فاجعل غايتك أن تنال رضا الله وسلامه؛ فمن أحسن وأخلص نال السلامَ والثناء؛ فسلامُ الله أعظمُ ما يُطلَب، وأجلُّ ما يُنال؛ فاعمل عملَ من يرجو سلامَ ربه؛ فاطلبه بالإحسانِ في عبادةِ الله ونصحِ خلقه والصبرِ على أذاهم."}},{"n":121,"reflection":{"text":"«إنا كذلك نجزي المحسنين» — إنا كما جزينا موسى وهارونَ بهذا الثناءِ نجزي كلَّ محسن؛ ففي هذا تقريرُ سنّةِ جزاءِ المحسنين؛ فأحسن في عملك لتكون من المحسنين الذين وعدهم الله بالجزاءِ الحسن، فالإحسانُ سبيلُ الجزاءِ الجميل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ في العملِ رجاءَ جزاءِ الله."},"action":{"text":"أحسن في عملك وعبادتك ومعاملتك لتكون من المحسنين الذين وعدهم الله بالجزاءِ الحسن، كما جزى موسى وهارونَ بالنصرِ والثناءِ الباقي «إنا كذلك نجزي المحسنين»؛ فهذه سنّةُ الله في جزاءِ المحسنين لا تتخلّف؛ فالإحسانُ أن تعبد الله كأنك تراه، وأن تُتقن عملك، وتُحسن إلى خلقه؛ فمن أحسن جزاه الله أحسنَ الجزاء؛ فاجعل الإحسانَ دأبك في كلِّ ما تأتي وتذر؛ فالله يحبّ المحسنين ويجزيهم بالحسنى؛ فراقب إحسانك في عبادتك وأخلاقك ومعاملاتك؛ فكلّما أحسنت زاد جزاؤك؛ فالجزاءُ من جنسِ العمل؛ فمن أحسن أُحسِن إليه؛ فاطلب جزاءَ الله بالإحسان."}},{"n":122,"reflection":{"text":"«إنهما من عبادنا المؤمنين» — إنّ موسى وهارونَ من عبادنا المؤمنين الصادقين؛ ففي هذا أنّ الإيمانَ الصادقَ أصلُ الإحسانِ والكرامة؛ فحقّق الإيمانَ الصادقَ في قلبك، فهو أصلُ كلِّ خير، فمن صدق إيمانه استحقّ كرامةَ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ الإيمانِ الصادق، فهو أصلُ الكرامة."},"action":{"text":"اعلم أنّ الله وصف موسى وهارونَ بأنهما من عبادِه المؤمنين الصادقين، فكان ذلك أصلَ إحسانهما وكرامتهما «إنهما من عبادنا المؤمنين»؛ فالإيمانُ الصادقُ أصلُ كلِّ خير، وبه تُنال كرامةُ الله؛ فحقّق الإيمانَ في قلبك تصديقًا وإذعانًا، وفي لسانك إقرارًا، وفي جوارحك عملًا؛ فمن صدق إيمانه استحقّ كرامةَ الله؛ فاعتنِ بإيمانك: قوِّه بالطاعةِ والذكرِ والتفكّر، وصُنه عن المعاصي؛ فالإيمانُ يزيد بالطاعةِ وينقص بالمعصية؛ فتعاهد إيمانك بالتقويةِ والتجديد؛ فمن قوي إيمانه حسُن عمله؛ فاجعل تحقيقَ الإيمانِ الصادقِ همّك الأول؛ فهو أساسُ الكرامةِ والنجاة."}}]},{"title":"إلياس: الدعوةُ إلى تقوى الله ونبذِ بعل، والثناءُ عليه","range":[123,132],"theme":"رسالةُ إلياسَ ودعوتُه قومه إلى تقوى الله ونبذِ عبادةِ بعلٍ إلى عبادةِ أحسنِ الخالقين ربِّ الجميع، وتكذيبُهم له وإحضارُهم في العذابِ إلا المخلصين، وإبقاءُ الثناءِ عليه والسلامُ عليه، وأنه من عبادِ الله المؤمنين","verses":[{"n":123,"reflection":{"text":"«وإن إلياس لمن المرسلين» — وإنّ إلياسَ عليه السلام لمن رسلِ الله؛ ففي هذا تقريرُ رسالتِه وتزكيتُه؛ فاعلم أنّ الرسلَ كثيرون أرسلهم الله رحمةً بالعباد، فآمن بجميعِ رسلِ الله، ولا تفرّق بينهم، فالإيمانُ بالرسلِ جميعًا من أصولِ الدين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بجميعِ رسلِ الله دون تفريق."},"action":{"text":"اعلم أنّ إلياسَ عليه السلام كان من رسلِ الله الذين أرسلهم رحمةً بالعبادِ وهدايةً لهم «وإن إلياس لمن المرسلين»؛ فالرسلُ كثيرون، أرسلهم الله إلى الأممِ يدعونهم إلى توحيدِه وطاعته؛ فآمن بجميعِ رسلِ الله من ذكر الله منهم ومن لم يذكر، ولا تفرّق بين أحدٍ منهم؛ فالإيمانُ بالرسلِ جميعًا من أصولِ الدينِ وأركانِ الإيمان؛ فمن كذّب رسولًا واحدًا فقد كذّب الرسلَ جميعًا؛ فوقّر رسلَ الله وأحبّهم، واتّبع ما جاؤوا به من الحق؛ فرسالتهم واحدةٌ في أصلها: الدعوةُ إلى توحيدِ الله؛ فاجعل الإيمانَ بالرسلِ راسخًا في قلبك؛ فهم صفوةُ الله من خلقه، وسفراؤه إلى عباده؛ فاتّبع خاتمهم محمدًا ﷺ، ففي اتّباعه اتّباعٌ لهم جميعًا؛ فالإيمانُ بالرسلِ والاقتداءُ بهم سبيلُ النجاة."}},{"n":124,"reflection":{"text":"«إذ قال لقومه ألا تتقون» — حين قال إلياسُ لقومه: ألا تتّقون الله فتحذرون عقابه؟ ففي هذا أنّ التقوى أصلُ دعوةِ الرسل؛ فاجعل التقوى شعارك ودعوتك، فهي وصيّةُ الله للأوّلين والآخرين، فاتّقِ الله حيثما كنت، وادعُ الناسَ إلى تقواه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ التقوى والدعوةُ إليها، فهي أصلُ دعوةِ الرسل."},"action":{"text":"اعلم أنّ إلياسَ افتتح دعوةَ قومه بالأمرِ بالتقوى: ألا تتّقون الله فتحذرون عقابه وتمتثلون أمره؟ «إذ قال لقومه ألا تتقون»؛ فالتقوى أصلُ دعوةِ الرسلِ جميعًا، وبها افتتحوا نداءهم لأقوامهم؛ فاجعل التقوى شعارك ووصيّتك ودعوتك؛ فهي وصيّةُ الله للأوّلين والآخرين «ولقد وصّينا الذين أوتوا الكتابَ من قبلكم وإياكم أن اتّقوا الله»؛ فاتّقِ الله حيثما كنت: امتثل أوامره واجتنب نواهيه، واجعل بينك وبين عذابه وقايةً من طاعته؛ فالتقوى جِماعُ الخير كلِّه؛ فمن اتّقى الله وقاه وكفاه وجعل له مخرجًا ورزقًا؛ فادعُ الناسَ إلى تقوى الله، وابدأ بنفسك؛ فأوصِ أهلك ومن حولك بالتقوى؛ فالمتّقون هم الفائزون في الدنيا والآخرة؛ فاجعل التقوى زادك في كلِّ أمرك، فخيرُ الزادِ التقوى."}},{"n":125,"reflection":{"text":"«أتدعون بعلا وتذرون أحسن الخالقين» — أتعبدون صنمًا اسمه بعل، وتتركون عبادةَ الله أحسنِ الخالقين؟ ففي هذا إنكارُ الشركِ وتقريرُ أنّ الله أحسنُ الخالقين؛ فتأمّل قبحَ تركِ عبادةِ الخالقِ الأحسنِ إلى عبادةِ مخلوقٍ عاجز، فوحّد أحسنَ الخالقين، ولا تصرف العبادةَ لسواه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله أحسنِ الخالقين، ونبذُ عبادةِ ما سواه."},"action":{"text":"تأمّل حجّةَ إلياسَ على قومه حين أنكر عبادتهم لصنمٍ اسمه «بعل» وتركهم عبادةَ الله أحسنِ الخالقين «أتدعون بعلا وتذرون أحسن الخالقين»؛ فأيُّ سفهٍ أعظمُ من تركِ عبادةِ الخالقِ الأحسنِ الذي أتقن كلَّ شيءٍ خلقه، إلى عبادةِ صنمٍ عاجزٍ لا يخلق ولا ينفع؟ فالله أحسنُ الخالقين، أتقن كلَّ شيء، وأحسن كلَّ ما صنع؛ فوحّده وحده بالعبادة، ولا تصرف شيئًا منها لسواه؛ فتفكّر في بديعِ خلقِ الله وإتقانِه، يزدك ذلك يقينًا بتوحيده؛ فمن نظر في حسنِ خلقِ الله عرف أنه المستحقُّ للعبادة؛ فانبذ عبادةَ كلِّ ما سوى الله من صنمٍ أو قبرٍ أو هوى؛ فأخلص العبادةَ لأحسنِ الخالقين؛ فهو وحده الخالقُ الرازقُ المدبّر؛ فكيف يُترَك الخالقُ ويُعبَد المخلوق؟ فاعبد الله أحسنَ الخالقين، وأفرده بكلِّ أنواعِ العبادة."}},{"n":126,"reflection":{"text":"«الله ربكم ورب آبائكم الأولين» — هو الله ربّكم وربُّ آبائكم الأوّلين، لا ربَّ سواه؛ ففي هذا تقريرُ ربوبيةِ الله الشاملةِ للجميع؛ فاعلم أنّ الله ربّك وربُّ آبائك وكلِّ شيء، فأفرده بالعبادةِ كما تفرّد بالربوبية، فمن كان ربًّا للجميع فهو المستحقُّ للعبادةِ وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بربوبيةِ الله الشاملة، وإفرادُه بالعبادة."},"action":{"text":"اعلم أنّ إلياسَ بيّن لقومه أنّ المعبودَ بحقٍّ هو الله ربّهم وربُّ آبائهم الأوّلين، الذي خلقهم وخلق آباءهم ورزق الجميع «الله ربكم ورب آبائكم الأولين»؛ فالله ربُّ الخلقِ أجمعين، المتفرّدُ بالخلقِ والرزقِ والتدبير؛ فإذا كان هو الربَّ الخالقَ للجميعِ من الأوّلين والآخرين، فهو المستحقُّ للعبادةِ وحده؛ فأفرده بالعبادةِ كما تفرّد بالربوبية؛ فالإقرارُ بأنّ الله ربُّ كلِّ شيءٍ يوجب إفرادَه بالألوهيةِ والعبادة؛ فلا تعبد مع ربِّ العالمين سواه؛ فمن أقرّ بربوبيةِ الله لزمه أن يعبده وحده؛ فاجعل عبادتك كلَّها لله ربِّك وربِّ آبائك؛ فهو ربُّ كلِّ شيءٍ ومليكه؛ فلا معبودَ بحقٍّ إلا هو؛ فوحّده في ربوبيتِه وألوهيتِه وأسمائه وصفاته؛ فذلك هو التوحيدُ الخالص."}},{"n":127,"reflection":{"text":"«فكذبوه فإنهم لمحضرون» — فكذّب قومُ إلياسَ رسولَهم، فإنهم لمحضرون في العذابِ يومَ القيامة؛ ففي هذا عاقبةُ تكذيبِ الرسل؛ فاحذر أن تكذّب الحقَّ فتُحضَر في العذاب، فاتّبع الرسلَ وصدّقهم، فمصيرُ المكذّبين الإحضارُ للحساب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تكذيبِ الحقِّ وعاقبتِه، وتصديقُ الرسل."},"action":{"text":"اعلم أنّ قومَ إلياسَ كذّبوه ولم يستجيبوا لدعوته، فتوعّدهم الله بأنهم محضرون في العذابِ يومَ القيامة جزاءَ تكذيبهم «فكذبوه فإنهم لمحضرون»؛ فهذه عاقبةُ تكذيبِ الرسلِ ورفضِ الحق: الإحضارُ للحسابِ والعذاب؛ فاحذر أن تكذّب الحقَّ أو تعرض عنه فتكون من المحضرين للعذاب؛ فاتّبع الرسلَ وصدّقهم فيما جاؤوا به، واعمل بما دعوا إليه؛ فمصيرُ المكذّبين الإحضارُ للحسابِ والعقاب؛ فبادر بالإيمانِ والتصديقِ والاتّباع؛ فالتكذيبُ سببُ الهلاكِ والعذاب، والتصديقُ سببُ النجاةِ والفوز؛ فلا تعرض عن دعوةِ الحقِّ إذا بلغتك؛ فاجعل من عاقبةِ المكذّبين عبرةً تحملك على الإيمانِ والاتّباع؛ فمن كذّب أُحضِر للعذاب، ومن آمن نجا وفاز؛ فاختر لنفسك سبيلَ الناجين المصدّقين."}},{"n":128,"reflection":{"text":"«إلا عباد الله المخلصين» — لكن عبادَ الله المخلصين الذين أخلصوا العبادةَ له نجوا من الإحضارِ في العذاب؛ ففي هذا استثناءُ المخلصين من العذاب؛ فأخلص عبادتك لله لتكون من الناجين، فالإخلاصُ سببُ النجاة، فاجعل عملك خالصًا لوجهِ الله، فالمخلصون هم الناجون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله للنجاةِ من العذاب."},"action":{"text":"أخلص عبادتك وعملك لله وحده لتكون من عبادِ الله المخلصين الذين استُثنوا من الإحضارِ في العذاب «إلا عباد الله المخلصين»؛ فالإخلاصُ سببُ النجاةِ من العذاب؛ فاجعل عملك كلَّه خالصًا لوجهِ الله، لا رياءً ولا سمعةً ولا طلبًا لعرضِ الدنيا؛ فالمخلصون هم الناجون المكرمون؛ فراقب نيّتك في أعمالك: هل هي خالصةٌ لله؟ فطهّرها من شوائبِ الرياءِ والسمعةِ وحظوظِ النفس؛ فمن أخلص لله نجا، ومن راءى خسر؛ فالإخلاصُ روحُ العملِ وسببُ قبوله؛ فاجعل الإخلاصَ همّك في كلِّ عمل؛ فالله لا يقبل من العملِ إلا ما كان خالصًا له وابتُغي به وجهه؛ فأخلص لله في عبادتك ودعائك وسائرِ عملك؛ فبالإخلاصِ تنجو من العذابِ وتفوز بالنعيم؛ فالمخلصون هم الناجون في الدنيا والآخرة؛ فجاهد نفسك على تحقيقِ الإخلاص."}},{"n":129,"reflection":{"text":"«وتركنا عليه في الآخرين» — وأبقينا لإلياسَ ثناءً حسنًا وذكرًا جميلًا في الأممِ الآخرين؛ ففي هذا جزاءُ إحسانِه بالذكرِ الباقي؛ فاعلم أنّ الله يجزي المحسنين بالثناءِ الحسنِ الباقي، فأحسن عملك يبقَ لك الذكرُ الجميل، فالإحسانُ يخلّد الذكرَ الطيّب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الذكرِ الحسنِ الباقي بإحسانِ العمل."},"action":{"text":"اعلم أنّ الله أبقى لإلياسَ ثناءً حسنًا وذكرًا جميلًا في الأممِ الآخرين إلى يومِ القيامة، جزاءً على إحسانه وصبره على دعوةِ قومه «وتركنا عليه في الآخرين»؛ فالله يجزي المحسنين بالذكرِ الحسنِ الباقي في الدنيا مع الأجرِ في الآخرة؛ فأحسن عملك وأخلص لله، يبقَ لك الذكرُ الجميلُ والثناءُ الحسن؛ فالذكرُ الحسنُ عمرٌ ثانٍ للمحسن؛ فاسعَ لأن تُذكَر بالخيرِ بعد موتك بإحسانك وصلاحك ودعوتك إلى الله؛ فمن أحسن في حياته بقي أثره الحسن؛ فاجعل سيرتك عطرةً بالإحسانِ والصلاحِ والدعوةِ إلى الحق؛ فالثناءُ الحسنُ من عاجلِ بشرى المؤمن."}},{"n":130,"reflection":{"text":"«سلام على إل ياسين» — سلامٌ وأمانٌ وثناءٌ من الله على إلياسَ (وقُرِئ: آلِ ياسين أي آلِ محمدٍ أو أتباعِ إلياس)؛ ففي هذا شرفُ السلامِ الإلهي؛ فاعلم أنّ أعظمَ الكرامةِ سلامُ الله على العبد، فاطلب رضا الله بالإحسانِ لتنال سلامه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ سلامِ الله ورضاه بالإحسان."},"action":{"text":"اعلم أنّ الله سلّم على إلياسَ وأثنى عليه أمانًا وتكريمًا «سلام على إل ياسين»؛ فأعظمُ الكرامةِ أن يسلّم الله على العبدِ ويثني عليه في الملأ الأعلى؛ فاطلب رضا الله وسلامه بالإحسانِ والإخلاصِ والدعوةِ إليه؛ فسلامُ الله على العبدِ أمانٌ له من كلِّ آفةٍ ونقص، وثناءٌ عليه في السماواتِ والأرض؛ فاجعل غايتك أن تنال رضا الله وسلامه؛ فمن أحسن وأخلص نال السلامَ والثناء؛ فسلامُ الله أعظمُ ما يُطلَب، وأجلُّ ما يُنال؛ فاعمل عملَ من يرجو سلامَ ربه؛ فاطلبه بالإحسانِ في عبادةِ الله ومعاملةِ خلقه؛ فكن ممّن يستحقّ سلامَ الله وثناءه بصدقِ العبوديةِ والإخلاص."}},{"n":131,"reflection":{"text":"«إنا كذلك نجزي المحسنين» — إنا كما جزينا إلياسَ بالثناءِ نجزي كلَّ محسن؛ ففي هذا تقريرُ سنّةِ جزاءِ المحسنين؛ فأحسن في عملك لتكون من المحسنين الموعودين بالجزاءِ الحسن، فالإحسانُ سبيلُ الجزاءِ الجميل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ في العملِ رجاءَ جزاءِ الله."},"action":{"text":"أحسن في عملك وعبادتك ودعوتك لتكون من المحسنين الذين وعدهم الله بالجزاءِ الحسن، كما جزى إلياسَ بالثناءِ الباقي «إنا كذلك نجزي المحسنين»؛ فهذه سنّةُ الله في جزاءِ المحسنين لا تتخلّف؛ فالإحسانُ أن تعبد الله كأنك تراه، وأن تُتقن عملك، وتُحسن إلى خلقه، وتصبر على أذاهم في الدعوة؛ فمن أحسن جزاه الله أحسنَ الجزاء؛ فاجعل الإحسانَ دأبك في كلِّ ما تأتي وتذر؛ فالله يحبّ المحسنين ويجزيهم بالحسنى؛ فراقب إحسانك في عبادتك وأخلاقك ومعاملاتك؛ فكلّما أحسنت زاد جزاؤك؛ فالجزاءُ من جنسِ العمل؛ فمن أحسن أُحسِن إليه؛ فاطلب جزاءَ الله بالإحسان."}},{"n":132,"reflection":{"text":"«إنه من عبادنا المؤمنين» — إنّ إلياسَ من عبادنا المؤمنين الصادقين؛ ففي هذا أنّ الإيمانَ الصادقَ أصلُ الإحسانِ والكرامة؛ فحقّق الإيمانَ الصادقَ في قلبك، فهو أصلُ كلِّ خير، فمن صدق إيمانه استحقّ كرامةَ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ الإيمانِ الصادق، فهو أصلُ الكرامة."},"action":{"text":"اعلم أنّ الله وصف إلياسَ بأنه من عبادِه المؤمنين الصادقين، فكان ذلك أصلَ إحسانه وكرامته «إنه من عبادنا المؤمنين»؛ فالإيمانُ الصادقُ أصلُ كلِّ خير، وبه تُنال كرامةُ الله؛ فحقّق الإيمانَ في قلبك تصديقًا وإذعانًا، وفي لسانك إقرارًا، وفي جوارحك عملًا؛ فمن صدق إيمانه استحقّ كرامةَ الله؛ فاعتنِ بإيمانك: قوِّه بالطاعةِ والذكرِ والدعوةِ إلى الله، وصُنه عن المعاصي؛ فالإيمانُ يزيد بالطاعةِ وينقص بالمعصية؛ فتعاهد إيمانك بالتقويةِ والتجديد؛ فاجعل تحقيقَ الإيمانِ الصادقِ همّك الأول؛ فهو أساسُ الكرامةِ والنجاة."}}]},{"title":"لوط: نجاتُه وأهلِه وهلاكُ الباقين، والاعتبارُ بديارهم","range":[133,138],"theme":"رسالةُ لوطٍ ونجاتُه وأهلِه أجمعين إلا امرأتَه من الغابرين، وتدميرُ المكذّبين، والدعوةُ للاعتبارِ بآثارهم التي يمرّ عليها الناسُ صباحًا وليلًا، والحثُّ على إعمالِ العقلِ في الاتّعاظ","verses":[{"n":133,"reflection":{"text":"«وإن لوطا لمن المرسلين» — وإنّ لوطًا عليه السلام لمن رسلِ الله؛ ففي هذا تقريرُ رسالتِه وتزكيتُه؛ فاعلم أنّ الله أرسل الرسلَ لهدايةِ العباد، فآمن بجميعِ رسلِ الله، واتّبع ما جاؤوا به من الحق، فالإيمانُ بالرسلِ من أصولِ الدين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ برسلِ الله واتّباعُ ما جاؤوا به."},"action":{"text":"اعلم أنّ لوطًا عليه السلام كان من رسلِ الله الذين أرسلهم لهدايةِ العبادِ ودعوتهم إلى التوحيدِ ونهيهم عن الفواحش «وإن لوطا لمن المرسلين»؛ فالرسلُ كثيرون، بعثهم الله رحمةً بالخلق؛ فآمن بجميعِ رسلِ الله، واتّبع ما جاؤوا به من الحقِّ والهدى؛ فالإيمانُ بالرسلِ من أصولِ الدينِ وأركانِ الإيمان؛ فوقّرهم وأحبّهم، واقتدِ بهم في الدعوةِ إلى الله والصبرِ على الأذى؛ فلوطٌ دعا قومه إلى التوحيدِ ونهاهم عن فاحشةٍ لم يسبقهم إليها أحد؛ فاتّبع سبيلَ الرسلِ في الأمرِ بالمعروفِ والنهيِ عن المنكر؛ فهم القدوةُ والأسوة؛ فمن اتّبع الرسلَ نجا، ومن خالفهم هلك؛ فاجعل الإيمانَ بالرسلِ والاقتداءَ بهم منهجك؛ فاتّبع خاتمهم محمدًا ﷺ، ففيه الهدى والنجاة."}},{"n":134,"reflection":{"text":"«إذ نجيناه وأهله أجمعين» — حين نجّينا لوطًا وأهله المؤمنين أجمعين من العذابِ الذي حلَّ بقومه؛ ففي هذا أنّ الله ينجّي أولياءه المؤمنين؛ فاعلم أنّ الله ينجّي المؤمنين من العذابِ النازلِ بالمكذّبين، فآمن واعمل صالحًا لتكون من الناجين، فالإيمانُ سببُ النجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في تنجيةِ الله للمؤمنين، والعملُ لأسبابِها."},"action":{"text":"اعلم أنّ الله نجّى لوطًا وأهله المؤمنين أجمعين حين أنزل العذابَ بقومه المكذّبين المصرّين على الفاحشة «إذ نجيناه وأهله أجمعين»؛ فالله ينجّي عباده المؤمنين من العذابِ النازلِ بالمكذّبين والفاسقين؛ فاعلم أنّ الإيمانَ والعملَ الصالحَ سببُ النجاةِ من عذابِ الله؛ فآمن بالله واعمل صالحًا، واجتنب الفواحشَ والمنكرات، لتكون من الناجين؛ فمن آمن وعمل صالحًا نجّاه الله؛ فالجأ إلى الله واعتصم بطاعته؛ فكم من عذابٍ عامٍّ نجّى الله منه المؤمنين؛ فاجعل إيمانك وطاعتك حصنك من العذاب؛ فالله لا يهلك المؤمنين مع الظالمين إذا اجتنبوا معاصيهم وأنكروا عليهم؛ فكن من المؤمنين العاملين المجتنبين للفواحش؛ فبذلك تكون من أهلِ النجاةِ والفوز؛ فالنجاةُ ثمرةُ الإيمانِ والعملِ الصالحِ واجتنابِ ما نهى الله عنه."}},{"n":135,"reflection":{"text":"«إلا عجوزا في الغابرين» — إلا امرأتَه العجوزَ التي كانت من الباقين في العذابِ لكفرها؛ ففي هذا أنّ القرابةَ لا تنفع مع الكفر؛ فاعلم أنّ صلةَ النسبِ بالصالحين لا تنفع مع الكفرِ والخيانة، فامرأةُ النبيِّ هلكت بكفرها، فاعتمد على إيمانك وعملك لا على قرابتك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ القرابةَ لا تنفع مع الكفر، والاعتمادُ على العمل."},"action":{"text":"اعلم أنّ الله نجّى لوطًا وأهله إلا امرأتَه العجوزَ التي بقيت في العذابِ مع الهالكين، لأنها كانت كافرةً خائنةً لزوجها في الدين، تدلّ قومه على أضيافه «إلا عجوزا في الغابرين»؛ فالقرابةُ والصلةُ بالصالحين لا تنفع صاحبها مع الكفرِ والخيانة؛ فامرأةُ نبيٍّ كريمٍ هلكت بكفرها رغمَ كونها تحت رسول؛ فاعلم أنّ النجاةَ بالإيمانِ والعملِ الصالح، لا بالنسبِ والقرابة؛ فلا يغرّنك انتسابك إلى صالحٍ أو قربك منه إن لم يكن معك إيمانٌ وعمل؛ فاعتمد على إيمانك وعملك، لا على قرابتك ونسبك؛ فكلٌّ يُجزى بعمله؛ فلن يغني عنك أحدٌ من الله شيئًا؛ فاسعَ لنفسك بالإيمانِ والطاعة؛ فمن نفعه عملُه لم يضرّه نسبه، ومن ضرّه عملُه لم ينفعه نسبه؛ فاجعل نجاتك بعملك الصالحِ وإيمانك الصادق، لا بمجرّدِ الانتسابِ إلى الصالحين."}},{"n":136,"reflection":{"text":"«ثم دمرنا الآخرين» — ثم أهلكنا القومَ الآخرين المكذّبين تدميرًا؛ ففي هذا عاقبةُ الإصرارِ على الفاحشةِ والتكذيب؛ فاعتبر بعاقبةِ المصرّين على المعاصي والفواحش، واحذر أن تكون منهم، فمصيرُ المكذّبين المصرّين الدمار، فاجتنب الفواحشَ وتب إلى الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ المصرّين على الفاحشة، واجتنابُها."},"action":{"text":"اعتبر بعاقبةِ قومِ لوطٍ الذين دمّرهم الله تدميرًا، فجعل عاليها سافلها وأمطر عليهم حجارةً من سِجّيل، جزاءَ إصرارهم على الفاحشةِ والتكذيب «ثم دمرنا الآخرين»؛ فهذه عاقبةُ المصرّين على المعاصي والفواحشِ والتكذيب: الدمارُ والهلاك؛ فاحذر أن تكون من المصرّين على المعاصي فيحلَّ بك ما حلَّ بهم؛ فاجتنب الفواحشَ ما ظهر منها وما بطن؛ فالمعاصي سببُ العقوباتِ وزوالِ النعم؛ فبادر بالتوبةِ إلى الله من كلِّ ذنب؛ فمن أصرّ على المعصيةِ عرّض نفسه لعقوبةِ الله؛ فاجعل من مصارعِ الأممِ الهالكةِ عبرةً تحملك على التقوى واجتنابِ المحارم؛ فما هلك الهالكون إلا بالإصرارِ على المعاصي والتكذيب؛ فتب إلى الله، واجتنب ما نهى عنه، وأنكر المنكرَ حولك؛ فالسلامةُ في التقوى واجتنابِ الفواحش."}},{"n":137,"reflection":{"text":"«وإنكم لتمرون عليهم مصبحين» — وإنكم أيها المخاطبون لتمرّون على ديارِ قومِ لوطٍ المهلكةِ في الصباحِ وأنتم مسافرون؛ ففي هذا الدعوةُ للاعتبارِ بآثارِ الهالكين؛ فاعتبر بآثارِ الأممِ الهالكةِ إذا مررت بها، فديارهم شاهدةٌ على عاقبةِ المعصية، فلا تمرَّ بها غافلًا، بل معتبرًا متّعظًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بآثارِ الهالكين عند المرورِ بها، وعدمُ الغفلة."},"action":{"text":"اعلم أنّ الله ذكّر المخاطبين بأنهم يمرّون على ديارِ قومِ لوطٍ المهلكةِ في أسفارهم صباحًا «وإنكم لتمرون عليهم مصبحين»؛ فديارهم الخربةُ شاهدةٌ على عاقبةِ المعصيةِ والتكذيب؛ فاعتبر بآثارِ الأممِ الهالكةِ إذا مررت بها أو سمعت بأخبارها؛ فلا تمرَّ بمصارعِ الهالكين غافلًا لاهيًا، بل معتبرًا متّعظًا خائفًا؛ فكم في آثارِ الأممِ الغابرةِ من عبرةٍ لأولي الأبصار؛ فسِر في الأرضِ وانظر كيف كان عاقبةُ المكذّبين؛ فتلك القرى نقصّ عليك من أنبائها؛ فاجعل مرورك بديارِ الهالكين موعظةً تزيدك خشيةً وتقوى؛ فمن اعتبر بغيرِه سلم، ومن غفل عن العبرِ هلك؛ فلا تكن من الغافلين الذين يمرّون على الآياتِ وهم عنها معرضون؛ فاعتبر واتّعظ، وخف أن يحلَّ بك ما حلَّ بمن قبلك؛ فالسعيدُ من وُعِظ بغيره."}},{"n":138,"reflection":{"text":"«وبالليل أفلا تعقلون» — وتمرّون عليهم بالليلِ أيضًا، أفلا تعقلون فتعتبرون؟ ففي هذا الحثُّ على إعمالِ العقلِ في الاعتبار؛ فأعمل عقلك في الاعتبارِ بمصارعِ الهالكين، فالعقلُ حجّةٌ عليك، فمن رأى العبرةَ ولم يعتبر فقد عطّل عقله، فاعتبر بعقلك واتّعظ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعمالُ العقلِ في الاعتبارِ والاتّعاظِ بالعبر."},"action":{"text":"اعلم أنّ الله حثّ المخاطبين على إعمالِ عقولهم في الاعتبارِ حين يمرّون على ديارِ قومِ لوطٍ صباحًا ومساءً: أفلا تعقلون فتتّعظون؟ «وبالليل أفلا تعقلون»؛ فالعقلُ إنما أُعطيه الإنسانُ ليعتبر ويتّعظ وينظر في العواقب؛ فأعمل عقلك في الاعتبارِ بمصارعِ الهالكين وعواقبِ المكذّبين؛ فالعقلُ حجّةٌ عليك لا لك إن لم تستعمله في الحق؛ فمن رأى العبرةَ ولم يعتبر، وبلغه الخبرُ ولم يتّعظ، فقد عطّل نعمةَ العقلِ التي أكرمه الله بها؛ فاستعمل عقلك في التفكّرِ والاعتبارِ والاستدلالِ على الله؛ فالتفكّرُ عبادةٌ عظيمة؛ فتأمّل في آياتِ الله وأخبارِ الأمم، واستخلص منها العبرَ والدروس؛ فمن عقل عن الله اتّعظ وأناب؛ فاجعل عقلك خادمًا لإيمانك، دالًّا لك على الحقِّ والهدى؛ فالعقلاءُ حقًّا هم المتّعظون المعتبرون، لا الغافلون المعرضون."}}]},{"title":"يونس: العجلةُ والتقامُ الحوتِ والتسبيحُ والنجاةُ والإرسال","range":[139,148],"theme":"رسالةُ يونسَ وإباقُه إلى الفلكِ المشحون، والمساهمةُ والتقامُ الحوتِ له وهو مليم، وأنّ تسبيحَه كان سببَ نجاته، ونبذُه بالعراءِ سقيمًا وإنباتُ شجرةِ اليقطينِ عليه رحمةً، وإرسالُه إلى مائةِ ألفٍ أو يزيدون فآمنوا فمتّعهم الله إلى حين","verses":[{"n":139,"reflection":{"text":"«وإن يونس لمن المرسلين» — وإنّ يونسَ عليه السلام لمن رسلِ الله؛ ففي هذا تقريرُ رسالتِه؛ فاعلم أنّ الله أرسل الرسلَ رحمةً بالعباد، فآمن بجميعِ رسلِ الله، واتّعظ بقصصهم، ففي قصصِ الرسلِ عبرٌ وعِظات، فتدبّرها لتزداد إيمانًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ برسلِ الله والاتّعاظُ بقصصهم."},"action":{"text":"اعلم أنّ يونسَ عليه السلام كان من رسلِ الله «وإن يونس لمن المرسلين»؛ فآمن بجميعِ رسلِ الله، واتّعظ بقصصهم؛ فقصّةُ يونسَ فيها عبرٌ عظيمة: في العجلةِ وتركِ الصبر، وفي رحمةِ الله بعبده حين سبّح ودعاه في الظلمات؛ فتدبّر قصصَ الرسلِ لتزداد إيمانًا وعبرة؛ فما قصّ الله علينا أنباءهم إلا لنعتبر ونثبّت به قلوبنا؛ فخذ من كلِّ قصّةٍ درسها وعبرتها؛ فمن قصّةِ يونسَ نتعلّم الصبرَ على الدعوةِ وعدمَ العجلة، ونتعلّم أنّ الله يقبل توبةَ من أناب إليه ولو من قعرِ البحرِ في بطنِ الحوت؛ فاجعل قصصَ الأنبياءِ زادًا لإيمانك ومعينًا على طاعتك؛ فتدبّرها بقلبٍ حاضر، واستخلص منها العبرَ والعِظات؛ فالإيمانُ بالرسلِ والاتّعاظُ بأخبارهم سبيلُ الهدى."}},{"n":140,"reflection":{"text":"«إذ أبق إلى الفلك المشحون» — حين ذهب يونسُ مغاضبًا لقومه إلى السفينةِ المملوءةِ بالركّابِ والمتاع، قبل أن يؤذَن له؛ ففي هذا التنبيهُ على خطرِ العجلةِ ومفارقةِ المأمور؛ فاحذر العجلةَ في مفارقةِ ما أُمِرت به، واصبر على ما كُلّفت به، فالعجلةُ من الشيطان، والصبرُ على الأمرِ سلامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من العجلةِ ومفارقةِ المأمور، ولزومُ الصبر."},"action":{"text":"اعلم أنّ يونسَ ذهب مغاضبًا لقومه إلى السفينةِ المملوءةِ بالركّابِ والمتاع، تاركًا موضعَه قبل أن يأذن الله له بالمفارقة «إذ أبق إلى الفلك المشحون»؛ ففي هذا تنبيهٌ على خطرِ العجلةِ ومفارقةِ ما أُمِر به العبد؛ فاحذر العجلةَ في مفارقةِ ما أُمِرت به من طاعةٍ أو موضعٍ أو تكليف؛ واصبر على ما كُلّفت به وإن شقّ عليك؛ فالعجلةُ من الشيطان، والتأنّي والصبرُ من الله؛ فلا تفارق مقامَ الطاعةِ ضجرًا أو غضبًا؛ فيونسُ نبيٌّ كريم، عاتبه الله على عجلتِه ومفارقتِه قومه قبل الإذن؛ فما بالك بغيره؟ فالزم الصبرَ على الدعوةِ والطاعةِ والبلاء؛ ولا تستعجل النتائج؛ فالصبرُ على الأمرِ سلامةٌ وعاقبتُه حميدة؛ فتعلّم من قصّةِ يونسَ أن تصبر ولا تعجل، وأن تلزم مقامك الذي أقامك الله فيه حتى يأذن لك؛ فالعجلةُ مزلّةٌ، والصبرُ منجاة."}},{"n":141,"reflection":{"text":"«فساهم فكان من المدحضين» — فاقترع مع أهلِ السفينةِ (لمّا ثقلت وخافوا الغرق)، فكان من المغلوبين الذين خرجت عليهم القرعةُ فأُلقي في البحر؛ ففي هذا جريانُ قدرِ الله على العبد؛ فاعلم أنّ قدرَ الله نافذ، فسلّم لقضاءِ الله ولو خالف مرادك، فما قدّره الله كائنٌ لا محالة، فارضَ بقضائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لقدرِ الله وقضائه النافذ."},"action":{"text":"اعلم أنّ السفينةَ لمّا ثقلت وأشرفت على الغرقِ اقترع ركّابها ليُلقوا أحدهم تخفيفًا، فخرجت القرعةُ على يونسَ فكان من المغلوبين الذين أُلقوا في البحر «فساهم فكان من المدحضين»؛ فجرى قدرُ الله على عبده يونسَ ليتمّ ما أراده الله به من الابتلاءِ ثم الرحمة؛ فاعلم أنّ قدرَ الله نافذٌ لا يُردّ؛ فسلّم لقضاءِ الله وقدرِه ولو خالف مرادك وهواك؛ فما قدّره الله كائنٌ لا محالة؛ فارضَ بقضاءِ الله، وأحسن الظنَّ به في كلِّ ما يجري عليك؛ فما أصابك لم يكن ليخطئك، وما أخطأك لم يكن ليصيبك؛ فالإيمانُ بالقدرِ ركنٌ من أركانِ الإيمان؛ فمن سلّم لقدرِ الله وجد الراحةَ والطمأنينة؛ فلا تتسخّط قضاءَ الله، بل سلّم وارضَ؛ فوراءَ أقدارِ الله حكمٌ ورحماتٌ قد تخفى عليك؛ ففي قدرِ يونسَ بإلقائه في البحرِ كانت رحمةُ الله وتوبتُه عليه؛ فسلّم لله في أقداره، وثق بحكمتِه ورحمته."}},{"n":142,"reflection":{"text":"«فالتقمه الحوت وهو مليم» — فابتلعه الحوتُ وهو آتٍ بما يُلام عليه من مغاضبةِ قومه قبل الإذن؛ ففي هذا أنّ العبدَ قد يُبتلى بسببِ زلّته؛ فاعلم أنّ الذنوبَ والزلّاتِ قد تجرّ الشدائد، فتب من زلّاتك، وحاسب نفسك، فإذا نزلت بك شدّةٌ فانظر في ذنوبك وتب إلى الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفسِ على الزلّات، والتوبةُ عند نزولِ الشدائد."},"action":{"text":"اعلم أنّ الحوتَ التقم يونسَ في البحر، وهو مليمٌ أي آتٍ بما يُلام عليه من مغاضبةِ قومه ومفارقتهم قبل إذنِ الله «فالتقمه الحوت وهو مليم»؛ ففي هذا أنّ العبدَ قد يُبتلى بالشدائدِ بسببِ زلّته وذنبه؛ فاعلم أنّ الذنوبَ والمعاصيَ قد تجرّ الشدائدَ والمحن؛ فحاسب نفسك على زلّاتك وتقصيرك؛ فإذا نزلت بك شدّةٌ أو بليّةٌ فانظر في ذنوبك وتب إلى الله منها؛ فما نزل بلاءٌ إلا بذنب، ولا رُفِع إلا بتوبة؛ فبادر بالتوبةِ والاستغفارِ عند نزولِ الشدائد؛ فالتوبةُ تكشف الكرب؛ فيونسُ لمّا التقمه الحوتُ سبّح ودعا وأناب، فنجّاه الله؛ فاقتدِ به في الرجوعِ إلى الله عند الشدّة؛ فحاسب نفسك دائمًا قبل أن تُحاسَب؛ فمن حاسب نفسه واستغفر من زلّاته سلم؛ فاجعل المحاسبةَ والتوبةَ دأبك؛ فبها تُكشَف الكروبُ وتُقال العثرات."}},{"n":143,"reflection":{"text":"«فلولا أنه كان من المسبحين» — فلولا أنّ يونسَ كان من المكثرين لتسبيحِ الله وذكرِه (قبل البلاءِ وفيه)؛ ففي هذا فضلُ التسبيحِ وأثرُه في النجاة؛ فأكثر من تسبيحِ الله وذكرِه في الرخاء، ينفعك في الشدّة، فالذكرُ في الرخاءِ سببُ الفرجِ في الشدّة، فاعمر أوقاتك بالتسبيح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من التسبيحِ والذكرِ في الرخاء، فينفعُ في الشدّة."},"action":{"text":"تأمّل فضلَ التسبيح: لولا أنّ يونسَ كان من المكثرين لتسبيحِ الله وذكرِه في رخائه، وسبّح في بطنِ الحوتِ داعيًا «لا إله إلا أنت سبحانك إني كنت من الظالمين»، لبقي في بطنِ الحوتِ إلى يومِ القيامة «فلولا أنه كان من المسبحين»؛ فالتسبيحُ والذكرُ في الرخاءِ سببُ الفرجِ والنجاةِ في الشدّة؛ فأكثر من تسبيحِ الله وذكرِه في رخائك وسعتك، ينفعك في شدّتك وكربك؛ فمن عرف الله في الرخاءِ عرفه الله في الشدّة؛ فاعمر أوقاتك بالتسبيحِ والتحميدِ والذكر؛ فالذاكرون الله كثيرًا لهم مغفرةٌ وأجرٌ عظيم؛ فاجعل لسانك رطبًا بذكرِ الله؛ فبالذكرِ تطمئنّ القلوب، وتُكشَف الكروب، وتُقضى الحوائج؛ فلا تغفل عن ذكرِ الله؛ فمن كان من المسبحين في رخائه نجّاه الله في شدّته؛ فاتّخذ من التسبيحِ والذكرِ زادًا دائمًا؛ فدعوةُ ذي النونِ ما دعا بها مكروبٌ إلا فرّج الله كربه؛ فألحّ على الله بالذكرِ والدعاء."}},{"n":144,"reflection":{"text":"«للبث في بطنه إلى يوم يبعثون» — لبقي يونسُ في بطنِ الحوتِ سجنًا له إلى يومِ القيامة؛ ففي هذا عظمُ أثرِ الذكرِ في النجاة، وسعةُ رحمةِ الله بالتائبين؛ فاعلم أنّ رحمةَ الله واسعةٌ للتائبين المسبّحين، فلا تيأس من رحمةِ الله مهما اشتدّ كربك، فبالتسبيحِ والتوبةِ يأتي الفرج.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ اليأسِ من رحمةِ الله، والفرجُ بالتوبةِ والتسبيح."},"action":{"text":"اعلم أنّ يونسَ لولا تسبيحه وذكرُه لبقي في بطنِ الحوتِ سجنًا له إلى يومِ القيامة «للبث في بطنه إلى يوم يبعثون»؛ ففي هذا بيانُ عظمِ أثرِ الذكرِ والتسبيحِ في تفريجِ الكرب، وسعةِ رحمةِ الله بالتائبين المنيبين؛ فاعلم أنّ رحمةَ الله واسعةٌ لمن تاب وأناب وسبّح، مهما عظم ذنبه واشتدّ كربه؛ فلا تيأس من رحمةِ الله؛ فمن أخرج يونسَ من ظلماتِ البحرِ وبطنِ الحوتِ قادرٌ على أن يفرّج كربك مهما اشتدّ؛ فبالتسبيحِ والتوبةِ والدعاءِ والإنابةِ يأتي الفرج؛ فألحّ على الله بالذكرِ والدعاءِ والتوبة عند كربك؛ فإنّ الله يجيب المضطرَّ إذا دعاه ويكشف السوء؛ فادعُ الله بدعاءِ ذي النون؛ فالفرجُ من الله قريب لمن أناب إليه وسبّحه؛ فاجعل التسبيحَ والتوبةَ ملجأك عند الشدائد؛ فرحمةُ الله وسعت كلَّ شيء، وهي قريبةٌ من التائبين المسبّحين."}},{"n":145,"reflection":{"text":"«فنبذناه بالعراء وهو سقيم» — فطرحناه بالفضاءِ الخالي على ساحلِ البحرِ وهو مريضٌ ضعيفٌ من طولِ المكثِ في بطنِ الحوت؛ ففي هذا لطفُ الله بعبده بعد الشدّة؛ فاعلم أنّ الله يلطف بعبده بعد الشدّةِ ويرفق به، فأحسن الظنَّ بالله في ضعفك ومرضك، فمن رحمه الله بعد شدّةٍ رفق به وتداركه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بلطفِ الله ورفقِه بعد الشدّة."},"action":{"text":"تأمّل لطفَ الله بعبده يونس: بعد أن أخرجه من بطنِ الحوت، طرحه برحمتِه بالفضاءِ الخالي على ساحلِ البحرِ وهو مريضٌ ضعيفٌ من طولِ ما لبث في بطنِ الحوت «فنبذناه بالعراء وهو سقيم»؛ فتعهّده الله بلطفِه ورعايتِه في حالِ ضعفه ومرضه؛ فاعلم أنّ الله يلطف بعبده بعد الشدّةِ ويرفق به ويتداركه برحمته؛ فأحسن الظنَّ بالله في ضعفك ومرضك وشدّتك؛ فمن رحمه الله بعد شدّةٍ رفق به وتولّاه؛ فلطفُ الله بعباده لا ينقطع؛ فبعد كلِّ عسرٍ يسر، وبعد كلِّ شدّةٍ رخاء؛ فثق برحمةِ الله ولطفه ولو كنت في أضعفِ أحوالك؛ فالله أرحم بك من نفسك؛ فإذا مرضت أو ضعفت أو نزل بك ما نزل، فاعلم أنّ الله لطيفٌ بك، يتعهّدك برحمته؛ فاصبر وأحسن الظنَّ، وانتظر لطفَ الله؛ فهو اللطيفُ الخبيرُ بعباده، الرفيقُ بهم في شدّتهم ورخائهم."}},{"n":146,"reflection":{"text":"«وأنبتنا عليه شجرة من يقطين» — وأنبتنا فوقه شجرةً من يقطين (القرع) تظلّله وينتفع بها في ضعفه؛ ففي هذا تمامُ لطفِ الله ورعايتِه لعبده؛ فتأمّل رحمةَ الله في تدبيرِ ما ينفع عبده في وقتِ حاجته، فاشكر الله على تدبيرِه لك ما ينفعك، فمن رحمةِ الله أن يهيّئ لك ما تحتاجه في ضعفك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ لطفِ الله في تدبيرِ ما ينفعُ العبدَ عند حاجته."},"action":{"text":"تأمّل تمامَ لطفِ الله بيونس: أنبت عليه شجرةً من يقطينٍ — وهو القرعُ — تظلّله بورقها الواسعِ وتقيه الشمسَ والذبابَ، وينتفع بثمرها في حالِ ضعفه ومرضه «وأنبتنا عليه شجرة من يقطين»؛ فانظر كيف دبّر الله لعبده في ضعفه ما ينفعه ويرفق به؛ فمن رحمةِ الله بعباده أن يهيّئ لهم ما يحتاجونه في أوقاتِ ضعفهم وشدّتهم من حيث لا يحتسبون؛ فاشكر الله على تدبيرِه لك ما ينفعك ويصلح حالك؛ فكم من نعمةٍ يسوقها الله إليك في وقتِ حاجتك؛ فتأمّل في تدبيرِ الله لك، وارضَ به، واشكره عليه؛ فالله أعلمُ بما يصلحك، وأرحمُ بك من نفسك؛ فاجعل قلبك ممتلئًا بشكرِ الله على لطفِه وتدبيرِه؛ فهو الرزّاقُ اللطيفُ الذي يسوق الأرزاقَ والمنافعَ لعباده في أوقاتها؛ فمن تأمّل لطفَ الله في تدبيرِه ازداد حبًّا له وشكرًا؛ فاشكر الله، وأحسن الظنَّ بتدبيرِه، وثق بلطفِه ورعايته."}},{"n":147,"reflection":{"text":"«وأرسلناه إلى مائة ألف أو يزيدون» — وأرسلنا يونسَ إلى قومٍ عددهم مائةُ ألفٍ أو يزيدون؛ ففي هذا استمرارُ الدعوةِ بعد التوبة، ورحمةُ الله بإرسالِ الرسل؛ فاعلم أنّ التائبَ يعود إلى عمله وطاعته، فلا تجعل زلّتك تقعدك عن الطاعة، بل تب وعد إلى دعوتك وعملك، فالتوبةُ تفتح بابَ العملِ من جديد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العودةُ إلى الطاعةِ والعملِ بعد التوبةِ من الزلّة."},"action":{"text":"اعلم أنّ الله بعد أن تاب على يونسَ وعافاه، أرسله إلى قومه — أو إلى قومٍ آخرين — وعددهم مائةُ ألفٍ أو يزيدون «وأرسلناه إلى مائة ألف أو يزيدون»؛ ففي هذا أنّ التائبَ يعود إلى عمله وطاعتِه ودعوتِه بعد توبته؛ فلا تجعل زلّتك أو ذنبك يقعدك عن الطاعةِ والعمل، ويقنّطك من العودةِ إلى الخير؛ بل تب إلى الله، وعد إلى طاعتك وعملك ودعوتك بنشاطٍ وعزم؛ فالتوبةُ تفتح للعبدِ بابَ العملِ الصالحِ من جديد؛ فما جعل الله التوبةَ إلا ليعود العبدُ إلى ربه وعمله؛ فمن أذنب ثم تاب فكأن لم يذنب؛ فلا تيأس من روحِ الله، ولا تدع الذنبَ يحبطك ويقعدك؛ فبادر بالتوبةِ ثم بالعملِ الصالح؛ فالتوّابون العاملون أحبُّ إلى الله؛ فاجعل من كلِّ توبةٍ بدايةً جديدةً للعملِ والطاعة؛ فالله يفرح بتوبةِ عبده ويعيده إلى ميدانِ العمل؛ فتب وأنب واعمل، ولا تقعد بك زلّةٌ عن طاعةِ ربك."}},{"n":148,"reflection":{"text":"«فآمنوا فمتعناهم إلى حين» — فآمن قومُ يونسَ لمّا رأوا العذابَ أو دعاهم، فمتّعناهم بالحياةِ إلى أجلٍ مسمّى؛ ففي هذا ثمرةُ الإيمانِ في رفعِ العذابِ وحصولِ النعمة؛ فاعلم أنّ الإيمانَ يرفع العذابَ ويجلب النعمة، فبادر بالإيمانِ والتوبةِ قبل نزولِ العذاب، فقومُ يونسَ آمنوا فرفع الله عنهم، وهم الأمّةُ الوحيدةُ التي نفعها إيمانُها عند رؤيةِ العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمانِ والتوبة، فالإيمانُ يرفعُ العذابَ ويجلبُ النعمة."},"action":{"text":"اعلم أنّ قومَ يونسَ آمنوا وتابوا لمّا أظلّهم العذاب، فرفعه الله عنهم ومتّعهم بالحياةِ إلى أجلهم المسمّى «فآمنوا فمتعناهم إلى حين»؛ فهم الأمّةُ الوحيدةُ التي نفعها إيمانُها عند رؤيةِ بواردِ العذاب، رحمةً من الله بهم؛ ففي هذا أنّ الإيمانَ والتوبةَ يرفعان العذابَ ويجلبان النعمةَ والرحمة؛ فبادر بالإيمانِ والتوبةِ إلى الله قبل نزولِ العذاب، ولا تؤخّرهما إلى وقتٍ لا ينفع فيه الإيمان؛ فالتوبةُ تُقبَل ما لم يعاين العبدُ العذابَ أو تبلغ الروحُ الحلقوم؛ فسارع إلى الله بالإيمانِ والتوبةِ والإنابة؛ فمن آمن وتاب رفع الله عنه، وبدّل سيّئاته حسنات، ومتّعه بحياةٍ طيّبة؛ فلا تسوّف بالتوبة؛ فاجعل من قصّةِ قومِ يونسَ حافزًا للمبادرةِ بالإيمانِ والتوبةِ قبل فواتِ الأوان؛ فالإيمانُ الصادقُ في وقتِ القبولِ يجلب رحمةَ الله ويرفع نقمته."}}]},{"title":"إبطالُ نسبةِ البناتِ والولدِ إلى الله، وتنزيهُه وإفحامُ المفترين","range":[149,160],"theme":"مطالبةُ المشركين بالحجّةِ على زعمهم أنّ الملائكةَ بناتُ الله، وبيانُ تناقضهم وحكمهم بلا علمٍ ولا سلطان، وأنّ نسبةَ الولدِ إلى الله من أعظمِ الإفكِ والكذب، وتنزيهُ الله عمّا يصفون، واستثناءُ المخلصين الذين لا يصفونه إلا بالحق","verses":[{"n":149,"reflection":{"text":"«فاستفتهم ألربك البنات ولهم البنون» — فاسأل هؤلاء المشركين موبّخًا: ألربّك البناتُ اللاتي تكرهونها، ولكم البنون؟ ففي هذا إبطالُ زعمهم أنّ الملائكةَ بناتُ الله؛ فتأمّل تناقضَ المشركين: ينسبون لله ما يكرهون لأنفسهم، فنزّه الله عن كلِّ نقص، ولا تنسب إليه ما لا يليق بجلاله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن كلِّ نقصٍ ونسبةِ ما لا يليق به."},"action":{"text":"تأمّل كيف أمر الله نبيَّه أن يسأل المشركين موبّخًا مبطلًا لزعمهم أنّ الملائكةَ بناتُ الله: ألربّك البناتُ اللاتي تكرهونها وتئدونها، ولكم البنون الذين تحبّونها؟ «فاستفتهم ألربك البنات ولهم البنون»؛ فانظر إلى تناقضِ المشركين وسفهِ عقولهم: ينسبون إلى الله ما يكرهونه ويأنفون منه لأنفسهم؛ فنزّه الله عن كلِّ نقصٍ وعيبٍ وحاجة؛ فالله الغنيُّ الصمدُ الذي لم يلد ولم يولد؛ فلا تنسب إلى الله ما لا يليق بجلالِه وكماله من ولدٍ أو صاحبةٍ أو شريك؛ فهو المنزّهُ عن مشابهةِ خلقه؛ فاعرف ربك بأسمائه الحسنى وصفاته العلى، ونزّهه عن كلِّ ما نسبه إليه الجاهلون والمشركون؛ فسبحانه عمّا يقولون علوًّا كبيرًا؛ فاجعل معرفتك بالله قائمةً على التنزيهِ والتعظيم؛ فمن عرف الله نزّهه عن كلِّ نقص، وأثبت له كلَّ كمال؛ فالله ليس كمثلِه شيء، وهو السميعُ البصير."}},{"n":150,"reflection":{"text":"«أم خلقنا الملائكة إناثا وهم شاهدون» — أم شهدوا خلقَ الملائكةِ فرأوهم إناثًا حتى يحكموا بذلك؟ ففي هذا إبطالُ حكمهم على الغيبِ بلا علم؛ فاعلم أنّ الحكمَ على الغيبِ بلا علمٍ باطل، فلا تقل على الله بلا علم، ولا تحكم في أمرِ الدينِ بالظنِّ والهوى، بل قف عند حدودِ العلمِ والوحي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ القولِ على الله والحكمِ في الغيبِ بلا علم."},"action":{"text":"تأمّل كيف أبطل الله حكمَ المشركين بأنّ الملائكةَ إناثٌ بقوله: أم شهدوا خلقَ الملائكةِ فرأوهم إناثًا حتى يحكموا بهذا؟ «أم خلقنا الملائكة إناثا وهم شاهدون»؛ فهم لم يشهدوا خلقهم، فكيف يحكمون على الغيبِ بلا علمٍ ولا دليل؟ ففي هذا إبطالُ الحكمِ على الغيبِ والقولِ على الله بلا علم؛ فاعلم أنّ الحكمَ في أمورِ الغيبِ والدينِ بلا علمٍ باطلٌ محرّم؛ فلا تقل على الله بلا علم؛ فالقولُ على الله بلا علمٍ من أعظمِ المحرّمات، قرنه الله بالشرك؛ فلا تحكم في أمرِ الدينِ بالظنِّ والهوى والتخرّص؛ بل قف عند حدودِ العلمِ والوحي؛ فما علمت فقل، وما جهلت فقل الله أعلم؛ فلا تخض فيما لا علمَ لك به؛ فاحفظ لسانك عن القولِ على الله وفي دينِه بلا برهان؛ فمن قال في الدينِ برأيه وهواه ضلّ وأضلّ؛ فاجعل مصدرَ حكمك في الدينِ الوحيَ لا الظنَّ؛ فالتثبّتُ في القولِ على الله وفي دينه من علاماتِ العلمِ والورع."}},{"n":151,"reflection":{"text":"«ألا إنهم من إفكهم ليقولون» — ألا إنّ هؤلاء المشركين من كذبهم المختلَقِ ليقولون قولًا عظيمًا؛ ففي هذا التمهيدُ لبيانِ أعظمِ إفكهم؛ فاحذر الكذبَ والافتراء، لا سيّما على الله، فأعظمُ الكذبِ الكذبُ على الله، فطهّر لسانك من الكذبِ كلِّه، وأعظمه ما كان على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكذبِ والافتراء، لا سيّما على الله."},"action":{"text":"اعلم أنّ الله نبّه على أنّ المشركين من كذبهم المختلَقِ وإفكهم يقولون قولًا عظيمًا في حقِّ الله «ألا إنهم من إفكهم ليقولون»؛ فمصدرُ أقوالهم الباطلةِ في حقِّ الله هو الإفكُ والكذبُ المفترى؛ فاحذر الكذبَ والافتراءَ بكلِّ صورِه؛ فالكذبُ رأسُ الرذائل، وبابُ الشرور؛ وأعظمُ الكذبِ وأخطره الكذبُ على الله ورسوله وفي دينه؛ فمن أعظمِ الظلمِ افتراءُ الكذبِ على الله بنسبةِ ما لا يليق به، أو تحليلِ ما حرّم، أو تحريمِ ما أحلّ، أو القولِ عليه بلا علم؛ فطهّر لسانك من الكذبِ كلِّه صغيرِه وكبيره؛ فالصدقُ يهدي إلى البرّ، والكذبُ يهدي إلى الفجور؛ فالزم الصدقَ في القولِ والعمل؛ واحذر أشدَّ الحذرِ الكذبَ على الله وفي دينه؛ فمن كذب على الله فقد افترى إثمًا عظيمًا؛ فاجعل لسانك صادقًا، وقلبك من الإفكِ سليمًا؛ فالصادقون هم الناجون، والكاذبون المفترون هم الخاسرون."}},{"n":152,"reflection":{"text":"«ولد الله وإنهم لكاذبون» — قولهم: ولد الله (نسبةُ الولدِ إليه سبحانه)، وإنهم لكاذبون في ذلك؛ ففي هذا بيانُ عظمِ فريتهم على الله وتنزيهُه؛ فنزّه الله عن الولدِ والصاحبة، فهو الأحدُ الصمدُ الذي لم يلد ولم يولد، فأعظم الله في قلبك، ونزّهه عن كلِّ ما لا يليق بكماله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد، وتعظيمُه في القلب."},"action":{"text":"اعلم أنّ أعظمَ إفكِ المشركين وكذبهم قولهم: «ولد الله»، ونسبتهم الولدَ إليه سبحانه بزعمهم أنّ الملائكةَ بناتُ الله، وإنهم لكاذبون في ذلك «ولد الله وإنهم لكاذبون»؛ فهذه من أعظمِ الفِرى على الله؛ فقد كادت السماواتُ يتفطّرن والأرضُ تنشقّ من هذه الكلمة؛ فنزّه الله عن الولدِ والصاحبةِ والشريك؛ فهو الله الأحدُ الصمدُ الذي لم يلد ولم يولد ولم يكن له كفوًا أحد؛ فكيف يكون له ولدٌ وهو خالقُ كلِّ شيء؟ فالولدُ يكون عن حاجةٍ ومشابهة، والله الغنيُّ المنزّهُ عن مشابهةِ خلقه؛ فأعظم الله في قلبك، ونزّهه عن كلِّ ما لا يليق بكماله وجلاله؛ فاجعل قلبك ممتلئًا بتعظيمِ الله وتنزيهه؛ فمن عرف الله عظّمه ونزّهه؛ فسبحان الله عمّا يشركون، وتعالى عمّا يقولون علوًّا كبيرًا؛ فنزّه ربك، وعظّمه، وأخلص له العبادةَ والتوحيد."}},{"n":153,"reflection":{"text":"«أصطفى البنات على البنين» — أاختار الله البناتِ على البنين (على زعمهم الفاسد)؟ ففي هذا إنكارُ زعمهم واستبعادُه؛ فتأمّل بطلانَ ما ينسبه الجاهلون إلى الله ممّا يناقض حكمته وكماله، فنزّه الله عن كلِّ نقص، ولا تحكم عليه إلا بما يليق بجلاله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استنكارُ نسبةِ النقصِ إلى الله، وتنزيهُه عمّا لا يليق."},"action":{"text":"تأمّل كيف أنكر الله على المشركين زعمهم منكرًا مستبعدًا: أاختار الله البناتِ على البنين حتى تنسبوا إليه البناتِ اللاتي تكرهونها لأنفسكم؟ «أصطفى البنات على البنين»؛ فهذا زعمٌ باطلٌ يناقض كمالَ الله وحكمته وغناه؛ فتأمّل بطلانَ ما ينسبه الجاهلون والمشركون إلى الله ممّا يناقض حكمته وكماله وغناه؛ فالله منزّهٌ عن الولدِ أصلًا، ذكرًا كان أو أنثى؛ فكيف يُنسَب إليه ما هو أنقصُ في زعمهم؟ فنزّه الله عن كلِّ نقصٍ وعيب؛ فلا تحكم على الله إلا بما يليق بجلالِه وكماله؛ فاعرفه بصفاتِ الكمالِ ونعوتِ الجلال؛ ونزّهه عن كلِّ ما يناقض ذلك؛ فالله له المثلُ الأعلى في السماواتِ والأرض؛ فأثبت له الكمالَ المطلق، ونزّهه عن كلِّ نقص؛ فمن عرف عظمةَ الله وكماله عرف بطلانَ ما ينسبه إليه المفترون؛ فعظّم ربك، ونزّهه، وأخلص له التوحيد."}},{"n":154,"reflection":{"text":"«ما لكم كيف تحكمون» — ما لكم أيها المشركون كيف تحكمون هذا الحكمَ الجائرَ الباطل؟ ففي هذا توبيخُهم على فسادِ حكمهم؛ فحاسب نفسك في أحكامك: هل هي موافقةٌ للحقِّ والعدلِ والوحي؟ فلا تحكم بالهوى والجهل، بل زِن أحكامك بميزانِ الحقِّ والوحي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفسِ في الأحكام، وزنُها بميزانِ الحقِّ والوحي."},"action":{"text":"تأمّل توبيخَ الله للمشركين على فسادِ حكمهم وسوءِ نظرهم: ما لكم كيف تحكمون هذا الحكمَ الجائرَ الباطلَ الذي تنسبون به إلى الله ما لا يليق به؟ «ما لكم كيف تحكمون»؛ فهو استفهامُ إنكارٍ وتوبيخٍ على حكمهم الفاسد؛ فحاسب نفسك في أحكامك وأقوالك: هل هي موافقةٌ للحقِّ والعدلِ والوحي؟ أم هي صادرةٌ عن هوًى وجهلٍ وتخرّص؟ فلا تحكم بالهوى والجهلِ والظنّ؛ بل زِن أحكامك وآراءك بميزانِ الحقِّ والوحيِ والعدل؛ فكم من حكمٍ جائرٍ مصدرُه الهوى والجهل؛ فتثبّت في أحكامك، ولا تقل إلا حقًّا، ولا تحكم إلا عدلًا؛ فاجعل الوحيَ حاكمًا على عقلك وهواك؛ فمن حكّم الهوى ضلّ، ومن حكّم الوحيَ اهتدى؛ فراجع أحكامك وتصوّراتك على ميزانِ الشرع؛ فالعقلُ السليمُ والحكمُ الرشيدُ ما وافق الوحيَ والعدل؛ فاحذر الأحكامَ الجائرةَ الصادرةَ عن الهوى؛ والزم الحقَّ والعدلَ في كلِّ حكمٍ تحكمه."}},{"n":155,"reflection":{"text":"«أفلا تذكرون» — أفلا تتذكّرون فتعلمون بطلانَ ما تقولون؟ ففي هذا الحثُّ على التذكّرِ والتدبّر؛ فتذكّر وتدبّر لتعرف الحقَّ من الباطل، فالتذكّرُ سبيلُ الهداية، فأعمل فكرك وتذكّر، فمن تذكّر عرف الحقَّ ورجع إليه، ومن غفل تمادى في الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكّرُ والتدبّرُ لمعرفةِ الحقِّ والرجوعِ إليه."},"action":{"text":"اعلم أنّ الله حثّ المشركين على التذكّرِ والتدبّر ليعلموا بطلانَ ما يقولون: أفلا تتذكّرون فتنزّهون الله عمّا نسبتم إليه؟ «أفلا تذكرون»؛ فالتذكّرُ والتدبّرُ سبيلُ معرفةِ الحقِّ والرجوعِ إليه؛ فأعمل فكرك وتذكّر؛ فبالتذكّرِ تعرف الحقَّ من الباطل، والهدى من الضلال؛ فمن تذكّر وتدبّر عرف الحقَّ ورجع إليه، ومن غفل وأعرض تمادى في الباطل؛ فأكثر من التذكّرِ والتفكّرِ في آياتِ الله وأمرِه ونهيه؛ فإنما يتذكّر أولو الألباب؛ فاجعل قلبك متذكّرًا متدبّرًا، لا غافلًا لاهيًا؛ فالذكرى تنفع المؤمنين؛ فتذكّر عظمةَ الله وكماله لتنزّهه، وتذكّر الموتَ والآخرةَ لتستعدّ، وتذكّر نعمَ الله لتشكرها، وتذكّر وعده ووعيده لترجو وتخاف؛ فالتذكّرُ حياةُ القلب؛ فمن عطّل التذكّرَ قسا قلبه وضلّ؛ فاجعل التذكّرَ والتدبّرَ دأبك؛ فبهما تحيا القلوبُ وتهتدي النفوس."}},{"n":156,"reflection":{"text":"«أم لكم سلطان مبين» — أم لكم حجّةٌ واضحةٌ وبرهانٌ بيّنٌ على ما تقولون؟ ففي هذا مطالبتهم بالدليلِ على دعواهم؛ فاعلم أنّ الدعوى بلا دليلٍ باطلة، فلا تقبل قولًا في الدينِ بلا برهان، ولا تعتقد إلا ما قام عليه الدليل، فالحقُّ ما دلّ عليه البرهان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مطالبةُ الدعوى بالدليل، وعدمُ قبولِ القولِ بلا برهان."},"action":{"text":"تأمّل كيف طالب الله المشركين بالحجّةِ والبرهانِ على دعواهم: أم لكم حجّةٌ واضحةٌ وسلطانٌ بيّنٌ من كتابٍ أو وحيٍ على ما تقولون من نسبةِ الولدِ إلى الله؟ «أم لكم سلطان مبين»؛ فهم لا حجّةَ لهم ولا برهان، وإنما هو الظنُّ والهوى والتقليد؛ فاعلم أنّ الدعوى بلا دليلٍ باطلةٌ مردودة؛ فلا تقبل قولًا في الدينِ أو العقيدةِ بلا برهانٍ ودليل؛ ولا تعتقد إلا ما قام عليه الدليلُ من الوحيِ الصحيح؛ فالحقُّ ما دلّ عليه البرهان، والباطلُ ما خالفه؛ فطالب كلَّ مدّعٍ بدليله «قل هاتوا برهانكم إن كنتم صادقين»؛ فلا تنقد وراء الدعاوى بلا بيّنة؛ فاجعل بناءَ عقيدتك وأحكامك على البرهانِ والدليل، لا على الظنِّ والتقليدِ الأعمى؛ فمن بنى معتقده على دليلٍ ثبت، ومن بناه على ظنٍّ وهوًى اضطرب؛ فالزم الدليلَ في اعتقادك وقولك؛ فالعلمُ ما قام عليه برهان؛ فلا تتّبع إلا ما قامت عليه الحجّةُ من الوحيِ والعقلِ الصريح."}},{"n":157,"reflection":{"text":"«فأتوا بكتابكم إن كنتم صادقين» — فأتوا بكتابٍ من الله ينطق بما تدّعون إن كنتم صادقين؛ ففي هذا تعجيزهم وإفحامهم بطلبِ الدليلِ النقلي؛ فاعلم أنّ الحقَّ في الدينِ مرجعه الوحي، فلا تتّبع في دينك إلا ما جاء في كتابِ الله وسنّةِ رسولِه، فمن لا دليلَ عنده من الوحي فدعواه باطلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ردُّ أمورِ الدينِ إلى الوحي، وعدمُ اتّباعِ ما لا دليلَ عليه."},"action":{"text":"تأمّل كيف أفحم الله المشركين وأعجزهم بطلبِ الدليلِ النقلي: فأتوا بكتابٍ من الله منزّلٍ ينطق بصحّةِ ما تدّعون من نسبةِ الولدِ إليه، إن كنتم صادقين «فأتوا بكتابكم إن كنتم صادقين»؛ فهم لا كتابَ عندهم ولا وحيَ يصدّق دعواهم؛ فاعلم أنّ الحقَّ في الدينِ والعقيدةِ مرجعه الوحيُ المنزّل؛ فلا تتّبع في دينك إلا ما جاء في كتابِ الله وسنّةِ رسولِه ﷺ؛ فمن لا دليلَ عنده من الوحيِ على قوله فدعواه باطلةٌ مردودة؛ فردَّ أمورَ الدينِ والاعتقادِ إلى الوحي؛ فما وافق الكتابَ والسنّةَ قُبِل، وما خالفهما رُدّ؛ فلا تحدث في الدينِ ما ليس منه؛ فكلُّ بدعةٍ ضلالة؛ فالزم ما جاء عن الله ورسوله، ودع ما سواه؛ فمن اتّبع الوحيَ اهتدى، ومن اتّبع الهوى والظنَّ ضلّ؛ فاجعل الكتابَ والسنّةَ مصدرَ دينك وعقيدتك وعملك؛ فالنجاةُ في اتّباعِ الوحي، والهلاكُ في اتّباعِ ما لا دليلَ عليه؛ فتمسّك بالوحيِ المعصوم، ودع أقوالَ المبطلين المتخرّصين."}},{"n":158,"reflection":{"text":"«وجعلوا بينه وبين الجنة نسبا ولقد علمت الجنة إنهم لمحضرون» — وجعل المشركون بين الله والجنِّ نسبًا وقرابة، ولقد علمت الجنُّ أنهم محضرون في العذاب؛ ففي هذا إبطالُ نسبةِ القرابةِ بين الله وخلقه؛ فنزّه الله عن مشابهةِ خلقه ومناسبتهم، فهو الخالقُ وكلُّ ما سواه مخلوقٌ عبدٌ له، فأعظم الله عن أن يكون له نسبٌ بأحدٍ من خلقه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن مناسبةِ خلقه، وإفرادُه بالخالقية."},"action":{"text":"اعلم أنّ المشركين جعلوا بين الله والجنِّ (أو الملائكة) نسبًا وقرابة، بزعمهم أنّ الملائكةَ بناتُ الله من سرواتِ الجن، ولقد علمت الملائكةُ والجنُّ أنّ قائلي هذا الإفكِ محضرون في العذاب «وجعلوا بينه وبين الجنة نسبا ولقد علمت الجنة إنهم لمحضرون»؛ ففي هذا إبطالُ نسبةِ القرابةِ بين الله وخلقه؛ فنزّه الله عن مشابهةِ خلقه ومناسبتهم؛ فهو الخالقُ الأحد، وكلُّ ما سواه مخلوقٌ عبدٌ فقيرٌ إليه؛ فكيف يكون بين الخالقِ والمخلوقِ نسبٌ وقرابة؟ فأعظم الله في قلبك عن أن يكون له نسبٌ بأحدٍ من خلقه، أو شبيهٌ أو مثيل؛ فهو الغنيُّ الصمد، وكلُّ الخلقِ عبيده؛ إن كلُّ من في السماواتِ والأرضِ إلا آتي الرحمنِ عبدًا؛ فأفرد الله بالخالقيةِ والربوبيةِ والألوهية؛ ونزّهه عن كلِّ نقصٍ ومشابهةٍ ومناسبة؛ فسبحانه وتعالى عمّا يقولون علوًّا كبيرًا؛ فعظّم ربك، ونزّهه، وأخلص له العبودية."}},{"n":159,"reflection":{"text":"«سبحان الله عما يصفون» — تنزيهًا لله وتقديسًا له عمّا يصفه به المشركون من الولدِ والشريكِ والنقص؛ ففي هذا تعليمُ التنزيهِ عند سماعِ الباطلِ في حقِّ الله؛ فسبّح الله ونزّهه إذا سمعت باطلًا في حقّه، فالتنزيهُ واجبُ المؤمنِ عند سماعِ ما لا يليق بالله، فاجعل «سبحان الله» جوابك لكلِّ باطلٍ يُقال في حقِّ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عند سماعِ الباطلِ في حقّه."},"action":{"text":"تأمّل كيف نزّه الله نفسه عمّا وصفه به المشركون من الولدِ والشريكِ والنقص: سبحان الله وتقديسًا له عن كلِّ ما يصفونه به ممّا لا يليق بجلالِه وكماله «سبحان الله عما يصفون»؛ ففي هذا تعليمٌ للمؤمنِ أن ينزّه الله ويسبّحه عند سماعِ الباطلِ في حقّه؛ فسبّح الله ونزّهه إذا سمعت باطلًا أو نقصًا يُنسَب إليه سبحانه؛ فالتنزيهُ والتسبيحُ واجبُ المؤمنِ عند سماعِ ما لا يليق بالله؛ فاجعل «سبحان الله» جوابك ووردك عند كلِّ باطلٍ يُقال في حقِّ الله؛ فبالتسبيحِ تبرأ إلى الله ممّا نسبه إليه المبطلون؛ فنزّه ربك عن كلِّ نقصٍ وعيبٍ وشريكٍ وولد؛ فهو الكاملُ في ذاته وأسمائه وصفاته وأفعاله؛ فأكثر من تسبيحِ الله وتنزيهه؛ فالتسبيحُ تعظيمٌ لله وتبرّؤٌ من الباطل؛ فاجعل لسانك رطبًا بتسبيحِ الله وتنزيهه؛ فسبحان الله وبحمده، سبحان الله العظيم؛ فمن عظّم الله نزّهه عمّا لا يليق به، وسبّحه في كلِّ حين."}},{"n":160,"reflection":{"text":"«إلا عباد الله المخلصين» — لكن عبادَ الله المخلصين لا يصفون الله إلا بما يليق بجلاله؛ ففي هذا مدحُ المخلصين وتنزيهُهم عن وصفِ الله بالباطل؛ فكن من عبادِ الله المخلصين الذين ينزّهون الله ويصفونه بما يليق به، فالمخلصون هم أهلُ التوحيدِ الخالصِ والتنزيهِ الصحيح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالمخلصين في تنزيهِ الله ووصفِه بما يليق."},"action":{"text":"اعلم أنّ الله استثنى عبادَه المخلصين الذين لا يصفون الله إلا بما يليق بجلالِه وكماله، ولا ينسبون إليه ما نسبه المشركون من النقص «إلا عباد الله المخلصين»؛ ففي هذا مدحُ المخلصين وتنزيهُهم عن وصفِ الله بالباطل؛ فكن من عبادِ الله المخلصين الذين ينزّهون الله ويصفونه بأسمائه الحسنى وصفاته العلى؛ فالمخلصون هم أهلُ التوحيدِ الخالصِ والتنزيهِ الصحيح؛ فأخلص عبادتك لله، وحقّق التوحيد، ونزّه الله عن كلِّ ما لا يليق به؛ فمن أخلص لله عرفه حقَّ المعرفةِ ووصفه بما يليق به؛ فاجعل معرفتك بالله ووصفك له تابعًا للوحي، مقتديًا بالمخلصين من عبادِ الله؛ فهم الذين أخلصهم الله واصطفاهم؛ فاسلك سبيلهم في التوحيدِ والإخلاصِ والتنزيه؛ فبالإخلاصِ تصفو معرفتك بالله، وتسلم عقيدتك من شوائبِ الشركِ والتشبيهِ والتعطيل؛ فكن من المخلصين، تكن من الناجين الموحّدين."}}]},{"title":"عجزُ المضلّين عن الفتنة، وصفوفُ الملائكةِ وتسبيحُهم، وردُّ تمنّي المشركين","range":[161,170],"theme":"أنّ المشركين ومعبوداتهم لا يفتنون عن الله إلا من قُدِّر له الجحيم، واعترافُ الملائكةِ بمقاماتهم المعلومةِ وأنهم الصافّون المسبّحون، وحكايةُ تمنّي كفّارِ قريشٍ لو جاءهم ذكرٌ ليكونوا مخلصين، ثم كفرُهم بالقرآنِ لمّا جاءهم ووعيدُهم","verses":[{"n":161,"reflection":{"text":"«فإنكم وما تعبدون» — فإنكم أيها المشركون وما تعبدون من دونِ الله؛ ففي هذا خطابُ المشركين ومعبوداتهم؛ فاعلم أنّ المشركين ومعبوداتهم لا يقدرون على إضلالِ أحدٍ كتب الله له الهداية، فتوكّل على الله واثبت، فلا يضرّك كيدُ المضلّين إن اعتصمت بالله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتصامُ بالله والثقةُ بأنّ المضلّين لا يضرّون المهتدي."},"action":{"text":"اعلم أنّ الله خاطب المشركين ومعبوداتهم مبيّنًا عجزهم عن الإضلال: فإنكم أيها المشركون وما تعبدون من دونِ الله «فإنكم وما تعبدون»؛ فهذا تمهيدٌ لبيانِ أنهم لا يقدرون على فتنةِ أحدٍ وإضلالِه إلا من قدّر الله ضلاله؛ فاعلم أنّ المضلّين وشياطينهم ومعبوداتهم لا يقدرون على إضلالِ أحدٍ كتب الله له الهداية والاعتصامَ به؛ فتوكّل على الله واعتصم به واثبت على الحق؛ فلا يضرّك كيدُ المضلّين والمفتنين إن اعتصمت بالله وتوكّلت عليه؛ فمن اعتصم بالله فقد هُدي إلى صراطٍ مستقيم؛ فالجأ إلى الله، واستعصم به من كلِّ فتنةٍ ومضلّة؛ فحفظُ الله لمن اعتصم به لا يخيب؛ فاجعل توكّلك واعتصامك بالله وحده؛ فمن كان الله حافظه وهاديه لم يضرّه من أراد فتنته وإضلاله؛ فاثبت على الحقِّ متوكّلًا على الله، ولا تخف كيدَ المضلّين؛ فإنّ كيدَ الشيطانِ كان ضعيفًا."}},{"n":162,"reflection":{"text":"«ما أنتم عليه بفاتنين» — ما أنتم أيها المشركون بمضلّين عن الله أحدًا؛ ففي هذا نفيُ قدرةِ المضلّين على فتنةِ من عصمه الله؛ فاعلم أنّ الفتنةَ والإضلالَ لا يقعان إلا بإذنِ الله وقدره، فمن عصمه الله لم يضلّه أحد، فاعتصم بالله يعصمك من فتنةِ المضلّين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ العصمةَ من الله، والاعتصامُ به من الفتنة."},"action":{"text":"اعلم أنّ الله نفى عن المشركين ومعبوداتهم القدرةَ على إضلالِ أحدٍ وفتنته: ما أنتم أيها المشركون بمضلّين عن دينِ الله أحدًا «ما أنتم عليه بفاتنين»؛ إلا من سبق في علمِ الله أنه من أهلِ النار باختيارِه الضلال؛ فاعلم أنّ الفتنةَ والإضلالَ لا يقعان إلا بإذنِ الله وقدره وحكمته؛ فمن عصمه الله وحفظه لم يقدر أحدٌ على إضلاله وفتنته؛ فاعتصم بالله يعصمك من فتنةِ المضلّين وكيدِ الشياطين؛ فالعصمةُ والحفظُ بيدِ الله وحده؛ فالجأ إليه، واسأله الثباتَ على الحقِّ والعصمةَ من الفتن؛ فمن توكّل على الله كفاه وعصمه؛ فلا تخف على نفسك من المضلّين إن اعتصمت بالله وأخذت بأسبابِ الثبات؛ فاسأل الله دائمًا: يا مقلّبَ القلوبِ ثبّت قلبي على دينك؛ فبالاعتصامِ بالله والتوكّلِ عليه تسلم من كلِّ فتنةٍ وإضلال؛ فالعاصمُ هو الله، فاعتصم به وحده."}},{"n":163,"reflection":{"text":"«إلا من هو صال الجحيم» — إلا من هو داخلٌ النارَ ومقدَّرٌ له الشقاء (فهذا الذي تضلّونه بإذنِ الله)؛ ففي هذا أنّ الإضلالَ لا يقع إلا على من اختار الضلالَ وسبق شقاؤه؛ فاحذر أن تكون ممّن يتّبع المضلّين فتصير إلى النار، بل اعتصم بالله واتّبع الحقّ، فالنجاةُ في الاعتصامِ بالله واتّباعِ الحق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اتّباعِ المضلّين، والاعتصامُ بالله واتّباعُ الحق."},"action":{"text":"اعلم أنّ المضلّين لا يقدرون على فتنةِ أحدٍ إلا من هو داخلٌ النارَ لا محالة، ممّن اختار الضلالَ وأعرض عن الهدى فسبق في علمِ الله شقاؤه «إلا من هو صال الجحيم»؛ ففي هذا أنّ الإضلالَ لا يقع إلا على من اختار الضلالَ بنفسه، وأعرض عن الحقِّ بعد وضوحه؛ فاحذر أن تكون ممّن يتّبع المضلّين والمفتنين فتصير إلى النار؛ بل اعتصم بالله، واتّبع الحقَّ الذي جاء به الرسل؛ فالنجاةُ في الاعتصامِ بالله واتّباعِ الحقِّ ولزومِ الهدى؛ فمن اتّبع الهدى فلا يضلّ ولا يشقى، ومن أعرض عن ذكرِ الله فإنّ له معيشةً ضنكًا؛ فاختر لنفسك سبيلَ الهدى، واجتنب سبيلَ الضلال؛ فالله لم يظلم أحدًا، وإنما العبدُ يختار لنفسه؛ فبادر باتّباعِ الحقِّ والاعتصامِ بالله؛ فمن أراد الهدى واعتصم بالله هداه، ومن آثر الضلالَ واتّبع المضلّين هلك؛ فاجعل نجاتك في لزومِ الحقِّ والاعتصامِ بالله."}},{"n":164,"reflection":{"text":"«وما منا إلا له مقام معلوم» — وما منا (معشرَ الملائكة) إلا له مقامٌ ومرتبةٌ معلومةٌ في العبادةِ لا يتعدّاها؛ ففي هذا تسبيحُ الملائكةِ ومعرفتهم قدرهم؛ فاعرف قدرك في العبوديةِ لله، والزم مقامك في الطاعة، فالملائكةُ يلزمون مقاماتهم في العبادة، فاعبد الله في المقامِ الذي أقامك فيه بإتقانٍ وثبات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ العبدِ قدرَه، ولزومُ مقامِه في عبادةِ الله."},"action":{"text":"اعلم أنّ الملائكةَ قالوا معترفين بعبوديتهم وقدرهم: وما منا إلا له مقامٌ ومرتبةٌ معلومةٌ في العبادةِ والطاعةِ لا يتعدّاها ولا يتجاوزها «وما منا إلا له مقام معلوم»؛ فالملائكةُ يعرفون قدرهم، ويلزمون مقاماتهم في عبادةِ الله وطاعته؛ فاعرف قدرك في العبوديةِ لله، والزم مقامك الذي أقامك الله فيه من الطاعةِ والعمل؛ فكما أنّ للملائكةِ مقاماتٍ معلومةً في العبادة، فلك مقامٌ في عبوديتك لله فالزمه بإتقانٍ وثبات؛ فاعبد الله في موضعك ووظيفتك التي جعلك الله فيها؛ فكلٌّ ميسّرٌ لما خُلِق له؛ فاعرف نفسك، والزم عبوديتك، وأدِّ ما عليك من حقوقِ الله بإحسانٍ وإتقان؛ فالسعادةُ في معرفةِ العبدِ قدرَه ولزومِه عبوديته؛ فلا تتعدَّ حدودَ عبوديتك، ولا تقصّر فيها؛ بل قم بها كما أُمِرت، مقتديًا بالملائكةِ في لزومِ مقامِ الطاعةِ والعبادة؛ فمن عرف قدره ولزم عبوديته سعد."}},{"n":165,"reflection":{"text":"«وإنا لنحن الصافون» — وإنا (معشرَ الملائكة) لنحن الصافّون صفوفًا في عبادةِ الله؛ ففي هذا شرفُ الصفوفِ في العبادة؛ فاقتدِ بالملائكةِ في إقامةِ الصفوفِ وإتمامها في الصلاة، فالتراصُّ في الصفوفِ من عبادةِ الملائكة، فأتمّ صفوفك وسدّ الفُرَجَ اقتداءً بهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالملائكةِ في إقامةِ الصفوفِ وإتمامها."},"action":{"text":"اعلم أنّ الملائكةَ وصفوا أنفسهم بأنهم الصافّون صفوفًا في عبادةِ الله وطاعته «وإنا لنحن الصافون»؛ ففي هذا شرفُ إقامةِ الصفوفِ في العبادة؛ فاقتدِ بالملائكةِ في إقامةِ الصفوفِ وإتمامها وتسويتها في الصلاة؛ فقد أمرنا النبيُّ ﷺ بتسويةِ الصفوفِ وسدِّ الفُرَجِ والتراصِّ فيها، وأخبر أنّ ذلك من تمامِ الصلاة؛ وأخبر أنّ الملائكةَ تصفّ عند ربها كذلك؛ فأتمّ صفوفك في الصلاة، وسدّ الفُرَج، وحاذِ بين المناكبِ والأقدام، وتراصّ مع إخوانك؛ فمن وصل صفًّا وصله الله، ومن قطعه قطعه الله؛ فالتراصُّ في الصفوفِ من عبادةِ الملائكةِ ومن كمالِ الصلاة؛ فاحرص على الصفِّ الأول، وعلى إتمامِ الصفوفِ الأولى فالأولى؛ فاقتدِ بالملائكةِ في انتظامِ عبادتهم وإقامةِ صفوفهم؛ فبإتمامِ الصفوفِ تنال شرفَ الاقتداءِ بالملائكةِ وكمالَ الصلاة."}},{"n":166,"reflection":{"text":"«وإنا لنحن المسبحون» — وإنا (معشرَ الملائكة) لنحن المسبّحون المنزّهون لله عن كلِّ نقص؛ ففي هذا دوامُ تسبيحِ الملائكةِ لله؛ فاقتدِ بالملائكةِ في دوامِ التسبيحِ والتنزيهِ لله، فالتسبيحُ عبادةُ الملائكةِ الدائمة، فاعمر لسانك وقلبك بتسبيحِ الله وتنزيهِه في كلِّ حين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالملائكةِ في دوامِ تسبيحِ الله وتنزيهه."},"action":{"text":"اعلم أنّ الملائكةَ وصفوا أنفسهم بأنهم المسبّحون المنزّهون لله عن كلِّ نقصٍ وعيب، الدائمون على تسبيحه «وإنا لنحن المسبحون»؛ فهم يسبّحون الليلَ والنهارَ لا يفترون؛ فاقتدِ بالملائكةِ في دوامِ التسبيحِ والتنزيهِ لله؛ فالتسبيحُ عبادةُ الملائكةِ الدائمةُ التي لا يملّونها؛ فاعمر لسانك وقلبك بتسبيحِ الله وتنزيهِه في كلِّ حين؛ فأكثر من قولِ: سبحان الله، سبحان الله وبحمده، سبحان الله العظيم؛ فالتسبيحُ ثقيلٌ في الميزان، حبيبٌ إلى الرحمن؛ فكلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم؛ فاجعل التسبيحَ وردك الدائمَ في قيامك وقعودك وعلى جنبك؛ فبالتسبيحِ تقتدي بالملائكة، وتعظّم ربك، وتثقّل ميزانك؛ فلا يجفّ لسانك من تسبيحِ الله وتنزيهه؛ فالمسبّحون هم أهلُ المقاماتِ العليّةِ عند الله."}},{"n":167,"reflection":{"text":"«وإن كانوا ليقولون» — وإنّ كفّارَ قريشٍ كانوا قبل بعثةِ النبيِّ ليقولون متمنّين؛ ففي هذا حكايةُ تمنّيهم الذي خالفوه بعد وقوعه؛ فاحذر أن تتمنّى الخيرَ ثم تخالفه عند حصوله، فالعبرةُ بالعملِ لا بالتمنّي، فمن تمنّى الهدى ثم أعرض عنه عند مجيئه فقد خسر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مخالفةِ ما تمنّاه من الخيرِ عند حصوله."},"action":{"text":"اعلم أنّ كفّارَ قريشٍ كانوا قبل بعثةِ النبيِّ ﷺ يقولون متمنّين ومقسمين «وإن كانوا ليقولون»؛ يتمنّون لو جاءهم رسولٌ وكتابٌ ليكونوا أهدى من الأممِ السابقة؛ فلمّا جاءهم ما تمنّوا كفروا به وأعرضوا؛ فاحذر أن تتمنّى الخيرَ والهدى ثم تخالفه وتعرض عنه عند حصوله ومجيئه؛ فالعبرةُ بالعملِ والاستجابةِ عند حصولِ المطلوب، لا بمجرّدِ التمنّي والدعوى؛ فكم من متمنٍّ للهدى إذا جاءه أعرض عنه؛ وكم من متمنٍّ للخيرِ إذا حضره قصّر فيه؛ فمن تمنّى الطاعةَ فليعمل بها إذا قدر، ومن تمنّى الهدى فليتّبعه إذا جاءه؛ فلا تكن ممّن يتمنّى الخيرَ بلسانه ويخالفه بفعله؛ فالمؤمنُ الصادقُ يصدق تمنّيه بعمله؛ فإذا تمنّيت خيرًا فاعمل لتحصيله، وإذا جاءك ما تمنّيت من الطاعةِ فبادر إليه؛ فالتمنّي بلا عملٍ رأسُ مالِ المفاليس؛ فاجعل تمنّيك مقرونًا بالعملِ والصدق؛ فمن صدق في طلبِ الهدى هُدي، ومن كذب في تمنّيه خُذِل."}},{"n":168,"reflection":{"text":"«لو أن عندنا ذكرا من الأولين» — كانوا يقولون: لو أنّ عندنا كتابًا كالذي أُنزِل على الأوّلين؛ ففي هذا تمنّيهم الكتابَ الذي كفروا به لمّا جاءهم؛ فاعلم أنّ نعمةَ القرآنِ التي بين يديك تمنّاها الأوّلون، فاشكرها بالإيمانِ والعمل، ولا تكن كمن تمنّى النعمةَ ثم كفرها عند حصولها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ القرآنِ بالإيمانِ والعمل، لا كفرُها."},"action":{"text":"اعلم أنّ كفّارَ قريشٍ كانوا يتمنّون قبل البعثة: لو أنّ عندنا كتابًا وذكرًا من الله كالذي أُنزِل على الأممِ الأولين «لو أن عندنا ذكرا من الأولين»؛ فلمّا جاءهم أشرفُ الكتبِ وأتمُّها — القرآنُ — كفروا به وأعرضوا؛ فاعلم أنّ نعمةَ القرآنِ العظيمةَ التي بين يديك قد تمنّاها الأوّلون؛ فاشكر هذه النعمةَ بالإيمانِ به والعملِ بمقتضاه؛ فالقرآنُ أعظمُ نعمةٍ أنعم الله بها عليك؛ فلا تكن كمن تمنّى النعمةَ ثم كفرها وأعرض عنها عند حصولها؛ بل اقبل على القرآنِ تلاوةً وتدبّرًا وعملًا وتحكيمًا؛ فما قيمةُ نعمةٍ لا تُشكَر ولا يُنتفَع بها؟ فاجعل شكرك للقرآنِ بلزومِه والعملِ به؛ فكم من محرومٍ من هذه النعمةِ يتمنّاها؛ وأنت قد أوتيتها، فاحمد الله واعمل بها؛ فمن شكر نعمةَ القرآنِ بالعملِ زاده الله هدًى، ومن كفرها بالإعراضِ خسر؛ فاشكر نعمةَ القرآنِ بالإقبالِ عليه والاهتداءِ به."}},{"n":169,"reflection":{"text":"«لكنا عباد الله المخلصين» — كانوا يقولون: لكنّا عبادَ الله المخلصين لو جاءنا الكتاب؛ ففي هذا دعواهم الإخلاصَ التي كذّبها فعلهم؛ فاحذر دعوى الإخلاصِ بلا عمل، فالإخلاصُ يُثبَت بالعملِ لا بالدعوى، فمن ادّعى الطاعةَ لو حصل السببُ ثم قصّر عند حصوله فدعواه كاذبة، فاصدق الله في إخلاصك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"صدقُ الإخلاصِ بالعمل، والحذرُ من دعواه بلا فعل."},"action":{"text":"اعلم أنّ كفّارَ قريشٍ كانوا يقولون متمنّين: لو جاءنا كتابٌ من الله لكنّا عبادَ الله المخلصين في عبادته وطاعته «لكنا عباد الله المخلصين»؛ فلمّا جاءهم القرآنُ كذّبوا دعواهم بفعلهم، فكفروا وأعرضوا؛ فاحذر دعوى الإخلاصِ والطاعةِ بلا عملٍ ولا صدق؛ فالإخلاصُ والإيمانُ يُثبَتان بالعملِ والامتثال، لا بمجرّدِ الدعوى والتمنّي؛ فمن ادّعى أنه لو حصل له كذا لأطاع وأخلص، ثم إذا حصل السببُ قصّر وأعرض، فدعواه كاذبة؛ فلا تقل: لو كان عندي مالٌ لتصدّقت، ولو فرغت لعبدت، ثم لا تعمل بما تقدر عليه؛ فالصادقُ يصدق قوله بعمله؛ فاصدق الله في إخلاصك، وحقّقه بالعملِ والامتثال؛ فمن صدق الله صدقه الله؛ فاجعل إخلاصك ثابتًا بعملك، لا مجرّدَ دعوى؛ فالله لا يقبل إلا العملَ الخالصَ الصادق؛ فحقّق الإخلاصَ في عبادتك، واصدق فيه قولًا وعملًا؛ فالمخلصون الصادقون هم الناجون، والمدّعون الكاذبون هم الخاسرون."}},{"n":170,"reflection":{"text":"«فكفروا به فسوف يعلمون» — فكفروا بالقرآنِ لمّا جاءهم بعد أن تمنّوه، فسوف يعلمون عاقبةَ كفرهم؛ ففي هذا وعيدُ الكافرين بالعلمِ اليقيني بعاقبتهم؛ فاحذر الكفرَ بنعمةِ القرآنِ والإعراضَ عنه، فعاقبةُ الكفرِ وخيمة، فآمن بالقرآنِ واعمل به قبل أن يأتيَ يومٌ تعلم فيه عاقبةَ إعراضك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكفرِ بالقرآنِ والإعراضِ عنه، والمبادرةُ بالإيمانِ به."},"action":{"text":"اعلم أنّ كفّارَ قريشٍ لمّا جاءهم القرآنُ الذي تمنّوا مثله كفروا به وأعرضوا عنه، فتوعّدهم الله بقوله: فسوف يعلمون عاقبةَ كفرهم وإعراضهم حين ينزل بهم العذاب «فكفروا به فسوف يعلمون»؛ فهذا وعيدٌ شديدٌ للكافرين بأنهم سيعلمون سوءَ عاقبتهم علمَ اليقين؛ فاحذر الكفرَ بنعمةِ القرآنِ والإعراضَ عنه وهجرَه؛ فعاقبةُ الكفرِ والإعراضِ وخيمةٌ في الدنيا والآخرة؛ فآمن بالقرآنِ واعمل به، واتلُه وتدبّره وحكّمه في حياتك، قبل أن يأتيَ يومٌ تعلم فيه عاقبةَ إعراضك ولاتَ حينَ مناص؛ فبادر بالإيمانِ والعملِ قبل فواتِ الأوان؛ فمن آمن بالقرآنِ وعمل به فاز ونجا، ومن كفر به وأعرض عنه خسر وهلك؛ فلا تهجر القرآنَ تلاوةً وتدبّرًا وعملًا؛ فهجرُه من أعظمِ الخسران؛ فاجعل القرآنَ إمامك ودليلك وحاكمك؛ فبه النجاةُ والفوز، وبالإعراضِ عنه الهلاكُ والخسران."}}]},{"title":"الوعدُ بنصرِ الرسلِ وغلبةِ الجند، والأمرُ بالصبرِ والإعراض، وختامُ التنزيهِ والسلامِ والحمد","range":[171,182],"theme":"سبقُ كلمةِ الله لرسلِه بالنصرِ والغلبة، والأمرُ للنبيِّ بالإعراضِ عن المكذّبين وترقّبِ عاقبتهم، وإنكارُ استعجالهم العذابَ وسوءِ صباحِ المنذَرين حين ينزل، وتكرارُ الأمرِ بالصبرِ والإعراض، وختامُ السورةِ بتنزيهِ ربِّ العزّةِ عمّا يصفون، والسلامِ على المرسلين، والحمدِ لله ربِّ العالمين","verses":[{"n":171,"reflection":{"text":"«ولقد سبقت كلمتنا لعبادنا المرسلين» — ولقد سبق وعدُنا وقضاؤنا لعبادنا المرسلين بالنصرِ والغلبة؛ ففي هذا تقريرُ وعدِ الله الحقِّ بنصرِ رسلِه؛ فاعلم أنّ وعدَ الله بنصرِ أوليائه حقٌّ لا يتخلّف، فاثبت على الحقِّ وانصر دينَ الله، فالعاقبةُ لجندِ الله ولو بعد حين، فوعدُ الله لا يُخلَف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بوعدِ الله الحقِّ بنصرِ رسلِه وأوليائه."},"action":{"text":"اعلم أنّ الله قد سبق وعدُه وقضاؤه الأزليُّ لعبادِه المرسلين بالنصرِ والغلبةِ والعاقبةِ الحسنة «ولقد سبقت كلمتنا لعبادنا المرسلين»؛ فهذا وعدٌ حقٌّ من الله لا يتخلّف ولا يُخلَف؛ فاعلم أنّ وعدَ الله بنصرِ رسلِه وأوليائه حقٌّ ثابت؛ فاثبت على الحقِّ وانصر دينَ الله، وابذل ما تستطيع في نصرته؛ فالعاقبةُ والنصرُ والغلبةُ لجندِ الله وأوليائه ولو بعد استضعافٍ وشدّةٍ وتأخير؛ فلا تيأس من نصرِ الله ولو تأخّر؛ فوعدُ الله آتٍ لا محالة؛ فمن نصر الله نصره الله؛ فاجتهد في أسبابِ النصرِ من الإيمانِ والتقوى والصبرِ والإعداد؛ ثم ثق بوعدِ الله؛ فإنّ الله لا يخلف وعده؛ فكم من فترةِ استضعافٍ أعقبها نصرٌ وتمكين؛ فاصبر واثبت وتوكّل، وانتظر نصرَ الله؛ فالعاقبةُ للمتّقين، والنصرُ للمؤمنين، والغلبةُ لجندِ الله؛ فثق بوعدِ الله الحقِّ، واعمل لنصرةِ دينه."}},{"n":172,"reflection":{"text":"«إنهم لهم المنصورون» — إنّ الرسلَ وأتباعهم لهم النصرُ من الله على أعدائهم؛ ففي هذا تأكيدُ نصرِ الله لرسلِه وأوليائه؛ فاعلم أنّ النصرَ لأهلِ الإيمانِ حقٌّ، فكن من جندِ الله وأتباعِ رسلِه لتنال النصر، فمن نصر دينَ الله نصره الله وأيّده وأعلاه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بنصرِ الله لرسلِه وأتباعهم، والانضواءُ في جندِه."},"action":{"text":"اعلم أنّ الله أكّد نصرَه لرسلِه وأتباعهم على أعدائهم: إنّ الرسلَ وأتباعهم لهم النصرُ والتأييدُ من الله «إنهم لهم المنصورون»؛ فهذا وعدٌ مؤكّدٌ بنصرِ الله لأهلِ الحقِّ من رسلِه وأوليائه؛ فاعلم أنّ النصرَ لأهلِ الإيمانِ والحقِّ حقٌّ من الله؛ فالنصرُ نصران: نصرُ الحجّةِ والبيان دائمًا، ونصرُ اليدِ والسنانِ في عاقبةِ الأمر؛ فكن من جندِ الله وأتباعِ رسلِه لتنال النصرَ والتأييد؛ فمن نصر دينَ الله نصره الله وأيّده وأعزّه؛ فانصر الحقَّ بقولك وعملك وموقفك؛ فوعدُ الله بنصرِ أوليائه لا يتخلّف؛ فاثبت على الحقِّ، وانضوِ تحت رايةِ الإيمان؛ فالعزّةُ لله ولرسولِه وللمؤمنين؛ فمن كان مع الله كان الله معه، ونصره وأيّده؛ فاجعل نفسك في صفِّ المؤمنين المنصورين؛ فالنصرُ حليفُ أهلِ الإيمانِ والحقِّ ولو بعد حين؛ فثق بنصرِ الله، واعمل لدينه، وكن من جنده المنصورين."}},{"n":173,"reflection":{"text":"«وإن جندنا لهم الغالبون» — وإنّ جندنا (رسلَنا وأتباعهم) لهم الغالبون في العاقبة؛ ففي هذا تقريرُ غلبةِ جندِ الله؛ فاعلم أنّ الغلبةَ لجندِ الله في نهايةِ الأمر، فكن من جندِ الله المؤمنين لتكون من الغالبين، فالعاقبةُ للتقوى، والغلبةُ لأهلِ الإيمان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بغلبةِ جندِ الله، والانتماءُ إليهم."},"action":{"text":"اعلم أنّ الله أكّد غلبةَ جندِه من رسلِه وأتباعهم المؤمنين: وإنّ جندنا لهم الغالبون في عاقبةِ الأمرِ ونهايته «وإن جندنا لهم الغالبون»؛ فهذا وعدٌ حقٌّ بغلبةِ جندِ الله وعلوّهم؛ فاعلم أنّ الغلبةَ لجندِ الله المؤمنين في نهايةِ الأمرِ وعاقبته، وإن أُديل عليهم أحيانًا لحكمةٍ وابتلاء؛ فالعاقبةُ لهم؛ فكن من جندِ الله المؤمنين المتّقين لتكون من الغالبين؛ فالعاقبةُ للتقوى، والغلبةُ لأهلِ الإيمانِ والحق؛ فانتمِ إلى جندِ الله بالإيمانِ والطاعةِ ونصرةِ دينه؛ فلا يغرّنك ما قد يصيب أهلَ الحقِّ من شدّةٍ واستضعافٍ حينًا؛ فإنّ العاقبةَ والغلبةَ لهم؛ فاثبت مع جندِ الله، واصبر، وتوكّل، وانتظر الغلبةَ والنصر؛ فوعدُ الله لجنده بالغلبةِ لا يتخلّف؛ فمن كان من جندِ الله كان من الغالبين ولو بعد حين؛ فاجعل انتماءك وولاءك لله ولدينه ولجنده المؤمنين؛ فالغلبةُ النهائيةُ لهم بوعدِ الله الحق."}},{"n":174,"reflection":{"text":"«فتول عنهم حتى حين» — فأعرض عنهم يا محمدُ حتى وقتٍ مقدّرٍ لعذابهم؛ ففي هذا الأمرُ بالصبرِ والإعراضِ عن المكذّبين إلى حينِ الفرج؛ فاصبر على أذى المخالفين، وأعرض عن جهلهم إلى أن يأذن الله بالفرج، فالصبرُ والإعراضُ عن الجاهلين من خُلُقِ الأنبياء، فلا يستفزّنّك جهلُ الجاهلين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ والإعراضُ عن المكذّبين إلى حينِ الفرج."},"action":{"text":"اعلم أنّ الله أمر نبيَّه بالإعراضِ عن المكذّبين والصبرِ عليهم إلى وقتٍ مقدّرٍ لنصرِه ولعذابهم: فأعرض عنهم حتى حينٍ معلوم «فتول عنهم حتى حين»؛ ففي هذا الأمرُ بالصبرِ والإعراضِ عن أذى المكذّبين والجاهلين إلى أن يأذن الله بالفرجِ والنصر؛ فاصبر على أذى المخالفين والمعرضين؛ وأعرض عن جهلهم وسفههم بحلمٍ وأناة؛ فالصبرُ والإعراضُ عن الجاهلين من خُلُقِ الأنبياءِ وأتباعهم؛ «خذ العفوَ وأمر بالعرفِ وأعرض عن الجاهلين»؛ فلا يستفزّنّك جهلُ الجاهلين وأذاهم؛ ولا تقابل السفهَ بالسفه؛ بل اصبر وأعرض، وكِل أمرهم إلى الله؛ فإنّ الله كافيك وناصرك في الوقتِ الذي قدّره؛ فالأمورُ بيدِ الله يدبّرها بحكمته؛ فاصبر لحكمِ ربك، ولا تستعجل؛ فمع الصبرِ الفرج، ومع العسرِ يسر؛ فأعرض عن المؤذين، واشتغل بطاعةِ الله ودعوته، وانتظر فرجَ الله ونصره؛ فالعاقبةُ للصابرين المتوكّلين."}},{"n":175,"reflection":{"text":"«وأبصرهم فسوف يبصرون» — وانظر إليهم وترقّب ما ينزل بهم، فسوف يبصرون عاقبةَ أمرهم وما يحلّ بهم؛ ففي هذا الوعيدُ للمكذّبين والتسليةُ للنبيّ؛ فاعلم أنّ عاقبةَ المكذّبين ستظهر، فاصبر وترقّب نصرَ الله، فالعاقبةُ للحقِّ وأهله، وسوف يبصر المكذّبون سوءَ ما اختاروا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ وترقّبُ نصرِ الله وظهورِ عاقبةِ المكذّبين."},"action":{"text":"اعلم أنّ الله أمر نبيَّه أن ينظر إليهم ويترقّب ما ينزل بهم، وتوعّد المكذّبين بأنهم سوف يبصرون عاقبةَ تكذيبهم وما يحلّ بهم من العذابِ والنكال «وأبصرهم فسوف يبصرون»؛ ففي هذا وعيدٌ للمكذّبين وتسليةٌ للنبيِّ وأتباعه؛ فاعلم أنّ عاقبةَ المكذّبين المعرضين ستظهر ولا بدّ؛ فاصبر وترقّب نصرَ الله وفرجه؛ فالعاقبةُ للحقِّ وأهله، والخِزيُ والعذابُ للمكذّبين المعرضين؛ فسوف يبصر المكذّبون سوءَ ما اختاروا لأنفسهم من الكفرِ والإعراض؛ ويبصر المؤمنون نصرَ الله وتأييده؛ فلا تستعجل، واصبر لحكمِ ربك؛ فكلُّ آتٍ قريب؛ فالنصرُ مع الصبر، والفرجُ مع الكرب؛ فاثبت على الحقِّ، وترقّب وعدَ الله؛ فإنّ الله منجزٌ وعده، ناصرٌ أولياءه، مخزٍ أعداءه؛ فاجعل صبرك وترقّبك لنصرِ الله عبادةً وثقةً بوعده؛ فمن صبر وترقّب فرجَ الله ظفر به."}},{"n":176,"reflection":{"text":"«أفبعذابنا يستعجلون» — أفبعذابنا يستعجل هؤلاء المكذّبون استهزاءً وتكذيبًا؟ ففي هذا إنكارُ استعجالهم العذابَ جهلًا؛ فاحذر الاستهانةَ بوعيدِ الله والاستعجالَ به، فمن استعجل عذابَ الله جهلًا فسيندم حين يقع، فخذ الوعيدَ مأخذَ الجدِّ، ولا تستهن به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهانةِ بوعيدِ الله والاستعجالِ به."},"action":{"text":"تأمّل إنكارَ الله على المكذّبين استعجالهم العذابَ استهزاءً وتكذيبًا: أفبعذابنا يستعجل هؤلاء الجاهلون؟ «أفبعذابنا يستعجلون»؛ فهم من جهلهم وتكذيبهم يستعجلون العذابَ الذي حُذِّروا منه؛ فاحذر الاستهانةَ بوعيدِ الله والاستعجالَ به؛ فمن استعجل عذابَ الله وأمنَ مكرَه فسيندم أشدَّ الندمِ حين يقع به؛ فلا تستهن بوعيدِ الله وعقابه؛ ولا تأمن مكرَ الله؛ فلا يأمن مكرَ الله إلا القومُ الخاسرون؛ فخذ وعيدَ الله مأخذَ الجدِّ والحذر؛ واحذر أسبابَ عذابه من الكفرِ والمعاصي؛ فالعاقلُ من خاف عقابَ الله فاجتنب أسبابه، لا من استعجله واستهزأ به؛ فإذا سمعت وعيدَ الله فخف واحذر واستعدّ؛ فالعذابُ إذا نزل لم يُردّ عن القومِ المجرمين؛ فبادر بالتوبةِ والطاعةِ قبل نزوله؛ فمن استعدّ للقاءِ الله بالإيمانِ والعملِ أمِن، ومن استعجل العذابَ مستهزئًا هلك؛ فاجعل خوفك من عذابِ الله حافزًا للطاعةِ والاستعداد."}},{"n":177,"reflection":{"text":"«فإذا نزل بساحتهم فساء صباح المنذرين» — فإذا نزل العذابُ بساحتهم فبئس صباحُ الذين أُنذِروا فلم يتّعظوا؛ ففي هذا تصويرُ هولِ نزولِ العذابِ بغتة؛ فاعلم أنّ عذابَ الله إذا نزل كان مهلكًا لا مفرَّ منه، فبادر بالتوبةِ والاستعدادِ قبل نزولِه، فمن أُنذِر فأعرض فصباحه سيّئٌ حين ينزل العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتوبةِ قبل نزولِ العذاب، والاتّعاظُ بالنذارة."},"action":{"text":"تأمّل تصويرَ الله لهولِ نزولِ العذاب: فإذا نزل عذابنا بساحتهم وحلّ بديارهم فبئس صباحُ الذين أُنذِروا فلم يتّعظوا «فإذا نزل بساحتهم فساء صباح المنذرين»؛ فعذابُ الله إذا نزل بقومٍ كان مهلكًا مدمّرًا لا مفرَّ منه ولا مهرب؛ فاعلم أنّ عذابَ الله إذا حلّ بساحةِ قومٍ أنذروا فأعرضوا كان صباحَ سوءٍ وهلاك؛ فبادر بالتوبةِ والإيمانِ والاستعدادِ قبل نزولِ العذاب؛ فمن أُنذِر فأعرض ولم يتّعظ فصباحه سيّئٌ حين ينزل به العذابُ بغتة؛ فلا تؤخّر التوبةَ والاستعداد؛ فإنّ العذابَ قد يأتي بغتةً وهم لا يشعرون؛ فاجعل من نذارةِ الله لك حافزًا للمبادرةِ بالطاعةِ والتوبة؛ فالنذارةُ رحمةٌ بك لتنجو قبل فواتِ الأوان؛ فاتّعظ بها، وبادر بالعملِ الصالح؛ فمن اتّعظ بالنذارةِ نجا، ومن أعرض عنها هلك؛ فاستعدّ للقاءِ الله بالإيمانِ والتوبةِ والعملِ قبل أن يفجأك الموتُ أو العذاب؛ فالسعيدُ من اتّعظ ونجا."}},{"n":178,"reflection":{"text":"«وتول عنهم حتى حين» — فأعرض عنهم يا محمدُ حتى وقتٍ مقدّر (تأكيدٌ للأمرِ الأول)؛ ففي هذا تأكيدُ الأمرِ بالصبرِ والإعراض؛ فاصبر واثبت على الإعراضِ عن أذى المكذّبين إلى أن يأذن الله بالفرج، فالصبرُ على المكارهِ حتى يأتيَ الفرجُ من شيمِ الأنبياء، فلا تضجر من طولِ الانتظار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الصبرِ والإعراضِ حتى يأتيَ الفرج."},"action":{"text":"اعلم أنّ الله كرّر الأمرَ لنبيّه بالإعراضِ عن المكذّبين والصبرِ عليهم إلى حينٍ مقدّر، تأكيدًا وتثبيتًا: وأعرض عنهم حتى حينٍ معلوم «وتول عنهم حتى حين»؛ ففي هذا التكرارِ تأكيدٌ للأمرِ بالصبرِ والإعراضِ وتثبيتٌ عليه؛ فاصبر واثبت على الإعراضِ عن أذى المكذّبين والمعرضين إلى أن يأذن الله بالفرجِ والنصر؛ فالصبرُ على المكارهِ والأذى حتى يأتيَ الفرجُ من شيمِ الأنبياءِ وأتباعهم؛ فلا تضجر من طولِ الانتظار، ولا تستعجل الفرج؛ فإنّ الفرجَ آتٍ في وقتِه الذي قدّره الله بحكمته؛ فاثبت على الحقِّ، واصبر على الأذى، وأعرض عن الجاهلين؛ وكِل أمرك وأمرهم إلى الله؛ فمن صبر ظفر، ومن ثبت نصر؛ فالصبرُ مفتاحُ الفرج؛ فاجعل صبرك وثباتك ثقةً بوعدِ الله وحسنَ ظنٍّ به؛ فإنّ مع العسرِ يسرًا، إنّ مع العسرِ يسرًا؛ فاصبر لحكمِ ربك، فإنك بأعيننا؛ فالعاقبةُ الحسنةُ للصابرين الثابتين المتوكّلين على الله."}},{"n":179,"reflection":{"text":"«وأبصر فسوف يبصرون» — وانظر وترقّب، فسوف يبصرون عاقبتهم (تأكيد)؛ ففي هذا تأكيدُ الوعيدِ للمكذّبين والتسليةِ للنبيّ؛ فاصبر وترقّب نصرَ الله وظهورَ عاقبةِ المكذّبين، فوعدُ الله حقٌّ لا محالة، وسوف يبصر المكذّبون سوءَ عاقبتهم، والمؤمنون نصرَ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ وترقّبُ نصرِ الله وظهورِ العاقبة."},"action":{"text":"اعلم أنّ الله كرّر الأمرَ لنبيّه بالنظرِ والترقّب، وأكّد وعيدَ المكذّبين: وأبصر ما ينزل بهم، فسوف يبصرون عاقبةَ أمرهم وما يحلّ بهم «وأبصر فسوف يبصرون»؛ ففي هذا التكرارِ تأكيدٌ للوعيدِ للمكذّبين وتسليةٌ للنبيِّ وأتباعه وتثبيتٌ لهم؛ فاصبر وترقّب نصرَ الله وفرجه وظهورَ عاقبةِ المكذّبين؛ فوعدُ الله حقٌّ لا محالة، وآتٍ لا ريب فيه؛ فسوف يبصر المكذّبون سوءَ عاقبةِ ما اختاروا من الكفرِ والإعراض؛ ويبصر المؤمنون نصرَ الله وتأييده وحسنَ العاقبة؛ فلا تستعجل، واصبر لحكمِ ربك؛ فكلُّ ما هو آتٍ قريب؛ فالنصرُ مع الصبر؛ فاثبت على الحقِّ، وترقّب موعودَ الله بثقةٍ ويقين؛ فإنّ الله لا يخلف الميعاد؛ فمن صبر وترقّب فرجَ الله ونصره ظفر به عاجلًا أو آجلًا؛ فاجعل صبرك وترقّبك عبادةً وثقةً بوعدِ الله الحق؛ فالعاقبةُ للمتّقين، والنصرُ للمؤمنين الصابرين."}},{"n":180,"reflection":{"text":"«سبحان ربك رب العزة عما يصفون» — تنزيهًا لربّك ربِّ العزّةِ والغلبةِ عمّا يصفه به المشركون من النقصِ والولدِ والشريك؛ ففي هذا ختامُ السورةِ بتنزيهِ الله وتعظيمِه؛ فنزّه ربّك ربَّ العزّةِ عن كلِّ ما لا يليق به، وأكثر من تسبيحه وتعظيمه، فالعزّةُ كلُّها لله، فاطلب العزّةَ من مصدرها، ونزّه ربّك الأعزّ عن كلِّ نقص.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ ربِّ العزّةِ وتعظيمُه، وطلبُ العزّةِ منه وحده."},"action":{"text":"تأمّل ختامَ السورةِ بتنزيهِ الله وتعظيمه: تنزيهًا لربّك ربِّ العزّةِ والغلبةِ والقهرِ عمّا يصفه به المشركون من النقصِ والولدِ والشريكِ وكلِّ ما لا يليق به «سبحان ربك رب العزة عما يصفون»؛ فربّك هو ربُّ العزّةِ ومالكها ومصدرها؛ فله العزّةُ جميعًا؛ فنزّه ربّك ربَّ العزّةِ عن كلِّ ما لا يليق بجلالِه وكماله؛ وأكثر من تسبيحه وتعظيمه وتنزيهه؛ فالعزّةُ كلُّها لله ولرسولِه وللمؤمنين؛ فاطلب العزّةَ من مصدرها، وهو الله ربُّ العزّة؛ فمن ابتغى العزّةَ عند الله أعزّه، ومن ابتغاها عند غيره أذلّه الله؛ فالعزّةُ في طاعةِ الله والتوحيدِ والاعتصامِ به، لا في معصيتِه واتّباعِ الهوى؛ فنزّه ربّك، وعظّمه، وأخلص له العبادة؛ واطلب العزّةَ بالإيمانِ والطاعةِ والتوحيد؛ فمن أطاع الله عزّ، ومن عصاه ذلّ؛ فاجعل تسبيحك وتنزيهك لربِّ العزّةِ دأبك؛ فبتعظيمِ الله وتنزيهِه وطاعتِه تنال العزّةَ في الدنيا والآخرة."}},{"n":181,"reflection":{"text":"«وسلام على المرسلين» — وسلامٌ وأمانٌ وثناءٌ من الله على جميعِ المرسلين؛ ففي هذا الثناءُ على الرسلِ جميعًا وتكريمُهم؛ فأحبَّ رسلَ الله جميعًا، وسلّم عليهم، واتّبع ما جاؤوا به من الحق، فمحبّةُ الرسلِ واتّباعهم من الدين، فاجعل الصلاةَ والسلامَ عليهم من عبادتك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"محبّةُ الرسلِ والسلامُ عليهم واتّباعُ ما جاؤوا به."},"action":{"text":"تأمّل ثناءَ الله على رسلِه جميعًا في ختامِ السورة: وسلامٌ وأمانٌ وتحيّةٌ وثناءٌ من الله على جميعِ المرسلين الذين بلّغوا رسالاتِ ربهم وصبروا «وسلام على المرسلين»؛ ففي هذا الثناءُ على الرسلِ جميعًا وتكريمُهم وتزكيتهم؛ فأحبَّ رسلَ الله جميعًا، وأثنِ عليهم، وسلّم عليهم؛ واتّبع ما جاؤوا به من الحقِّ والهدى؛ فمحبّةُ الرسلِ وتوقيرهم واتّباعهم من أصولِ الدين؛ فاجعل الصلاةَ والسلامَ على الأنبياءِ والمرسلين من عبادتك وقربتك؛ ولا سيّما على خاتمهم وسيّدهم محمدٍ ﷺ؛ فأكثر من الصلاةِ عليه؛ فمن صلّى عليه صلاةً صلّى الله عليه بها عشرًا؛ فوقّر رسلَ الله، واقتدِ بهم في الدعوةِ والصبرِ والإخلاص؛ فهم صفوةُ الله وسفراؤه إلى خلقه؛ فالسلامُ عليهم تكريمٌ لهم وتقرّبٌ إلى الله بمحبّتهم؛ فاجعل قلبك مملوءًا بمحبّةِ الرسلِ وتوقيرهم واتّباعهم؛ فبمحبّتهم واتّباعهم تنال محبّةَ الله ورضاه."}},{"n":182,"reflection":{"text":"«والحمد لله رب العالمين» — والحمدُ لله ربِّ العالمين على نعمِه كلِّها، وعلى نصرِ أوليائه وهلاكِ أعدائه؛ ففي هذا ختامُ السورةِ بحمدِ الله وتعظيمه؛ فاحمد الله في كلِّ حالٍ على نعمه وأفضاله، فالحمدُ لله أولًا وآخرًا وظاهرًا وباطنًا، فاجعل الحمدَ لله ديدنك، فهو المستحقُّ للحمدِ كلِّه ربُّ العالمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"حمدُ الله على نعمِه كلِّها، وجعلُ الحمدِ ديدنًا."},"action":{"text":"تأمّل ختامَ السورةِ بحمدِ الله وتعظيمه: والحمدُ لله ربِّ العالمين على نعمِه كلِّها الدينيةِ والدنيوية، وعلى قضائه وقدره، وعلى نصرِ أوليائه وهلاكِ أعدائه «والحمد لله رب العالمين»؛ فختم الله السورةَ بالحمدِ كما بدأ الخلقَ والأمرَ به؛ فالحمدُ لله على كلِّ حال؛ فاحمد الله في السرّاءِ والضرّاء، على النعمةِ والبلاء، على العطاءِ والمنع؛ فالحمدُ لله أولًا وآخرًا، وظاهرًا وباطنًا؛ فهو المستحقُّ للحمدِ كلِّه، ربُّ العالمين وخالقهم ورازقهم ومدبّرهم؛ فاجعل الحمدَ لله ديدنك وعادتك في كلِّ أحوالك؛ فأكثر من حمدِ الله وشكره؛ فالحمدُ رأسُ الشكر؛ ومن حمد الله على نعمه استوجب المزيد؛ فأهلُ الجنّةِ آخرُ دعواهم أن الحمدُ لله ربِّ العالمين؛ فتعوّد الحمدَ في الدنيا لتكون من الحامدين في الآخرة؛ فاجعل لسانك وقلبك عامرًا بحمدِ الله وتعظيمه وشكرِه؛ فالحمدُ لله الذي بنعمتِه تتمّ الصالحات؛ فله الحمدُ في الأولى والآخرة، وله الحكمُ وإليه ترجعون."}}]}],"coverage":{"covered":182,"total":182}};
